const RUSSIAN_DICTIONARY_INDEX = Object.freeze([{"cat":"alphabet","catLabel":"ALFABETO","primary":"А а","secondary":"[ A ] Vogal","desc":"Igual ao 'A' em português. Pronúncia aberta como em 'água'. — Exemplo: Автобус (Ônibus)","audio":"А","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Б б","secondary":"[ B ] Consoante","desc":"Tem som de 'B' como em 'bola'. Note a barra no topo parecendo um boné. — Exemplo: Бабушка (Avó)","audio":"Б","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"В в","secondary":"[ V ] Consoante","desc":"⚠️ Falso Cognato Visual! Parece um 'B', mas tem som de 'V' como em 'vinho'. — Exemplo: Вода (Água)","audio":"В","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Г г","secondary":"[ G ] Consoante","desc":"Som de 'G' duro como em 'gato' ou 'gol'. Formato de ganchinho. — Exemplo: Город (Cidade)","audio":"Г","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Д д","secondary":"[ D ] Consoante","desc":"Derivada do Delta grego. Som de 'D' como em 'dado'. — Exemplo: Дом (Casa / Lar)","audio":"Д","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Е е","secondary":"[ YE / E ] Vogal Suave","desc":"Soa como 'iê' no início de palavras ou após vogais. Suafiza consoantes anteriores. — Exemplo: Еда (Comida)","audio":"Е","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ё ё","secondary":"[ YO ] Vogal Suave","desc":"Soa como 'ió' (sempre tônica). Os dois pontos sobre a letra marcam a tônica. — Exemplo: Ёлка (Árvore de Natal / Pinheiro)","audio":"Ё","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ж ж","secondary":"[ ZH ] Consoante","desc":"Som de 'J' forte e chiado como em 'janela' ou 'jornal'. Formato de besouro. — Exemplo: Журнал (Revista)","audio":"Ж","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"З з","secondary":"[ Z ] Consoante","desc":"Som de 'Z' como em 'zebra'. Lembra o número 3 desenhado de lado. — Exemplo: Зима (Inverno)","audio":"З","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"И и","secondary":"[ I ] Vogal Suave","desc":"Som de 'I' como em 'ilha'. Parece um 'N' latino invertido. — Exemplo: Изучать (Estudar)","audio":"И","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Й й","secondary":"[ Y (I curto) ] ","desc":"Semivogal curta 'i'. Forma ditongos como em 'май' (mai). — Exemplo: Chai (Чай) (Chá)","audio":"Й","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"К к","secondary":"[ K ] Consoante","desc":"Idêntico ao 'K' latino. Som seco de 'K' como em 'kiwi'. — Exemplo: Книга (Livro)","audio":"К","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Л л","secondary":"[ L ] Consoante","desc":"Som de 'L' palatal ou velar como em 'lua' ou 'lago'. Formato de tenda. — Exemplo: Лето (Verão)","audio":"Л","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"М м","secondary":"[ M ] Consoante","desc":"Idêntico ao 'M' em português. Lembre de 'Мама' (Mãe). — Exemplo: Мама (Mãe)","audio":"М","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Н н","secondary":"[ N ] Consoante","desc":"⚠️ Falso Cognato Visual! Parece um 'H', mas tem som de 'N' de 'navio'. — Exemplo: Ночь (Noite)","audio":"Н","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"О о","secondary":"[ O ] Vogal","desc":"Igual ao 'O' latino. Quando tônico soa 'Ó', quando átono soa suave 'A'. — Exemplo: Окно (Janela)","audio":"О","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"П п","secondary":"[ P ] Consoante","desc":"Derivada do Pi grego (П). Som seco de 'P' de 'pato'. — Exemplo: Привет (Olá / Oi)","audio":"П","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Р р","secondary":"[ R ] Consoante","desc":"⚠️ Falso Cognato Visual! Parece um 'P', mas tem som de 'R' vibrante. — Exemplo: Работа (Trabalho)","audio":"Р","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"С с","secondary":"[ S ] Consoante","desc":"⚠️ Falso Cognato Visual! Parece um 'C', mas tem som de 'S' de 'sol'. — Exemplo: Спасибо (Obrigado)","audio":"С","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Т т","secondary":"[ T ] Consoante","desc":"Idêntico ao 'T' latino. Som firme de 'T' de 'táxi'. — Exemplo: Такси (Táxi)","audio":"Т","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"У у","secondary":"[ U ] Vogal","desc":"⚠️ Falso Cognato Visual! Parece um 'Y', mas tem som de 'U' de 'uva'. — Exemplo: Утро (Manhã)","audio":"У","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ф ф","secondary":"[ F ] Consoante","desc":"Derivada do Phi grego (Ф). Som de 'F' como em 'foto'. — Exemplo: Фильм (Filme)","audio":"Ф","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Х х","secondary":"[ KH ] Consoante","desc":"Som de 'R' forte e raspado como em 'carro' ou 'khleb' (pão). — Exemplo: Хлеб (Pão)","audio":"Х","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ц ц","secondary":"[ TS ] Consoante","desc":"Som de 'TS' conjunto como em 'tsunami' ou 'pizza'. Note o pezinho no canto. — Exemplo: Центр (Centro)","audio":"Ц","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ч ч","secondary":"[ CH ] Consoante","desc":"Som de 'TCH' de 'tchau' ou 'chocolate'. Lembra o número 4 invertido. — Exemplo: Час (Hora)","audio":"Ч","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ш ш","secondary":"[ SH ] Consoante","desc":"Som de 'CH' de 'chá' ou 'xícara'. Consoante dura e soprada. — Exemplo: Школа (Escola)","audio":"Ш","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Щ щ","secondary":"[ SCH ] Consoante Suave","desc":"Som suave e palatal de 'SH' prolongado (como em 'sushi'). Possui pezinho. — Exemplo: Борщ (Borsch (Sopa tradicional))","audio":"Щ","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ъ ъ","secondary":"[ Sinal Duro ] Sinal Ortográfico","desc":"Não possui som próprio. Impede a palatização da consoante anterior. — Exemplo: Объект (Objeto)","audio":"Ъ","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ы ы","secondary":"[ YI (I gutural) ] Vogal Central","desc":"Som gutural fundo produzido no fundo da garganta com dentes cerrados. — Exemplo: Мы (Nós)","audio":"Ы","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ь ь","secondary":"[ Sinal Suave ] Sinal Ortográfico","desc":"Não tem som. Palatiza e suaviza a consoante que a antecede (som molhado). — Exemplo: День (Dia)","audio":"Ь","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Э э","secondary":"[ E (aberto) ] Vogal","desc":"Som de 'É' aberto como em 'éla' ou 'época'. — Exemplo: Это (Isto / Este)","audio":"Э","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Ю ю","secondary":"[ YU ] Vogal Suave","desc":"Soa como 'iú' de 'universo'. Combinação do som I + U. — Exemplo: Юг (Sul)","audio":"Ю","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"alphabet","catLabel":"ALFABETO","primary":"Я я","secondary":"[ YA ] Vogal Suave","desc":"Soa como 'iá' de 'iatismo'. Significa também o pronome 'Eu' (Я). — Exemplo: Яблоко (Maçã)","audio":"Я","level":"A1","module":"Alfabeto Cirílico (Кириллица)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Здравствуйте","secondary":"[ Zdravstvuyte ] — Olá / Como vai? (Formal)","desc":"Exemplo: \"Здравствуйте, меня зовут Анна.\"","audio":"Здравствуйте","level":"A1","module":"Saudações"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Привет","secondary":"[ Privet ] — Oi / Olá (Informal)","desc":"Exemplo: \"Привет! Как дела?\"","audio":"Привет","level":"A1","module":"Saudações"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Спасибо","secondary":"[ Spasibo ] — Obrigado(a)","desc":"Exemplo: \"Большое спасибо за помощь!\"","audio":"Спасибо","level":"A1","module":"Cortesia"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пожалуйста","secondary":"[ Pozhaluysta ] — Por favor / De nada","desc":"Exemplo: \"Скажите, пожалуйста, где метро?\"","audio":"Пожалуйста","level":"A1","module":"Cortesia"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"До свидания","secondary":"[ Do svidaniya ] — Até logo / Adeus","desc":"Exemplo: \"До свидания! До завтра!\"","audio":"До свидания","level":"A1","module":"Saudações"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Меня зовут...","secondary":"[ Menya zovut... ] — Meu nome é...","desc":"Exemplo: \"Меня зовут Виктор.\"","audio":"Меня зовут...","level":"A1","module":"Apresentações"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Очень приятно","secondary":"[ Ochen priyatno ] — Muito prazer","desc":"Exemplo: \"Очень приятно с вами познакомиться!\"","audio":"Очень приятно","level":"A1","module":"Apresentações"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Семья","secondary":"[ Sem'ya ] — Família","desc":"Exemplo: \"Моя семья очень дружная.\"","audio":"Семья","level":"A1","module":"Família"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Отец","secondary":"[ Otets ] — Pai","desc":"Exemplo: \"Мой отец работает инженером.\"","audio":"Отец","level":"A1","module":"Família"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мать","secondary":"[ Mat' ] — Mãe","desc":"Exemplo: \"Моя мать очень хорошо готовит.\"","audio":"Мать","level":"A1","module":"Família"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Друг","secondary":"[ Drug ] — Amigo","desc":"Exemplo: \"Иван — мой лучший друг.\"","audio":"Друг","level":"A1","module":"Relacionamentos"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Город","secondary":"[ Gorod ] — Cidade","desc":"Exemplo: \"Москва — красивый город.\"","audio":"Город","level":"A1","module":"Cidade"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Улица","secondary":"[ Ulitsa ] — Rua","desc":"Exemplo: \"Мы живём на этой улице.\"","audio":"Улица","level":"A1","module":"Cidade"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дом","secondary":"[ Dom ] — Casa / Edifício","desc":"Exemplo: \"Наш дом находится в центре.\"","audio":"Дом","level":"A1","module":"Habitação"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вода","secondary":"[ Vada ] — Água","desc":"Exemplo: \"Принесите, пожалуйста, воду.\"","audio":"Вода","level":"A1","module":"Alimentação"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Хлеб","secondary":"[ Khleb ] — Pão","desc":"Exemplo: \"Свежий хлеб очень вкусный.\"","audio":"Хлеб","level":"A1","module":"Alimentação"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ресторан","secondary":"[ Restaran ] — Restaurante","desc":"Exemplo: \"Мы ужинаем в ресторане.\"","audio":"Ресторан","level":"A1","module":"Alimentação"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Работа","secondary":"[ Rabota ] — Trabalho / Emprego","desc":"Exemplo: \"Моя работа интересная и важная.\"","audio":"Работа","level":"A2","module":"Trabalho"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Время","secondary":"[ Vremya ] — Tempo / Hora","desc":"Exemplo: \"Который час? У нас мало времени.\"","audio":"Время","level":"A2","module":"Tempo"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Путешествие","secondary":"[ Puteshestviye ] — Viagem","desc":"Exemplo: \"Путешествие по России было незабываемым.\"","audio":"Путешествие","level":"A2","module":"Turismo"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Билет","secondary":"[ Bilet ] — Ingresso / Passagem","desc":"Exemplo: \"Я купил билет на поезд в Санкт-Петербург.\"","audio":"Билет","level":"A2","module":"Turismo"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Аэропорт","secondary":"[ Aeroport ] — Aeroporto","desc":"Exemplo: \"Самолет прилетает в аэропорт.\"","audio":"Аэропорт","level":"A2","module":"Transporte"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Свобода","secondary":"[ Svoboda ] — Liberdade","desc":"Exemplo: \"Свобода слова является важным принципом.\"","audio":"Свобода","level":"B1","module":"Sociedade"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Развитие","secondary":"[ Razvitiye ] — Desenvolvimento","desc":"Exemplo: \"Экономическое развитие страны ускоряется.\"","audio":"Развитие","level":"B1","module":"Educação"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Образование","secondary":"[ Obrazovaniye ] — Educação / Ensino","desc":"Exemplo: \"Высшее образование открывает новые возможности.\"","audio":"Образование","level":"B1","module":"Educação"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сотрудничество","secondary":"[ Sotrudnichestvo ] — Cooperação / Parceria","desc":"Exemplo: \"Мы надеемся на долгосрочное взаимовыгодное сотрудничество.\"","audio":"Сотрудничество","level":"B2","module":"Negócios"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Законодательство","secondary":"[ Zakonodatel'stvo ] — Legislação / Direito","desc":"Exemplo: \"Новое законодательство вступает в силу с следующего месяца.\"","audio":"Законодательство","level":"B2","module":"Jurídico"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Искусственный интеллект","secondary":"[ Iskusstvennyy intellekt ] — Inteligência Artificial","desc":"Exemplo: \"Развитие искусственного интеллекта меняет рынок труда.\"","audio":"Искусственный интеллект","level":"B2","module":"Tecnologia"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Именительный падеж (Caso Nominativo)","secondary":"Sujeito da oração (Кто? Что? - Quem? O quê?)","desc":"É a forma inicial/dicionário do substantivo sem declinação. Indica o sujeito que executa a ação principal da frase.","context":"Exemplo: \"Студент читает книгу. (O estudante lê um livro.)\"","audio":"Именительный","level":"A1","module":"Casos Gramaticais"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Винительный падеж (Caso Acusativo)","secondary":"Objeto Direto (Кого? Что? - Quem? O quê?)","desc":"Indica o objeto direto afetado pela ação transitiva ou o destino de movimento (в / на + Acusativo).","context":"Exemplo: \"Я люблю музыку. Я иду в парк.\"","audio":"Винительный","level":"A1","module":"Casos Gramaticais"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Предложный падеж (Caso Preposicional)","secondary":"Localização e Assunto (О ком? О чём? Где? - Onde? Sobre o quê?)","desc":"Sempre precedido por preposição (в, на, о/об). Usado para indicar localização estática e tema de conversa.","context":"Exemplo: \"Я живу в Москве. Мы говорим о работе.\"","audio":"Предложный","level":"A1","module":"Casos Gramaticais"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Родительный падеж (Caso Genitivo)","secondary":"Posse, Ausência e Quantidade (Кому? Чего? У кого? - De quem? Sem o quê?)","desc":"Indica posse (livro do professor), negação com НЕТ (нет времени) e numerais (2, 3, 4 + genitivo singular; 5+ genitivo plural).","context":"Exemplo: \"У меня нет машины. Это книга анны.\"","audio":"Родительный","level":"A2","module":"Casos Gramaticais"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Дательный падеж (Caso Dativo)","secondary":"Objeto Indireto e Idade (Кому? Чему? - Para quem? A quem?)","desc":"Indica o receptor da ação, destinatário de mensagens/presentes e expressão de idade (Мне 20 лет).","context":"Exemplo: \"Я звоню другу. Мне тридцать лет.\"","audio":"Дательный","level":"A2","module":"Casos Gramaticais"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Творительный падеж (Caso Instrumental)","secondary":"Instrumento e Companhia (Кем? Чем? С кем? - Com o quê? Com quem?)","desc":"Indica o instrumento utilizado para realizar uma ação, profissão com o verbo ser/estar no passado (работать/быть + Instrumental) ou companhia com С.","context":"Exemplo: \"Я пишу ручкой. Я работаю врачом. Мы с другом ужинаем.\"","audio":"Творительный","level":"B1","module":"Casos Gramaticais"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Виды глагола (Aspectos Verbais: НСВ vs СВ)","secondary":"Imperfeito (НСВ - Processo/Hábito) vs Perfeito (СВ - Resultado)","desc":"Em russo, os verbos possuem dois aspectos: Imperfeito (processo contínuo, hábito, repetição) e Perfeito (ação concluída com resultado pontual único).","context":"Exemplo: \"Я долго читал книгу (НСВ - processo) vs Я прочитал книгу (СВ - resultado concluído).\"","audio":"Виды","level":"B1","module":"Verbos"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Причастие (Particípios em Russo)","secondary":"Adjetivos Verbais (Ativos -ущ-/-вш- e Passivos -енн-/-т-)","desc":"Particípios modificam substantivos conectando ação e qualidade. Podem ser ativos (quem faz) ou passivos (quem sofre a ação).","context":"Exemplo: \"Студент, читающий книгу (O estudante que está lendo a livro).\"","audio":"Причастие","level":"B2","module":"Sintaxe Avançada"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Деепричастие (Gerúndios em Russo)","secondary":"Advérbios Verbais (-а/-я no Imperfeito e -в/-вши no Perfeito)","desc":"Indica uma ação secundária simultânea ou anterior realizada pelo mesmo sujeito da frase principal.","context":"Exemplo: \"Читая книгу, я пил кофе. (Lendo o livro, eu bebia café.)\"","audio":"Деепричастие","level":"B2","module":"Sintaxe Avançada"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Здравствуйте vs. Привет","secondary":"Здравствуйте (Formal) / Привет (Informal)","desc":"Em russo, a cortesia depende do grau de formalidade. Use a saudação formal com pessoas mais velhas ou desconhecidos e a informal entre amigos.","context":"Ex: \"Здравствуйте, Anna! / Привет, Ivan! — \"Olá, Anna! / Oi, Ivan!\"\"","audio":"Здравствуйте vs. Привет","level":"A1","module":"Módulo 1: Здравствуйте! (Saudações e Cortesia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Cortesia Básica","secondary":"Спасибо ➔ Пожалуйста (De nada)","desc":"A expressão \"Пожалуйста\" é multifuncional e serve tanto para pedir cortesia quanto para responder a um agradecimento.","context":"Ex: \"Кофе, пожалуйста. — Спасибо! — \"Café, por favor. — Obrigado(a)!\"\"","audio":"Cortesia Básica","level":"A1","module":"Módulo 1: Здравствуйте! (Saudações e Cortesia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura Меня зовут...","secondary":"Меня зовут + [Seu Nome]","desc":"Toda apresentação pessoal em russo usa a estrutura \"Меня зовут\" (literalmente \"Me chamam de...\").","context":"Ex: \"Меня зовут Игорь. — \"Meu nome é Igor.\"\"","audio":"Estrutura Меня зовут...","level":"A1","module":"Módulo 2: Меня зовут... (Apresentações)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntando o Nome","secondary":"Как вас зовут? (Formal) / Как тебя зовут? (Informal)","desc":"Para perguntar o nome de alguém, diferencie a forma formal da informal.","context":"Ex: \"Как вас зовут? — Меня зовут Анна. — \"Como você se chama? — Meu nome é Anna.\"\"","audio":"Perguntando o Nome","level":"A1","module":"Módulo 2: Меня зовут... (Apresentações)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Меня зовут","secondary":"[ Menya zovut ] — Meu nome é...","desc":"","audio":"Меня зовут","level":"A1","module":"Módulo 2: Меня зовут... (Apresentações)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Как вас зовут?","secondary":"[ Kak vas zovut? ] — Como você se chama? (formal)","desc":"","audio":"Как вас зовут?","level":"A1","module":"Módulo 2: Меня зовут... (Apresentações)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Как тебя зовут?","secondary":"[ Kak tebya zovut? ] — Como você se chama? (informal)","desc":"","audio":"Как тебя зовут?","level":"A1","module":"Módulo 2: Меня зовут... (Apresentações)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Pronome Demonstrativo Это","secondary":"Это + [Substantivo]","desc":"Em russo, \"Это\" funciona como pronome demonstrativo universal (Isto é / Este é / Esta é) sem mudar por gênero.","context":"Ex: \"Это кот. Это книга. — \"Isto é um gato. Isto é um livro.\"\"","audio":"O Pronome Demonstrativo Это","level":"A1","module":"Módulo 3: Кто это? Что это? (Identificação de Pessoas e Objetos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Кто vs. Что","secondary":"Кто это? (Pessoas/Animais) / Что это? (Objetos)","desc":"Usa-se \"Кто\" exclusivamente para seres animados (pessoas e animais) e \"Что\" para objetos inanimados.","context":"Ex: \"Кто это? — Это врач. / Что это? — Это книга. — \"Quem é este? — É um médico. / O que é isto? — É um livro.\"\"","audio":"Кто vs. Что","level":"A1","module":"Módulo 3: Кто это? Что это? (Identificação de Pessoas e Objetos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Кто","secondary":"[ Kto ] — Quem","desc":"","audio":"Кто","level":"A1","module":"Módulo 3: Кто это? Что это? (Identificação de Pessoas e Objetos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Что","secondary":"[ Shto ] — O que / Que","desc":"","audio":"Что","level":"A1","module":"Módulo 3: Кто это? Что это? (Identificação de Pessoas e Objetos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Это","secondary":"[ Eto ] — Isto / Este / Esta","desc":"","audio":"Это","level":"A1","module":"Módulo 3: Кто это? Что это? (Identificação de Pessoas e Objetos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Кто это?","secondary":"[ Kto eto? ] — Quem é este(a)?","desc":"","audio":"Кто это?","level":"A1","module":"Módulo 3: Кто это? Что это? (Identificação de Pessoas e Objetos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Что это?","secondary":"[ Shto eto? ] — O que é isto?","desc":"","audio":"Что это?","level":"A1","module":"Módulo 3: Кто это? Что это? (Identificação de Pessoas e Objetos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Preposição Из + Genitivo","secondary":"Я из + [País no Genitivo]","desc":"Para dizer de qual país você é, usa-se a preposição Из seguida do nome do país no Caso Genitivo.","context":"Ex: \"Я из Бразилии. / Он из России. — \"Eu sou do Brasil. / Ele é da Rússia.\"\"","audio":"A Preposição Из + Genitivo","level":"A1","module":"Módulo 4: Я из Бразилии (Países e Nacionalidades)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntando a Origem","secondary":"Откуда вы? (Formal) / Откуда ты? (Informal)","desc":"Para perguntar de onde alguém é, use Откуда com a pessoa correspondente.","context":"Ex: \"Откуда вы? — Я из Бразилии. — \"De onde você é? — Eu sou do Brasil.\"\"","audio":"Perguntando a Origem","level":"A1","module":"Módulo 4: Я из Бразилии (Países e Nacionalidades)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Откуда","secondary":"[ Otkuda ] — De onde","desc":"","audio":"Откуда","level":"A1","module":"Módulo 4: Я из Бразилии (Países e Nacionalidades)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Бразилия","secondary":"[ Braziliya ] — Brasil","desc":"","audio":"Бразилия","level":"A1","module":"Módulo 4: Я из Бразилии (Países e Nacionalidades)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Россия","secondary":"[ Rossiya ] — Rússia","desc":"","audio":"Россия","level":"A1","module":"Módulo 4: Я из Бразилии (Países e Nacionalidades)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Из","secondary":"[ Iz ] — De / Vindo de","desc":"","audio":"Из","level":"A1","module":"Módulo 4: Я из Бразилии (Países e Nacionalidades)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Concordância de Possessivos","secondary":"Мой (Masc) / Моя (Fem) / Моё (Neutro) / Мои (Plural)","desc":"Os pronomes possessivos em russo concordam em gênero e número com o objeto possuído.","context":"Ex: \"Это мой брат и моя сестра. — \"Este é meu irmão e esta é minha irmã.\"\"","audio":"Concordância de Possessivos","level":"A1","module":"Módulo 5: Моя семья (Família e Possessivos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Possessivos de Segunda Pessoa","secondary":"Твой (Masc) / Твоя (Fem) / Твоё (Neutro) / Твои (Plural)","desc":"Assim como \"Мой\", o possessivo \"Твой\" concorda com o substantivo.","context":"Ex: \"Где твой дом? — \"Onde fica sua casa?\"\"","audio":"Possessivos de Segunda Pessoa","level":"A1","module":"Módulo 5: Моя семья (Família e Possessivos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мама","secondary":"[ Mama ] — Mãe","desc":"","audio":"Мама","level":"A1","module":"Módulo 5: Моя семья (Família e Possessivos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Папа","secondary":"[ Papa ] — Pai","desc":"","audio":"Папа","level":"A1","module":"Módulo 5: Моя семья (Família e Possessivos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Брат","secondary":"[ Brat ] — Irmão","desc":"","audio":"Брат","level":"A1","module":"Módulo 5: Моя семья (Família e Possessivos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сестра","secondary":"[ Sestra ] — Irmã","desc":"","audio":"Сестра","level":"A1","module":"Módulo 5: Моя семья (Família e Possessivos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Omissão do Verbo SER","secondary":"[Pronome] + [Profissão]","desc":"No presente em russo, o verbo SER (быть) é completamente omitido entre o pronome e a profissão.","context":"Ex: \"Я студент. / Она врач. — \"Eu sou estudante. / Ela é médica.\"\"","audio":"Omissão do Verbo SER","level":"A1","module":"Módulo 6: Профессии (Profissões e Trabalho)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntando a Profissão","secondary":"Кто вы по профессии?","desc":"A pergunta educada padrão para saber a ocupação de alguém.","context":"Ex: \"Кто вы по профессии? — Я инженер. — \"Qual é sua profissão? — Eu sou engenheiro.\"\"","audio":"Perguntando a Profissão","level":"A1","module":"Módulo 6: Профессии (Profissões e Trabalho)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Врач","secondary":"[ Vrach ] — Médico(a)","desc":"","audio":"Врач","level":"A1","module":"Módulo 6: Профессии (Profissões e Trabalho)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Учитель","secondary":"[ Uchitel ] — Professor(a)","desc":"","audio":"Учитель","level":"A1","module":"Módulo 6: Профессии (Profissões e Trabalho)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Инженер","secondary":"[ Inzhener ] — Engenheiro(a)","desc":"","audio":"Инженер","level":"A1","module":"Módulo 6: Профессии (Profissões e Trabalho)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Студент","secondary":"[ Student ] — Estudante (masc)","desc":"","audio":"Студент","level":"A1","module":"Módulo 6: Профессии (Profissões e Trabalho)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Caso Preposicional (Localização)","secondary":"В/НА + [Substantivo + е]","desc":"Para responder a \"Где?\" (Onde?), os substantivos masculinos e femininos geralmente recebem a terminação -е.","context":"Ex: \"Москва ➔ в Москве / Город ➔ в городе — \"em Moscou / na cidade\"\"","audio":"O Caso Preposicional (Localização)","level":"A1","module":"Módulo 7: Где ты живешь? (Caso Preposicional I - Lugares)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Diferença entre В e НА","secondary":"В [Cidade/Prédio] / НА [Rua/Praça]","desc":"Usa-se В para cidades e espaços fechados e НА para ruas, praças e espaços abertos.","context":"Ex: \"Я живу в Москве на улице Тверская. — \"Eu moro em Moscou na rua Tverskaya.\"\"","audio":"Diferença entre В e НА","level":"A1","module":"Módulo 7: Где ты живешь? (Caso Preposicional I - Lugares)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Где","secondary":"[ Gde ] — Onde","desc":"","audio":"Где","level":"A1","module":"Módulo 7: Где ты живешь? (Caso Preposicional I - Lugares)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Жить","secondary":"[ Zhit ] — Morar / Viver","desc":"","audio":"Жить","level":"A1","module":"Módulo 7: Где ты живешь? (Caso Preposicional I - Lugares)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"в Москве","secondary":"[ v Moskve ] — em Moscou","desc":"","audio":"в Москве","level":"A1","module":"Módulo 7: Где ты живешь? (Caso Preposicional I - Lugares)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"в городе","secondary":"[ v gorode ] — na cidade","desc":"","audio":"в городе","level":"A1","module":"Módulo 7: Где ты живешь? (Caso Preposicional I - Lugares)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Concordância dos Números 1 e 2","secondary":"Один / Одна (1) — Два / Две (2)","desc":"Os números 1 e 2 em russo mudam de acordo com o gênero do substantivo.","context":"Ex: \"Один кот, одна кошка, два рубля, две книги. — \"Um gato, uma gata, dois rublos, duas palavras.\"\"","audio":"Concordância dos Números 1 e 2","level":"A1","module":"Módulo 8: Числа 1-20 (Números e Contagem)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Formação dos Números 11 a 19","secondary":"[Número Base] + надцать","desc":"Adiciona-se o sufixo -надцать ao número base.","context":"Ex: \"11 = одиннадцать, 12 = двенадцать. — \"11 = onze, 12 = doze.\"\"","audio":"Formação dos Números 11 a 19","level":"A1","module":"Módulo 8: Числа 1-20 (Números e Contagem)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Один","secondary":"[ Odin ] — Um (masc)","desc":"","audio":"Один","level":"A1","module":"Módulo 8: Числа 1-20 (Números e Contagem)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Два","secondary":"[ Dva ] — Dois (masc)","desc":"","audio":"Два","level":"A1","module":"Módulo 8: Числа 1-20 (Números e Contagem)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Три","secondary":"[ Tri ] — Três","desc":"","audio":"Три","level":"A1","module":"Módulo 8: Числа 1-20 (Números e Contagem)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пять","secondary":"[ Pyat ] — Cinco","desc":"","audio":"Пять","level":"A1","module":"Módulo 8: Числа 1-20 (Números e Contagem)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Десять","secondary":"[ Desyat ] — Dez","desc":"","audio":"Десять","level":"A1","module":"Módulo 8: Числа 1-20 (Números e Contagem)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Expressão Я буду...","secondary":"Я буду + [Pedido no Acusativo]","desc":"A forma mais natural de pedir comida ou bebida em restaurantes na Rússia é usando \"Я буду...\".","context":"Ex: \"Я буду кофе. / Я буду воду. — \"Eu vou querer café. / Eu vou querer água.\"\"","audio":"A Expressão Я буду...","level":"A1","module":"Módulo 9: В ресторане (Restaurante e Pedidos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pedindo a Conta","secondary":"Счёт, пожалуйста!","desc":"Expressão curta e cortês para solicitar a conta ao garçom.","context":"Ex: \"Дайте счёт, пожалуйста. — \"Me dê a conta, por favor.\"\"","audio":"Pedindo a Conta","level":"A1","module":"Módulo 9: В ресторане (Restaurante e Pedidos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Меню","secondary":"[ Menyu ] — Cardápio / Menu","desc":"","audio":"Меню","level":"A1","module":"Módulo 9: В ресторане (Restaurante e Pedidos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Чай","secondary":"[ Chai ] — Chá","desc":"","audio":"Чай","level":"A1","module":"Módulo 9: В ресторане (Restaurante e Pedidos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Кофе","secondary":"[ Kofe ] — Café","desc":"","audio":"Кофе","level":"A1","module":"Módulo 9: В ресторане (Restaurante e Pedidos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Счёт","secondary":"[ Schot ] — Conta","desc":"","audio":"Счёт","level":"A1","module":"Módulo 9: В ресторане (Restaurante e Pedidos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Concordância do Adjetivo Вкусный","secondary":"Вкусный (Masc) / Вкусная (Fem) / Вкусное (Neutro)","desc":"O adjetivo \"saboroso\" concorda com o gênero do prato.","context":"Ex: \"Вкусный борщ / Вкусная рыба. — \"Borsch saboroso / Peixe saboroso.\"\"","audio":"Concordância do Adjetivo Вкусный","level":"A1","module":"Módulo 10: Русская кухня (Comidas Típicas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Gosto (Мне нравится)","secondary":"Мне нравится + [Singular] / Мне нравятся + [Plural]","desc":"Para dizer que gosta de algo em russo, usa-se \"Мне нравится\" (singular) ou \"Мне нравятся\" (plural).","context":"Ex: \"Мне нравится борщ. — \"Eu gosto de borsch.\"\"","audio":"Expressando Gosto (Мне нравится)","level":"A1","module":"Módulo 10: Русская кухня (Comidas Típicas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Борщ","secondary":"[ Borsch ] — Borsch (Sopa de beterraba)","desc":"","audio":"Борщ","level":"A1","module":"Módulo 10: Русская кухня (Comidas Típicas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Блины","secondary":"[ Bliny ] — Panquecas russas","desc":"","audio":"Блины","level":"A1","module":"Módulo 10: Русская кухня (Comidas Típicas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пельмени","secondary":"[ Pelmeni ] — Massa recheada russa","desc":"","audio":"Пельмени","level":"A1","module":"Módulo 10: Русская кухня (Comidas Típicas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вкусный","secondary":"[ Vkusny ] — Saboroso / Gostoso","desc":"","audio":"Вкусный","level":"A1","module":"Módulo 10: Русская кухня (Comidas Típicas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estações no Preposicional","secondary":"На + [Estação + ции]","desc":"Substantivos femininos terminados em -ция mudam para -ции no Caso Preposicional.","context":"Ex: \"Я на станции \"Арбатская\". — \"Estou na estação Arbatskaya.\"\"","audio":"Estações no Preposicional","level":"A1","module":"Módulo 11: В метро Москвы (Metrô de Moscou)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Sinalizações de Entrada e Saída","secondary":"Вход (Entrada) / Выход (Saída)","desc":"Palavras essenciais para se orientar em estações de metrô e prédios públicos.","context":"Ex: \"Где выход в город? — \"Onde fica a saída?\"\"","audio":"Sinalizações de Entrada e Saída","level":"A1","module":"Módulo 11: В метро Москвы (Metrô de Moscou)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Метро","secondary":"[ Metro ] — Metrô","desc":"","audio":"Метро","level":"A1","module":"Módulo 11: В метро Москвы (Metrô de Moscou)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Станция","secondary":"[ Stantsiya ] — Estação","desc":"","audio":"Станция","level":"A1","module":"Módulo 11: В метро Москвы (Metrô de Moscou)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Поезд","secondary":"[ Poyezd ] — Trem","desc":"","audio":"Поезд","level":"A1","module":"Módulo 11: В метро Москвы (Metrô de Moscou)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вход","secondary":"[ Vkhod ] — Entrada","desc":"","audio":"Вход","level":"A1","module":"Módulo 11: В метро Москвы (Metrô de Moscou)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Выход","secondary":"[ Vykhod ] — Saída","desc":"","audio":"Выход","level":"A1","module":"Módulo 11: В метро Москвы (Metrô de Moscou)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntando as Horas","secondary":"Который час? (Que horas são?)","desc":"Para perguntar as horas em russo, usa-se a expressão \"Который час?\".","context":"Ex: \"Который час? — Сейчас три часа. — \"Que horas são? — Agora são três horas.\"\"","audio":"Perguntando as Horas","level":"A1","module":"Módulo 12: Который час? (Horas e Tempo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Formas de Hora (Час / Часа / Часов)","secondary":"1 час / 2,3,4 часа / 5-20 часов","desc":"O substantivo \"час\" concorda com o número de horas.","context":"Ex: \"Один час, два часа, пять часов. — \"1h, 2h, 5h.\"\"","audio":"Formas de Hora (Час / Часа / Часов)","level":"A1","module":"Módulo 12: Который час? (Horas e Tempo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Час","secondary":"[ Chas ] — Hora","desc":"","audio":"Час","level":"A1","module":"Módulo 12: Который час? (Horas e Tempo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Минута","secondary":"[ Minuta ] — Minuto","desc":"","audio":"Минута","level":"A1","module":"Módulo 12: Который час? (Horas e Tempo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Утро","secondary":"[ Utro ] — Manhã","desc":"","audio":"Утро","level":"A1","module":"Módulo 12: Который час? (Horas e Tempo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"День","secondary":"[ Den ] — Dia / Tarde","desc":"","audio":"День","level":"A1","module":"Módulo 12: Который час? (Horas e Tempo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вечер","secondary":"[ Vecher ] — Noite","desc":"","audio":"Вечер","level":"A1","module":"Módulo 12: Который час? (Horas e Tempo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Dias da Semana com В","secondary":"В + [Dia da Semana no Acusativo]","desc":"Para indicar em qual dia da semana algo acontece, usa-se В + Acusativo.","context":"Ex: \"В понедельник я работаю. — \"Na segunda eu trabalho.\"\"","audio":"Dias da Semana com В","level":"A1","module":"Módulo 13: Дни недели и месяцы (Dias e Meses)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Meses do Ano no Preposicional","secondary":"В + [Mês no Preposicional]","desc":"Para dizer \"em tal mês\", usa-se В + Caso Preposicional.","context":"Ex: \"В январе холодно. — \"Em janeiro faz frio.\"\"","audio":"Meses do Ano no Preposicional","level":"A1","module":"Módulo 13: Дни недели и месяцы (Dias e Meses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Понедельник","secondary":"[ Ponedelnik ] — Segunda-feira","desc":"","audio":"Понедельник","level":"A1","module":"Módulo 13: Дни недели и месяцы (Dias e Meses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вторник","secondary":"[ Vtornik ] — Terça-feira","desc":"","audio":"Вторник","level":"A1","module":"Módulo 13: Дни недели и месяцы (Dias e Meses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Среда","secondary":"[ Sreda ] — Quarta-feira","desc":"","audio":"Среда","level":"A1","module":"Módulo 13: Дни недели и месяцы (Dias e Meses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Суббота","secondary":"[ Subbota ] — Sábado","desc":"","audio":"Суббота","level":"A1","module":"Módulo 13: Дни недели и месяцы (Dias e Meses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Воскресенье","secondary":"[ Voskresenye ] — Domingo","desc":"","audio":"Воскресенье","level":"A1","module":"Módulo 13: Дни недели и месяцы (Dias e Meses)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"1ª Conjugação (-ать)","secondary":"Я -ю, Ты -ешь, Он -ет, Мы -ем, Вы -ете, Они -ют","desc":"Os verbos da 1ª conjugação em -ать seguem um padrão regular de terminações no presente.","context":"Ex: \"Я читаю книгу. — \"Eu leio um livro.\"\"","audio":"1ª Conjugação (-ать)","level":"A1","module":"Módulo 14: Мой день (Rotina e 1ª Conjugação)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntando a Ação Atual","secondary":"Что ты делаешь? (Informal) / Что вы делаете? (Formal)","desc":"Para perguntar o que alguém está fazendo no momento.","context":"Ex: \"Что ты делаешь? — Я работаю. — \"O que faz? — Trabalhando.\"\"","audio":"Perguntando a Ação Atual","level":"A1","module":"Módulo 14: Мой день (Rotina e 1ª Conjugação)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Читать","secondary":"[ Chitat ] — Ler","desc":"","audio":"Читать","level":"A1","module":"Módulo 14: Мой день (Rotina e 1ª Conjugação)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Делать","secondary":"[ Delat ] — Fazer","desc":"","audio":"Делать","level":"A1","module":"Módulo 14: Мой день (Rotina e 1ª Conjugação)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Работать","secondary":"[ Rabotat ] — Trabalhar","desc":"","audio":"Работать","level":"A1","module":"Módulo 14: Мой день (Rotina e 1ª Conjugação)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Отдыхать","secondary":"[ Otdykhat ] — Descansar","desc":"","audio":"Отдыхать","level":"A1","module":"Módulo 14: Мой день (Rotina e 1ª Conjugação)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"2ª Conjugação (-ить)","secondary":"Я -ю/у, Ты -ишь, Он -ит, Мы -им, Вы -ите, Они -ят/ат","desc":"Os verbos da 2ª conjugação em -ить possuem terminações características no presente.","context":"Ex: \"Я говорю по-русски. — \"Eu falo russo.\"\"","audio":"2ª Conjugação (-ить)","level":"A1","module":"Módulo 15: Что ты делаешь? (2ª Conjugação)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Falar Idiomas (по-...)","secondary":"Говорить + по-[idioma]","desc":"Ao usar o verbo \"говорить\", adiciona-se o prefixo \"по-\" ao idioma.","context":"Ex: \"Вы говорите по-русски? — \"Você fala russo?\"\"","audio":"Falar Idiomas (по-...)","level":"A1","module":"Módulo 15: Что ты делаешь? (2ª Conjugação)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Говорить","secondary":"[ Govorit ] — Falar","desc":"","audio":"Говорить","level":"A1","module":"Módulo 15: Что ты делаешь? (2ª Conjugação)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Смотреть","secondary":"[ Smotret ] — Olhar / Assistir","desc":"","audio":"Смотреть","level":"A1","module":"Módulo 15: Что ты делаешь? (2ª Conjugação)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Учить","secondary":"[ Uchit ] — Aprender / Estudar","desc":"","audio":"Учить","level":"A1","module":"Módulo 15: Что ты делаешь? (2ª Conjugação)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"по-русски","secondary":"[ po-russki ] — russo (idioma)","desc":"","audio":"по-русски","level":"A1","module":"Módulo 15: Что ты делаешь? (2ª Conjugação)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntando Preços (Сколько стоит)","secondary":"Сколько стоит [Singular]? / Сколько стоят [Plural]?","desc":"Diferencie o preço no singular (стоит) do plural (стоят).","context":"Ex: \"Сколько стоит книга? / Сколько стоят сувениры? — \"Quanto custa o livro? / Quanto custam os souvenirs?\"\"","audio":"Perguntando Preços (Сколько стоит)","level":"A1","module":"Módulo 16: В магазине (Compras e Preços)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Flexão de Rublos","secondary":"1 рубль / 2,3,4 рубля / 5-20 рублей","desc":"O substantivo \"рубль\" muda de acordo com o número que o antecede.","context":"Ex: \"Один рубль, два рубля, сто рублей. — \"1 rublo, 2 rublos, 100 rublos.\"\"","audio":"Flexão de Rublos","level":"A1","module":"Módulo 16: В магазине (Compras e Preços)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сколько","secondary":"[ Skolko ] — Quanto(s)","desc":"","audio":"Сколько","level":"A1","module":"Módulo 16: В магазине (Compras e Preços)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Стоить","secondary":"[ Stoit ] — Custar","desc":"","audio":"Стоить","level":"A1","module":"Módulo 16: В магазине (Compras e Preços)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Рубль","secondary":"[ Rubl ] — Rublo (moeda)","desc":"","audio":"Рубль","level":"A1","module":"Módulo 16: В магазине (Compras e Preços)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Магазин","secondary":"[ Magazin ] — Loja","desc":"","audio":"Магазин","level":"A1","module":"Módulo 16: В магазине (Compras e Preços)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Concordância dos Adjetivos de Cor","secondary":"Красный (Masc) / Красная (Fem) / Красное (Neutro) / Красные (Plural)","desc":"Adjetivos de cor concordam com o gênero e número do substantivo.","context":"Ex: \"Красный шарф / Красная рубашка. — \"Cachecol vermelho / Camisa vermelha.\"\"","audio":"Concordância dos Adjetivos de Cor","level":"A1","module":"Módulo 17: Одежда и цвета (Roupas e Cores)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Roupas de Inverno","secondary":"Пальто (Indeclinável) / Шапка / Шарф","desc":"Vocabulário essencial para vestuário de frio intenso.","context":"Ex: \"Тёплое пальто и чёрная шапка. — \"Casaco quente e gorro preto.\"\"","audio":"Roupas de Inverno","level":"A1","module":"Módulo 17: Одежда и цвета (Roupas e Cores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Красный","secondary":"[ Krasny ] — Vermelho","desc":"","audio":"Красный","level":"A1","module":"Módulo 17: Одежда и цвета (Roupas e Cores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Синий","secondary":"[ Siny ] — Azul escuro","desc":"","audio":"Синий","level":"A1","module":"Módulo 17: Одежда и цвета (Roupas e Cores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Чёрный","secondary":"[ Chorny ] — Preto","desc":"","audio":"Чёрный","level":"A1","module":"Módulo 17: Одежда и цвета (Roupas e Cores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Шапка","secondary":"[ Shapka ] — Gorro / Touca","desc":"","audio":"Шапка","level":"A1","module":"Módulo 17: Одежда и цвета (Roupas e Cores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пальто","secondary":"[ Palto ] — Sobretudo / Casaco","desc":"","audio":"Пальто","level":"A1","module":"Módulo 17: Одежда и цвета (Roupas e Cores)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Frases Impessoais de Clima","secondary":"Сегодня + [Холодно / Тепло / Жарко]","desc":"Para falar sobre a temperatura e o clima usam-se advérbios impessoais.","context":"Ex: \"Сегодня очень холодно. — \"Hoje está muito frio.\"\"","audio":"Frases Impessoais de Clima","level":"A1","module":"Módulo 18: Погода в России (O Clima na Rússia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Precipitações (Neve e Chuva)","secondary":"Идёт снег (Nevando) / Идёт дождь (Chovendo)","desc":"Para dizer que está nevando ou chovendo usa-se o verbo \"идти\".","context":"Ex: \"На улице идёт снег. — \"Está nevando na rua.\"\"","audio":"Precipitações (Neve e Chuva)","level":"A1","module":"Módulo 18: Погода в России (O Clima na Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Холодно","secondary":"[ Kholodno ] — Frio","desc":"","audio":"Холодно","level":"A1","module":"Módulo 18: Погода в России (O Clima na Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Тепло","secondary":"[ Teplo ] — Agradável / Morno","desc":"","audio":"Тепло","level":"A1","module":"Módulo 18: Погода в России (O Clima na Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Жарко","secondary":"[ Zharko ] — Quente / Calor","desc":"","audio":"Жарко","level":"A1","module":"Módulo 18: Погода в России (O Clima na Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Снег","secondary":"[ Sneg ] — Neve","desc":"","audio":"Снег","level":"A1","module":"Módulo 18: Погода в России (O Clima na Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дождь","secondary":"[ Dozhd ] — Chuva","desc":"","audio":"Дождь","level":"A1","module":"Módulo 18: Погода в России (O Clima na Rússia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pedidos Polidos com Будьте добры","secondary":"Будьте добры + [Pedido]","desc":"A expressão mais cortês para solicitar atendimento em hotéis ou serviços.","context":"Ex: \"Будьте добры, мой ключ. — \"Tenha a gentileza, minha chave.\"\"","audio":"Pedidos Polidos com Будьте добры","level":"A1","module":"Módulo 19: В отеле (Check-in e Hospedagem)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Vocabulário de Hotel","secondary":"Номер (Quarto) / Ключ (Chave) / Бронь (Reserva)","desc":"Termos fundamentais para check-in e hospedagem.","context":"Ex: \"У меня забронирован номер. — \"Eu tenho um quarto reservado.\"\"","audio":"Vocabulário de Hotel","level":"A1","module":"Módulo 19: В отеле (Check-in e Hospedagem)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Отель","secondary":"[ Otel ] — Hotel","desc":"","audio":"Отель","level":"A1","module":"Módulo 19: В отеле (Check-in e Hospedagem)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Номер","secondary":"[ Nomer ] — Quarto de hotel / Número","desc":"","audio":"Номер","level":"A1","module":"Módulo 19: В отеле (Check-in e Hospedagem)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ключ","secondary":"[ Klyuch ] — Chave","desc":"","audio":"Ключ","level":"A1","module":"Módulo 19: В отеле (Check-in e Hospedagem)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Бронь","secondary":"[ Bron ] — Reserva","desc":"","audio":"Бронь","level":"A1","module":"Módulo 19: В отеле (Check-in e Hospedagem)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura У меня болит...","secondary":"У меня болит + [Singular] / У меня болят + [Plural]","desc":"Para expressar dores no corpo, diferencie singular e plural.","context":"Ex: \"У меня болит голова (sing) / У меня болят зубы (plural) — \"Dor de cabeça / Dor nos dentes\"\"","audio":"Estrutura У меня болит...","level":"A1","module":"Módulo 20: Здоровье и аптека (Saúde e Farmácia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pedidos na Farmácia","secondary":"Дайте, пожалуйста, лекарство от + [Sintoma]","desc":"Para solicitar um medicamento específico na farmácia.","context":"Ex: \"Дайте лекарство от боли. — \"Remédio para dor.\"\"","audio":"Pedidos na Farmácia","level":"A1","module":"Módulo 20: Здоровье и аптека (Saúde e Farmácia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Аптека","secondary":"[ Apteka ] — Farmácia","desc":"","audio":"Аптека","level":"A1","module":"Módulo 20: Здоровье и аптека (Saúde e Farmácia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Лекарство","secondary":"[ Lekarstvo ] — Remédio","desc":"","audio":"Лекарство","level":"A1","module":"Módulo 20: Здоровье и аптека (Saúde e Farmácia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Голова","secondary":"[ Golova ] — Cabeça","desc":"","audio":"Голова","level":"A1","module":"Módulo 20: Здоровье и аптека (Saúde e Farmácia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Болеть","secondary":"[ Bolet ] — Doer","desc":"","audio":"Болеть","level":"A1","module":"Módulo 20: Здоровье и аптека (Saúde e Farmácia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Meios de Transporte com НА","secondary":"НА + [Transporte no Preposicional]","desc":"Para indicar o meio de transporte utilizado, usa-se Na no Preposicional.","context":"Ex: \"Я еду на автобусе. — \"Estou indo de ônibus.\"\"","audio":"Meios de Transporte com НА","level":"A1","module":"Módulo 21: Транспорт в городе (Transportes Urbanos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbo de Deslocamento Ехать","secondary":"Я еду / Ты едешь / Он едет / Мы едем / Они едут","desc":"Diferença entre deslocar-se a pé (идти) e por veículo (ехать).","context":"Ex: \"Мы едем в центр на такси. — \"Vamos ao centro de táxi.\"\"","audio":"Verbo de Deslocamento Ехать","level":"A1","module":"Módulo 21: Транспорт в городе (Transportes Urbanos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Автобус","secondary":"[ Avtobus ] — Ônibus","desc":"","audio":"Автобус","level":"A1","module":"Módulo 21: Транспорт в городе (Transportes Urbanos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Такси","secondary":"[ Taksi ] — Táxi","desc":"","audio":"Такси","level":"A1","module":"Módulo 21: Транспорт в городе (Transportes Urbanos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Трамвай","secondary":"[ Tramvay ] — Bonde","desc":"","audio":"Трамвай","level":"A1","module":"Módulo 21: Транспорт в городе (Transportes Urbanos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ехать","secondary":"[ Yekhat ] — Ir de transporte","desc":"","audio":"Ехать","level":"A1","module":"Módulo 21: Транспорт в городе (Transportes Urbanos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Advérbios de Direção","secondary":"Прямо (Em frente) / Направо (Direita) / Налево (Esquerda)","desc":"Termos essenciais para dar e seguir orientações na cidade.","context":"Ex: \"Идите прямо, потом направо. — \"Vá em frente, depois à direita.\"\"","audio":"Advérbios de Direção","level":"A1","module":"Módulo 22: Ориентация в городе (Direções e Localização)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Advérbios de Proximidade","secondary":"Рядом (Perto) / Далеко (Longe)","desc":"Expressando distância ou proximidade de pontos de interesse.","context":"Ex: \"Метро рядом? — Нет, далеко. — \"O metrô é perto? — Não, longe.\"\"","audio":"Advérbios de Proximidade","level":"A1","module":"Módulo 22: Ориентация в городе (Direções e Localização)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Прямо","secondary":"[ Pryamo ] — Em frente","desc":"","audio":"Прямо","level":"A1","module":"Módulo 22: Ориентация в городе (Direções e Localização)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Направо","secondary":"[ Napravo ] — À direita","desc":"","audio":"Направо","level":"A1","module":"Módulo 22: Ориентация в городе (Direções e Localização)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Налево","secondary":"[ Nalevo ] — À esquerda","desc":"","audio":"Налево","level":"A1","module":"Módulo 22: Ориентация в городе (Direções e Localização)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Рядом","secondary":"[ Ryadom ] — Perto / Ao lado","desc":"","audio":"Рядом","level":"A1","module":"Módulo 22: Ориентация в городе (Direções e Localização)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Далеко","secondary":"[ Daleko ] — Longe","desc":"","audio":"Далеко","level":"A1","module":"Módulo 22: Ориентация в городе (Direções e Localização)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Resumo dos Casos Principais A1","secondary":"Nominativo (Sujeito) / Preposicional (Local) / Genitivo (Origem)","desc":"Síntese das 3 funções essenciais aprendidas no nível iniciante.","context":"Ex: \"Я из Бразилии (Gen). Я живу в Москве (Prep). — \"Sou do Brasil. Moro em Moscou.\"\"","audio":"Resumo dos Casos Principais A1","level":"A1","module":"Módulo 23: Revisão Geral A1"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Resumo das Conjugações","secondary":"1ª Conjugação (-ать) vs 2ª Conjugação (-ить)","desc":"Comparativo dos dois grandes grupos verbais em russo.","context":"Ex: \"Я читаю (1ª) / Я говорю (2ª). — \"Eu leio / Eu falo.\"\"","audio":"Resumo das Conjugações","level":"A1","module":"Módulo 23: Revisão Geral A1"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Certificação Interna A1","secondary":"Russo de Sobrevivência (Nível A1 Concluído)","desc":"Ao concluir este teste com aproveitamento, você estará preparado para o Nível A2.","context":"Ex: \"Поздравляем! (Parabéns!) — \"Parabéns!\"\"","audio":"Certificação Interna A1","level":"A1","module":"Módulo 24: Desafio Final A1 (Aeroporto de Moscou)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estruturas Fundamentais A1","secondary":"Здравствуйте / Меня зовут / Я из / Я живу / Сколько стоит","desc":"Revisão das expressões chave de cortesia, localização e compras.","context":"Ex: \"Здравствуйте! Я из Бразилии. — \"Olá! Sou do Brasil.\"\"","audio":"Estruturas Fundamentais A1","level":"A1","module":"Módulo 24: Desafio Final A1 (Aeroporto de Moscou)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Поздравляем","secondary":"[ Pozdravlyayem ] — Parabéns!","desc":"","audio":"Поздравляем","level":"A1","module":"Módulo 24: Desafio Final A1 (Aeroporto de Moscou)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Sufixos do Tempo Passado","secondary":"Infinitivo sem -ть + -л (M) / -ла (F) / -ло (N) / -ли (Plur)","desc":"Em russo, o passado concorda em gênero e número com o sujeito, substituindo a terminação do infinitivo (-ть) pelos sufixos -л, -ла, -ло, -ли.","context":"Ex: \"Он читал / Она читала / Они читали — \"Ele leu / Ela leu / Eles leram\"\"","audio":"Sufixos do Tempo Passado","level":"A2","module":"Módulo 1: Прошлое (O Passado dos Verbos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Passado do Verbo Быть (Ser/Estar)","secondary":"Был (M) / Была (F) / Было (N) / Были (Plural)","desc":"O verbo ser/estar no passado flexiona normalmente: Был (M), Была (F), Было (N), Были (Plur).","context":"Ex: \"Вчера я был дома. — \"Ontem eu estava em casa.\"\"","audio":"Passado do Verbo Быть (Ser/Estar)","level":"A2","module":"Módulo 1: Прошлое (O Passado dos Verbos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вчера","secondary":"[ Vchera ] — Ontem","desc":"","audio":"Вчера","level":"A2","module":"Módulo 1: Прошлое (O Passado dos Verbos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Раньше","secondary":"[ Ranshe ] — Antes / Antigamente","desc":"","audio":"Раньше","level":"A2","module":"Módulo 1: Прошлое (O Passado dos Verbos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Был","secondary":"[ Byl ] — Estava / Foi (masculino)","desc":"","audio":"Был","level":"A2","module":"Módulo 1: Прошлое (O Passado dos Verbos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Была","secondary":"[ Byla ] — Estava / Foi (feminino)","desc":"","audio":"Была","level":"A2","module":"Módulo 1: Прошлое (O Passado dos Verbos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Смотрел","secondary":"[ Smotrel ] — Assistiu / Olhou (masculino)","desc":"","audio":"Смотрел","level":"A2","module":"Módulo 1: Прошлое (O Passado dos Verbos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Futuro Composto (Буду + Infinitivo)","secondary":"Я буду / Ты будешь / Он будет / Мы будем / Вы будете / Они будут + [Infinitivo]","desc":"Para verbos imperfeitos, o futuro é formado conjugando o verbo быть no futuro + o verbo principal no infinitivo.","context":"Ex: \"Я буду читать книгу. — \"Eu vou ler / lerei um livro.\"\"","audio":"Futuro Composto (Буду + Infinitivo)","level":"A2","module":"Módulo 2: Будущее (O Futuro Simples e Composto)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Marcadores de Tempo Futuro","secondary":"Завтра / Скоро / На следующей неделе","desc":"Palavras como Завтра (Amanhã) e Скоро (Em breve) indicam ações futuras.","context":"Ex: \"Завтра мы будем отдыхать. — \"Amanhã nós vamos descansar.\"\"","audio":"Marcadores de Tempo Futuro","level":"A2","module":"Módulo 2: Будущее (O Futuro Simples e Composto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Завтра","secondary":"[ Zavtra ] — Amanhã","desc":"","audio":"Завтра","level":"A2","module":"Módulo 2: Будущее (O Futuro Simples e Composto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Скоро","secondary":"[ Skoro ] — Em breve / Logo","desc":"","audio":"Скоро","level":"A2","module":"Módulo 2: Будущее (O Futuro Simples e Composto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Буду","secondary":"[ Budu ] — Eu serei / Eu vou","desc":"","audio":"Буду","level":"A2","module":"Módulo 2: Будущее (O Futuro Simples e Composto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Планы","secondary":"[ Plany ] — Planos","desc":"","audio":"Планы","level":"A2","module":"Módulo 2: Будущее (O Futuro Simples e Composto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Будет","secondary":"[ Budet ] — Será / Vai ser","desc":"","audio":"Будет","level":"A2","module":"Módulo 2: Будущее (O Futuro Simples e Composto)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Aspecto Imperfeito (НСВ)","secondary":"Verbo НСВ (процесс / повторение)","desc":"O aspecto imperfeito (НСВ) foca no PROCESSO da ação, na sua duração ou na repetição de um hábito.","context":"Ex: \"Я долго писал письмо. — \"Eu fiquei um longo tempo escrevendo a carta.\"\"","audio":"Aspecto Imperfeito (НСВ)","level":"A2","module":"Módulo 3: Аспект глагола I (Imperfeito vs Perfeito)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Aspecto Perfeito (СВ)","secondary":"Verbo СВ (результат / факт)","desc":"O aspecto perfeito (СВ) foca no RESULTADO único de uma ação totalmente concluída.","context":"Ex: \"Я написал письмо. — \"Eu escrevi (e terminei) a carta.\"\"","audio":"Aspecto Perfeito (СВ)","level":"A2","module":"Módulo 3: Аспект глагола I (Imperfeito vs Perfeito)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сделать","secondary":"[ Sdelat ] — Fazer / Concluir (perfeito/resultado)","desc":"","audio":"Сделать","level":"A2","module":"Módulo 3: Аспект глагола I (Imperfeito vs Perfeito)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Прочитать","secondary":"[ Prochitat ] — Ler até o fim (perfeito)","desc":"","audio":"Прочитать","level":"A2","module":"Módulo 3: Аспект глагола I (Imperfeito vs Perfeito)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Написать","secondary":"[ Napisat ] — Escrever (perfeito)","desc":"","audio":"Написать","level":"A2","module":"Módulo 3: Аспект глагола I (Imperfeito vs Perfeito)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Наконец","secondary":"[ Nakonets ] — Finalmente / Por fim","desc":"","audio":"Наконец","level":"A2","module":"Módulo 3: Аспект глагола I (Imperfeito vs Perfeito)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Acusativo Feminino Inanimado","secondary":"Feminino em -а ➔ -у / Feminino em -я ➔ -ю","desc":"No Caso Acusativo (objeto direto), os substantivos femininos terminados em -а mudam para -у, e em -я mudam para -ю.","context":"Ex: \"Книга ➔ Книгу / Вода ➔ Воду / Земля ➔ Землю — \"Livro ➔ (vejo o) livro / Água ➔ (bebo) água\"\"","audio":"Acusativo Feminino Inanimado","level":"A2","module":"Módulo 4: Винительный падеж I (Caso Acusativo - Inanimados)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Masculinos e Neutros Inanimados","secondary":"Masculino/Neutro Inanimado = Sem alteração","desc":"Substantivos masculinos e neutros inanimados permanecem exatamente iguais ao Nominativo.","context":"Ex: \"Я вижу дом (M). Я ем яблоко (N). — \"Eu vejo a casa. Eu como a maçã.\"\"","audio":"Masculinos e Neutros Inanimados","level":"A2","module":"Módulo 4: Винительный падеж I (Caso Acusativo - Inanimados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Книгу","secondary":"[ Knigu ] — Livro (objeto direto acusativo)","desc":"","audio":"Книгу","level":"A2","module":"Módulo 4: Винительный падеж I (Caso Acusativo - Inanimados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Воду","secondary":"[ Vodu ] — Água (objeto direto acusativo)","desc":"","audio":"Воду","level":"A2","module":"Módulo 4: Винительный падеж I (Caso Acusativo - Inanimados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Песню","secondary":"[ Pesnyu ] — Música / Canção (acusativo)","desc":"","audio":"Песню","level":"A2","module":"Módulo 4: Винительный падеж I (Caso Acusativo - Inanimados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Газету","secondary":"[ Gazetu ] — Jornal (acusativo)","desc":"","audio":"Газету","level":"A2","module":"Módulo 4: Винительный падеж I (Caso Acusativo - Inanimados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Письмо","secondary":"[ Pismo ] — Carta (neutro inalterado)","desc":"","audio":"Письмо","level":"A2","module":"Módulo 4: Винительный падеж I (Caso Acusativo - Inanimados)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Acusativo Masculino Animado","secondary":"Masculino Animado + -а / -я","desc":"Ao contrário dos objetos inanimados, os seres masculinos animados (pessoas e animais) recebem a terminação -а (ou -я se terminados em soft sign/й) no Acusativo.","context":"Ex: \"Брат ➔ Брата / Друг ➔ Друга / Учитель ➔ Учителя — \"Irmão ➔ (vejo o) irmão / Amigo ➔ (conheço o) amigo\"\"","audio":"Acusativo Masculino Animado","level":"A2","module":"Módulo 5: Винительный падеж II (Caso Acusativo - Animados)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Animado vs. Inanimado no Masculino","secondary":"Дом (Inanimado) vs. Друга (Animado)","desc":"Já para inanimados o acusativo é igual ao nominativo. Compare: Я вижу дом (inanimado) vs Я вижу друга (animado).","context":"Ex: \"Я вижу автобус (inanimado) / Я вижу кота (animado) — \"Vejo o ônibus / Vejo o gato\"\"","audio":"Animado vs. Inanimado no Masculino","level":"A2","module":"Módulo 5: Винительный падеж II (Caso Acusativo - Animados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Друга","secondary":"[ Druga ] — Amigo (acusativo animado)","desc":"","audio":"Друга","level":"A2","module":"Módulo 5: Винительный падеж II (Caso Acusativo - Animados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Брата","secondary":"[ Brata ] — Irmão (acusativo animado)","desc":"","audio":"Брата","level":"A2","module":"Módulo 5: Винительный падеж II (Caso Acusativo - Animados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Учителя","secondary":"[ Uchitelya ] — Professor (acusativo animado)","desc":"","audio":"Учителя","level":"A2","module":"Módulo 5: Винительный падеж II (Caso Acusativo - Animados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Кота","secondary":"[ Kota ] — Gato (acusativo animado)","desc":"","audio":"Кота","level":"A2","module":"Módulo 5: Винительный падеж II (Caso Acusativo - Animados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вижу","secondary":"[ Vizhu ] — Eu vejo","desc":"","audio":"Вижу","level":"A2","module":"Módulo 5: Винительный падеж II (Caso Acusativo - Animados)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Ausência com У меня нет...","secondary":"У [Genitivo de quem] нет + [Genitivo do que falta]","desc":"A negação de posse ou ausência total de algo é expressa pela estrutura \"У меня нет\" seguida do substantivo obrigatoriamente no Caso Genitivo.","context":"Ex: \"У меня нет машины. / У него нет времени. — \"Eu não tenho carro. / Ele não tem tempo.\"\"","audio":"Ausência com У меня нет...","level":"A2","module":"Módulo 6: Родительный падеж I (Caso Genitivo - Posse e Ausência)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Terminações do Genitivo Singular","secondary":"Masc/Neutro: -а/-я | Fem: -ы/-и","desc":"Substantivos masculinos/neutros ganham -а/-я. Femininos terminados em -а mudam para -ы (ou -и após г, к, х, ж, ч, ш, щ).","context":"Ex: \"Брат ➔ Брата / Машина ➔ Машины / Книга ➔ Книги — \"do irmão / do carro / do livro\"\"","audio":"Terminações do Genitivo Singular","level":"A2","module":"Módulo 6: Родительный падеж I (Caso Genitivo - Posse e Ausência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Нет","secondary":"[ Net ] — Não há / Não tem","desc":"","audio":"Нет","level":"A2","module":"Módulo 6: Родительный падеж I (Caso Genitivo - Posse e Ausência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Времени","secondary":"[ Vremeni ] — Tempo (genitivo)","desc":"","audio":"Времени","level":"A2","module":"Módulo 6: Родительный падеж I (Caso Genitivo - Posse e Ausência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Денег","secondary":"[ Deneg ] — Dinheiro (genitivo plural)","desc":"","audio":"Денег","level":"A2","module":"Módulo 6: Родительный падеж I (Caso Genitivo - Posse e Ausência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Машины","secondary":"[ Mashiny ] — Carro (genitivo)","desc":"","audio":"Машины","level":"A2","module":"Módulo 6: Родительный падеж I (Caso Genitivo - Posse e Ausência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Проблемы","secondary":"[ Problemy ] — Problema (genitivo)","desc":"","audio":"Проблемы","level":"A2","module":"Módulo 6: Родительный падеж I (Caso Genitivo - Posse e Ausência)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Contagem com 2, 3, 4 (Genitivo Singular)","secondary":"2, 3, 4 + [Genitivo Singular]","desc":"Após os números 2 (два/две), 3 (три) e 4 (четыре), o substantivo entra obrigatoriamente no Genitivo Singular.","context":"Ex: \"2 года / 3 рубля / 4 брата — \"2 anos / 3 rublos / 4 irmãos\"\"","audio":"Contagem com 2, 3, 4 (Genitivo Singular)","level":"A2","module":"Módulo 7: Родительный падеж II (Quantidade e Números)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Contagem com 5 a 20 (Genitivo Plural)","secondary":"5 a 20 + [Genitivo Plural]","desc":"Após os números de 5 a 20 (e dezenas inteiras), o substantivo entra no Genitivo Plural.","context":"Ex: \"5 лет / 10 рублей / 20 студентов — \"5 anos / 10 rublos / 20 estudantes\"\"","audio":"Contagem com 5 a 20 (Genitivo Plural)","level":"A2","module":"Módulo 7: Родительный падеж II (Quantidade e Números)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Года","secondary":"[ Goda ] — Anos (genitivo singular após 2,3,4)","desc":"","audio":"Года","level":"A2","module":"Módulo 7: Родительный падеж II (Quantidade e Números)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Лет","secondary":"[ Let ] — Anos (genitivo plural após 5+)","desc":"","audio":"Лет","level":"A2","module":"Módulo 7: Родительный падеж II (Quantidade e Números)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Рубля","secondary":"[ Rublya ] — Rublos (genitivo singular)","desc":"","audio":"Рубля","level":"A2","module":"Módulo 7: Родительный падеж II (Quantidade e Números)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Рублей","secondary":"[ Rubley ] — Rublos (genitivo plural)","desc":"","audio":"Рублей","level":"A2","module":"Módulo 7: Родительный падеж II (Quantidade e Números)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbo Заниматься + Instrumental","secondary":"Заниматься + [Instrumental]","desc":"Para dizer que pratica um esporte ou atividade de lazer, usa-se o verbo reflexivo Заниматься seguido do Caso Instrumental (-ом/-ем para masc, -ой/-ей para fem).","context":"Ex: \"Спорт ➔ Заниматься спортом / Музыка ➔ Заниматься музыкой — \"Praticar esportes / Fazer música\"\"","audio":"Verbo Заниматься + Instrumental","level":"A2","module":"Módulo 8: Свободное время и хобби (Lazer e Hobbies)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressão В свободное время","secondary":"В свободное время + [Ação]","desc":"Significa \"No tempo livre\", usada para introduzir hobbies.","context":"Ex: \"В свободное время я читаю. — \"No meu tempo livre eu leio.\"\"","audio":"Expressão В свободное время","level":"A2","module":"Módulo 8: Свободное время и хобби (Lazer e Hobbies)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Свободное время","secondary":"[ Svobodnoye vremya ] — Tempo livre","desc":"","audio":"Свободное время","level":"A2","module":"Módulo 8: Свободное время и хобби (Lazer e Hobbies)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Хобби","secondary":"[ Khobbi ] — Hobby","desc":"","audio":"Хобби","level":"A2","module":"Módulo 8: Свободное время и хобби (Lazer e Hobbies)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Спортом","secondary":"[ Sportom ] — Esporte (instrumental)","desc":"","audio":"Спортом","level":"A2","module":"Módulo 8: Свободное время и хобби (Lazer e Hobbies)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Музыкой","secondary":"[ Muzykoi ] — Música (instrumental)","desc":"","audio":"Музыкой","level":"A2","module":"Módulo 8: Свободное время и хобби (Lazer e Hobbies)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Плаванием","secondary":"[ Plavaniyem ] — Natação (instrumental)","desc":"","audio":"Плаванием","level":"A2","module":"Módulo 8: Свободное время и хобби (Lazer e Hobbies)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Felicitações com С + Instrumental","secondary":"С + [Festa no Instrumental]!","desc":"Em russo, felicita-se alguém por uma data comemorativa usando \"С\" + o nome da festa no Caso Instrumental.","context":"Ex: \"С Новым Годом! / С Днём Рождения! — \"Feliz Ano Novo! / Feliz Aniversário!\"\"","audio":"Felicitações com С + Instrumental","level":"A2","module":"Módulo 9: Праздники в России (Festas Russas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Principais Festas Russas","secondary":"Новый Год (Ano Novo) / Масленица (Maslenitsa)","desc":"O Ano Novo (Новый Год) é a maior festa do ano na Rússia, celebrada com a árvore (ёлка) e presentes de Ded Moroz (Papai Noel russo).","context":"Ex: \"Поздравляю с Новым Годом! — \"Parabéns pelo Ano Novo!\"\"","audio":"Principais Festas Russas","level":"A2","module":"Módulo 9: Праздники в России (Festas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Праздник","secondary":"[ Prazdnik ] — Festa / Feriado","desc":"","audio":"Праздник","level":"A2","module":"Módulo 9: Праздники в России (Festas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Подарок","secondary":"[ Podarok ] — Presente","desc":"","audio":"Подарок","level":"A2","module":"Módulo 9: Праздники в России (Festas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"С Новым Годом!","secondary":"[ S Novym Godom! ] — Feliz Ano Novo!","desc":"","audio":"С Новым Годом!","level":"A2","module":"Módulo 9: Праздники в России (Festas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"С Днём Рождения!","secondary":"[ S Dnyom Rozhdeniya! ] — Feliz Aniversário!","desc":"","audio":"С Днём Рождения!","level":"A2","module":"Módulo 9: Праздники в России (Festas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Поздравляю!","secondary":"[ Pozdravlyayu! ] — Parabéns! / Meus parabéns!","desc":"","audio":"Поздравляю!","level":"A2","module":"Módulo 9: Праздники в России (Festas Russas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Grau Comparativo Sintético","secondary":"Дорогой ➔ Дороже | Дешёвый ➔ Дешевле | Хороший ➔ Лучше","desc":"Muitos adjetivos em russo formam o comparativo adicionando -ее ou com formas especiais irregulares (дороже = mais caro, дешевле = mais barato, лучше = melhor).","context":"Ex: \"Эта книга дороже. — \"Este livro é mais caro.\"\"","audio":"Grau Comparativo Sintético","level":"A2","module":"Módulo 10: Покупки и сувениры (Matrioska e Lembrancinhas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Comparações com Чем","secondary":"[Item 1] + [Comparativo] + чем + [Item 2]","desc":"Para comparar duas coisas explicitamente, usa-se a palavra \"чем\" (do que).","context":"Ex: \"Матрёшка дороже, чем шапка. — \"A matrioska é mais cara do que o gorro.\"\"","audio":"Comparações com Чем","level":"A2","module":"Módulo 10: Покупки и сувениры (Matrioska e Lembrancinhas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Матрёшка","secondary":"[ Matryoshka ] — Matrioska (boneca russa)","desc":"","audio":"Матрёшка","level":"A2","module":"Módulo 10: Покупки и сувениры (Matrioska e Lembrancinhas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сувенир","secondary":"[ Suvenir ] — Lembrancinha / Souvenir","desc":"","audio":"Сувенир","level":"A2","module":"Módulo 10: Покупки и сувениры (Matrioska e Lembrancinhas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дороже","secondary":"[ Dorozhe ] — Mais caro(a)","desc":"","audio":"Дороже","level":"A2","module":"Módulo 10: Покупки и сувениры (Matrioska e Lembrancinhas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дешевле","secondary":"[ Deshevle ] — Mais barato(a)","desc":"","audio":"Дешевле","level":"A2","module":"Módulo 10: Покупки и сувениры (Matrioska e Lembrancinhas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Чем","secondary":"[ Chem ] — Do que (em comparações)","desc":"","audio":"Чем","level":"A2","module":"Módulo 10: Покупки и сувениры (Matrioska e Lembrancinhas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Adjetivos de Aparência e Caráter","secondary":"Masc: -ый/-ий | Fem: -ая/-яя | Plur: -ые/-ие","desc":"Os adjetivos masculinos terminam em -ый/-ой/-ий e os femininos em -ая/-яя. Eles concordam com a pessoa descrita.","context":"Ex: \"Высокий мужчина / Красивая женщина — \"Homem alto / Mulher bonita\"\"","audio":"Adjetivos de Aparência e Caráter","level":"A2","module":"Módulo 11: Описание людей (Descrição Física e Personalidade)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Descrevendo Cabelos e Olhos","secondary":"У него / У неё + [Adjetivo Plural] + глаза / волосы","desc":"Usa-se a estrutura \"У него / У неё\" + cor dos olhos/cabelos.","context":"Ex: \"У неё голубые глаза и тёмные волосы. — \"Ela tem olhos azuis e cabelos escuros.\"\"","audio":"Descrevendo Cabelos e Olhos","level":"A2","module":"Módulo 11: Описание людей (Descrição Física e Personalidade)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Высокий","secondary":"[ Vysoky ] — Alto","desc":"","audio":"Высокий","level":"A2","module":"Módulo 11: Описание людей (Descrição Física e Personalidade)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Красивая","secondary":"[ Krasivaya ] — Bonita (feminino)","desc":"","audio":"Красивая","level":"A2","module":"Módulo 11: Описание людей (Descrição Física e Personalidade)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Умный","secondary":"[ Umny ] — Inteligente","desc":"","audio":"Умный","level":"A2","module":"Módulo 11: Описание людей (Descrição Física e Personalidade)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Добрый","secondary":"[ Dobry ] — Bondoso / Gentil","desc":"","audio":"Добрый","level":"A2","module":"Módulo 11: Описание людей (Descrição Física e Personalidade)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Глаза","secondary":"[ Glaza ] — Olhos","desc":"","audio":"Глаза","level":"A2","module":"Módulo 11: Описание людей (Descrição Física e Personalidade)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Conceito Cultural da Дача","secondary":"На даче (Na dacha)","desc":"A Дача é a tradicional casa de campo russa onde as famílias passam fins de semana e o verão cultivando hortas e fazendo banha (sauna russa).","context":"Ex: \"Летом мы всегда ездим на дачу. — \"No verão nós sempre vamos para a dacha.\"\"","audio":"O Conceito Cultural da Дача","level":"A2","module":"Módulo 12: В квартире (A Dacha e Casas Russas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Cômodos e Móveis no Preposicional","secondary":"В комнате / На кухне / В спальне","desc":"Para dizer em qual cômodo algo está, usa-se В/НА + Preposicional (-е).","context":"Ex: \"Стол стоит в комнате. — \"A mesa está na sala.\"\"","audio":"Cômodos e Móveis no Preposicional","level":"A2","module":"Módulo 12: В квартире (A Dacha e Casas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дача","secondary":"[ Dacha ] — Dacha (casa de campo russa)","desc":"","audio":"Дача","level":"A2","module":"Módulo 12: В квартире (A Dacha e Casas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Квартира","secondary":"[ Kvartira ] — Apartamento","desc":"","audio":"Квартира","level":"A2","module":"Módulo 12: В квартире (A Dacha e Casas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Кухня","secondary":"[ Kukhnya ] — Cozinha","desc":"","audio":"Кухня","level":"A2","module":"Módulo 12: В квартире (A Dacha e Casas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Комната","secondary":"[ Komnata ] — Quarto / Sala","desc":"","audio":"Комната","level":"A2","module":"Módulo 12: В квартире (A Dacha e Casas Russas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мебель","secondary":"[ Mebel ] — Móveis","desc":"","audio":"Мебель","level":"A2","module":"Módulo 12: В квартире (A Dacha e Casas Russas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Atendendo ao Telefone","secondary":"Алло! / Слушаю! / Да-да!","desc":"Ao atender uma chamada em russo, usam-se as expressões \"Алло!\" ou \"Слушаю!\" (Literalmente: \"Estou ouvindo!\").","context":"Ex: \"Алло! Здравствуйте, я слушаю. — \"Alô! Olá, estou ouvindo.\"\"","audio":"Atendendo ao Telefone","level":"A2","module":"Módulo 13: Звонок по телефону (Ligações e Mensagens)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pedindo para Falar com Alguém","secondary":"Можно + [Nome] + к телефону?","desc":"Para solicitar a presença de alguém na linha, usa-se \"Можно + [Nome no Acusativo/Genitivo] + к телефону?\".","context":"Ex: \"Можно Анну к телефону? — \"Posso falar com a Anna?\"\"","audio":"Pedindo para Falar com Alguém","level":"A2","module":"Módulo 13: Звонок по телефону (Ligações e Mensagens)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Алло","secondary":"[ Allo ] — Alô","desc":"","audio":"Алло","level":"A2","module":"Módulo 13: Звонок по телефону (Ligações e Mensagens)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Слушаю","secondary":"[ Slushayu ] — Pode falar / Estou ouvindo","desc":"","audio":"Слушаю","level":"A2","module":"Módulo 13: Звонок по телефону (Ligações e Mensagens)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Перезвонить","secondary":"[ Perezvonit ] — Retornar a ligação","desc":"","audio":"Перезвонить","level":"A2","module":"Módulo 13: Звонок по телефону (Ligações e Mensagens)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сообщение","secondary":"[ Soobscheniye ] — Mensagem de texto","desc":"","audio":"Сообщение","level":"A2","module":"Módulo 13: Звонок по телефону (Ligações e Mensagens)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Encontrar-se com Alguém (Встречаться с)","secondary":"Встречаться с + [Pessoa no Instrumental]","desc":"O verbo reflexivo Встречаться (ou встретиться) exige a preposição С seguida do Caso Instrumental.","context":"Ex: \"Я встречаюсь с другом. — \"Eu vou me encontrar com meu amigo.\"\"","audio":"Encontrar-se com Alguém (Встречаться с)","level":"A2","module":"Módulo 14: Приглашение и встречи (Convites e Encontros)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fazendo Convites com Давай","secondary":"Давай / Давайте + [Ação no Infinitivo/Futuro]","desc":"Usa-se \"Давай\" (informal) ou \"Давайте\" (formal) para convidar alguém a fazer algo.","context":"Ex: \"Давай пойдём в кино! — \"Vamos ao cinema!\"\"","audio":"Fazendo Convites com Давай","level":"A2","module":"Módulo 14: Приглашение и встречи (Convites e Encontros)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Давай","secondary":"[ Davai ] — Vamos! / Bora!","desc":"","audio":"Давай","level":"A2","module":"Módulo 14: Приглашение и встречи (Convites e Encontros)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Встреча","secondary":"[ Vstrecha ] — Encontro / Reunião","desc":"","audio":"Встреча","level":"A2","module":"Módulo 14: Приглашение и встречи (Convites e Encontros)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Встречаться","secondary":"[ Vstrechat-sya ] — Encontrar-se","desc":"","audio":"Встречаться","level":"A2","module":"Módulo 14: Приглашение и встречи (Convites e Encontros)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"С удовольствием","secondary":"[ S udovolstviyem ] — Com prazer!","desc":"","audio":"С удовольствием","level":"A2","module":"Módulo 14: Приглашение и встречи (Convites e Encontros)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"К сожалению","secondary":"[ K sozhaleniyu ] — Infelizmente","desc":"","audio":"К сожалению","level":"A2","module":"Módulo 14: Приглашение и встречи (Convites e Encontros)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Идти vs. Ехать (Verbos de Movimento)","secondary":"Идти (А pé) vs. Ехать (De veículo)","desc":"Em russo é OBRIGATÓRIO diferenciar o meio de deslocamento: usa-se Идти quando a pessoa vai A PÉ, e Ехать quando vai por QUALQUER VEÍCULO (carro, trem, ônibus).","context":"Ex: \"Я иду в парк (a pé) / Я еду в Москву (de veículo) — \"Vou ao parque a pé / Vou a Moscou de transporte\"\"","audio":"Идти vs. Ехать (Verbos de Movimento)","level":"A2","module":"Módulo 15: Путешествия по России (Transiberiana)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Ferrovia Transiberiana (Транссиб)","secondary":"Ехать на поезде по Транссибу","desc":"A famosa ferrovia conecta Moscou a Vladivostok cruzando toda a Sibéria. Para viajar de trem usa-se Ехать на поезде.","context":"Ex: \"Мы едем на поезде в Сибирь. — \"Estamos indo de trem para a Sibéria.\"\"","audio":"A Ferrovia Transiberiana (Транссиб)","level":"A2","module":"Módulo 15: Путешествия по России (Transiberiana)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Транссиб","secondary":"[ Transsib ] — Transiberiana (ferrovia)","desc":"","audio":"Транссиб","level":"A2","module":"Módulo 15: Путешествия по России (Transiberiana)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Идти","secondary":"[ Idti ] — Ir a pé","desc":"","audio":"Идти","level":"A2","module":"Módulo 15: Путешествия по России (Transiberiana)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Teatro Bolshoi e o Hermitage","secondary":"В Большом театре / В Эрмитаже","desc":"O Большой театр (Moscou) é o templo mundial do balé e ópera; o Эрмитаж (São Petersburgo) é um dos maiores museus de arte do planeta.","context":"Ex: \"Вчера мы были в Большом театре. — \"Ontem estávamos no Teatro Bolshoi.\"\"","audio":"O Teatro Bolshoi e o Hermitage","level":"A2","module":"Módulo 16: В театре и музее (Teatro Bolshoi e Hermitage)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Comprando Ingressos na Bilheteria (Касса)","secondary":"Билеты на + [Espetáculo/Dia no Acusativo]","desc":"Para pedir ingressos usa-se \"Дайте, пожалуйста, билеты на...\".","context":"Ex: \"Дайте два билета на балет. — \"Me dê dois ingressos para o balé.\"\"","audio":"Comprando Ingressos na Bilheteria (Касса)","level":"A2","module":"Módulo 16: В театре и музее (Teatro Bolshoi e Hermitage)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Театр","secondary":"[ Teatr ] — Teatro","desc":"","audio":"Театр","level":"A2","module":"Módulo 16: В театре и музее (Teatro Bolshoi e Hermitage)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Балет","secondary":"[ Balet ] — Balé","desc":"","audio":"Балет","level":"A2","module":"Módulo 16: В театре и музее (Teatro Bolshoi e Hermitage)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Музей","secondary":"[ Muzey ] — Museu","desc":"","audio":"Музей","level":"A2","module":"Módulo 16: В театре и музее (Teatro Bolshoi e Hermitage)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Выставка","secondary":"[ Vystavka ] — Exposição / Mostra","desc":"","audio":"Выставка","level":"A2","module":"Módulo 16: В театре и музее (Teatro Bolshoi e Hermitage)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Касса","secondary":"[ Kassa ] — Bilheteria / Guichê","desc":"","audio":"Касса","level":"A2","module":"Módulo 16: В театре и музее (Teatro Bolshoi e Hermitage)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Advérbios de Estação (Caso Instrumental)","secondary":"Зима ➔ Зимой | Весна ➔ Весной | Лето ➔ Летом | Осень ➔ Осенью","desc":"Para responder a \"Quando?\" referente a uma estação do ano, usa-se a forma do Caso Instrumental do substantivo.","context":"Ex: \"Зимой очень холодно. Летом жарко. — \"No inverno é muito frio. No verão é quente.\"\"","audio":"Advérbios de Estação (Caso Instrumental)","level":"A2","module":"Módulo 17: Природа и сезоны (Natureza e Estações do Ano)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"As Quatro Estações na Rússia","secondary":"Зима (Inverno) / Весна (Primavera) / Лето (Verão) / Осень (Outono)","desc":"A Rússia vive transformações drásticas entre o inverno congelante (зима) e o verão ensolarado (лето).","context":"Ex: \"Весной природа красивая. — \"Na primavera a natureza é bonita.\"\"","audio":"As Quatro Estações na Rússia","level":"A2","module":"Módulo 17: Природа и сезоны (Natureza e Estações do Ano)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Зимой","secondary":"[ Zimoi ] — No inverno","desc":"","audio":"Зимой","level":"A2","module":"Módulo 17: Природа и сезоны (Natureza e Estações do Ano)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Весной","secondary":"[ Vesnoi ] — Na primavera","desc":"","audio":"Весной","level":"A2","module":"Módulo 17: Природа и сезоны (Natureza e Estações do Ano)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Летом","secondary":"[ Letom ] — No verão","desc":"","audio":"Летом","level":"A2","module":"Módulo 17: Природа и сезоны (Natureza e Estações do Ano)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Осенью","secondary":"[ Osenyu ] — No outono","desc":"","audio":"Осенью","level":"A2","module":"Módulo 17: Природа и сезоны (Natureza e Estações do Ano)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Природа","secondary":"[ Priroda ] — Natureza","desc":"","audio":"Природа","level":"A2","module":"Módulo 17: Природа и сезоны (Natureza e Estações do Ano)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Saudações de Abertura em Cartas","secondary":"Дорогой + [Nome Masc] / Дорогая + [Nome Fem]","desc":"Usa-se \"Дорогой\" (para homens) ou \"Дорогая\" (para mulheres) em mensagens afetuosas informais, e \"Уважаемый/Уважаемая\" para contextos formais.","context":"Ex: \"Дорогой Иван! / Дорогая Анна! — \"Querido Ivan! / Querida Anna!\"\"","audio":"Saudações de Abertura em Cartas","level":"A2","module":"Módulo 18: Письма и e-mail (Redação Informal)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fórmulas de Encerramento","secondary":"С уважением (Atenciosamente) / Обнимаю (Abraços)","desc":"Em cartas informais usam-se \"Обнимаю\" (Abraços) ou \"Всего доброго\" (Tudo de bom). Em e-mails formais usa-se \"С уважением\" (Atenciosamente).","context":"Ex: \"С уважением, Viktor Petrov. — \"Atenciosamente, Viktor Petrov.\"\"","audio":"Fórmulas de Encerramento","level":"A2","module":"Módulo 18: Письма и e-mail (Redação Informal)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дорогой","secondary":"[ Dorogoy ] — Querido (masculino)","desc":"","audio":"Дорогой","level":"A2","module":"Módulo 18: Письма и e-mail (Redação Informal)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Уважаемый","secondary":"[ Uvazhayemy ] — Prezado / Respeitável (formal)","desc":"","audio":"Уважаемый","level":"A2","module":"Módulo 18: Письма и e-mail (Redação Informal)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"С уважением","secondary":"[ S uvazheniyem ] — Atenciosamente","desc":"","audio":"С уважением","level":"A2","module":"Módulo 18: Письма и e-mail (Redação Informal)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Обнимаю","secondary":"[ Obnimayu ] — Um abraço / Abraços","desc":"","audio":"Обнимаю","level":"A2","module":"Módulo 18: Письма и e-mail (Redação Informal)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Imperativo de Emergência","secondary":"Помогите! (Ajude/Ajudem!) | Скажите! (Diga!) | Извините! (Desculpe!)","desc":"Para pedir ajuda urgente a desconhecidos ou autoridades, usa-se a forma do Imperativo no plural/formal terminada em -те / -ите.","context":"Ex: \"Помогите, пожалуйста! — \"Por favor, me ajudem!\"\"","audio":"Imperativo de Emergência","level":"A2","module":"Módulo 19: Проблемы в поездке (Imprevistos e Ajuda)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Perda de Objetos","secondary":"","desc":"Usa-se o verbo Потерять (perder) no passado: Я потерял (Masc) / Я потеряла (Fem).","context":"Ex: \"Я потерял паспорт e деньги. — \"Eu perdi o passaporte e o dinheiro.\"\"","audio":"Expressando Perda de Objetos","level":"A2","module":"Módulo 19: Проблемы в поездке (Imprevistos e Ajuda)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Помогите!","secondary":"[ Pomogite! ] — Socorro! / Me ajudem!","desc":"","audio":"Помогите!","level":"A2","module":"Módulo 19: Проблемы в поездке (Imprevistos e Ajuda)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Потерял","secondary":"[ Poteryal ] — Perdi (masculino)","desc":"","audio":"Потерял","level":"A2","module":"Módulo 19: Проблемы в поездке (Imprevistos e Ajuda)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Потеряла","secondary":"[ Poteryala ] — Perdi (feminino)","desc":"","audio":"Потеряла","level":"A2","module":"Módulo 19: Проблемы в поездке (Imprevistos e Ajuda)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Полиция","secondary":"[ Politsiya ] — Polícia","desc":"","audio":"Полиция","level":"A2","module":"Módulo 19: Проблемы в поездке (Imprevistos e Ajuda)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Поликлиника","secondary":"[ Poliklinika ] — Posto de saúde / Clínica","desc":"","audio":"Поликлиника","level":"A2","module":"Módulo 19: Проблемы в поездке (Imprevistos e Ajuda)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Construção Dativo Impessoal de Estado","secondary":"Мне / Тебе / Ему / Ей + [Advérbio de Estado]","desc":"Em russo, estados emocionais e sensações físicas não usam o verbo ter/ser diretamente, mas sim o Caso Dativo do pronome (Мне, Тебе, Ему, Ей, Нам) + um advérbio curto de estado.","context":"Ex: \"Мне грустно / Мне весело / Мне холодно — \"Estou triste / Estou feliz / Estou com frio\"\"","audio":"Construção Dativo Impessoal de Estado","level":"A2","module":"Módulo 20: Чувства и эмоции (Sentimentos e Emoções)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Advérbios de Emoção","secondary":"","desc":"Principais estados: Весело (Alegre/Divertido), Грустно (Triste), Скучно (Entediado), Интересно (Interessante).","context":"Ex: \"Нам очень интересно. — \"Estamos achando muito interessante.\"\"","audio":"Advérbios de Emoção","level":"A2","module":"Módulo 20: Чувства и эмоции (Sentimentos e Emoções)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мне грустно","secondary":"[ Mne grustno ] — Estou triste","desc":"","audio":"Мне грустно","level":"A2","module":"Módulo 20: Чувства и эмоции (Sentimentos e Emoções)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мне весело","secondary":"[ Mne veselo ] — Estou alegre / divertido","desc":"","audio":"Мне весело","level":"A2","module":"Módulo 20: Чувства и эмоции (Sentimentos e Emoções)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мне скучно","secondary":"[ Mne skuchno ] — Estou entediado(a)","desc":"","audio":"Мне скучно","level":"A2","module":"Módulo 20: Чувства и эмоции (Sentimentos e Emoções)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мне интересно","secondary":"[ Mne interesno ] — Acho interessante / Tenho interesse","desc":"","audio":"Мне интересно","level":"A2","module":"Módulo 20: Чувства и эмоции (Sentimentos e Emoções)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Радость","secondary":"[ Radost ] — Alegria","desc":"","audio":"Радость","level":"A2","module":"Módulo 20: Чувства и эмоции (Sentimentos e Emoções)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Играть в + Acusativo (Esportes e Jogos)","secondary":"Играть в + [Esporte no Acusativo]","desc":"Para esportes, jogos e modalidades coletivas, usa-se o verbo Играть com a preposição В + Acusativo.","context":"Ex: \"Играть в футбол / Играть в хоккей / Играть в шахматы — \"Jogar futebol / Jogar hóquei / Jogar xadrez\"\"","audio":"Играть в + Acusativo (Esportes e Jogos)","level":"A2","module":"Módulo 21: Спорт и Здоровый образ жизни (Esportes)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Играть на + Preposicional (Instrumentos)","secondary":"Играть на + [Instrumento no Preposicional]","desc":"Para tocar instrumentos musicais, usa-se Играть com a preposição НА + Preposicional.","context":"Ex: \"Играть на гитаре / Играть на пианино — \"Tocar violão/guitarra / Tocar piano\"\"","audio":"Играть на + Preposicional (Instrumentos)","level":"A2","module":"Módulo 21: Спорт и Здоровый образ жизни (Esportes)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Футбол","secondary":"[ Futbol ] — Futebol","desc":"","audio":"Футбол","level":"A2","module":"Módulo 21: Спорт и Здоровый образ жизни (Esportes)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Хоккей","secondary":"[ Khokkey ] — Hóquei no gelo","desc":"","audio":"Хоккей","level":"A2","module":"Módulo 21: Спорт и Здоровый образ жизни (Esportes)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Гитаре","secondary":"[ Gitare ] — Violão / Guitarra (preposicional)","desc":"","audio":"Гитаре","level":"A2","module":"Módulo 21: Спорт и Здоровый образ жизни (Esportes)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пианино","secondary":"[ Pianino ] — Piano (indeclinável)","desc":"","audio":"Пианино","level":"A2","module":"Módulo 21: Спорт и Здоровый образ жизни (Esportes)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Спорт","secondary":"[ Sport ] — Esporte","desc":"","audio":"Спорт","level":"A2","module":"Módulo 21: Спорт и Здоровый образ жизни (Esportes)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Séculos no Preposicional (В ... веке)","secondary":"В + [Número Ordinal no Preposicional] + веке","desc":"Para se referir a fatos históricos ocorridos em determinado século, usa-se o número ordinal no Caso Preposicional seguido de \"веке\".","context":"Ex: \"В девятнадцатом веке (В XIX веке). — \"No século XIX.\"\"","audio":"Séculos no Preposicional (В ... веке)","level":"A2","module":"Módulo 22: История и Символы (Símbolos e História da Rússia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Símbolos Nacionais Russos","secondary":"Флаг (Bandeira) / Кремль (Kremlin) / История (História)","desc":"A bandeira tricolor (белый, синий, красный), o brasão da águia bicéfala (двуглавый орёл) e o Kremlin (Кремль) são os símbolos maiores da federação.","context":"Ex: \"Кремль — символ Москвы. — \"O Kremlin é o símbolo de Moscou.\"\"","audio":"Símbolos Nacionais Russos","level":"A2","module":"Módulo 22: История и Символы (Símbolos e História da Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"История","secondary":"[ Istoriya ] — História","desc":"","audio":"История","level":"A2","module":"Módulo 22: История и Символы (Símbolos e História da Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Век","secondary":"[ Vek ] — Século","desc":"","audio":"Век","level":"A2","module":"Módulo 22: История и Символы (Símbolos e História da Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Символ","secondary":"[ Simvol ] — Símbolo","desc":"","audio":"Символ","level":"A2","module":"Módulo 22: История и Символы (Símbolos e História da Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Флаг","secondary":"[ Flag ] — Bandeira","desc":"","audio":"Флаг","level":"A2","module":"Módulo 22: История и Символы (Símbolos e História da Rússia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Resumo dos Tempos e Aspectos A2","secondary":"Прошлое (-л) / Будущее (Буду+) / Аспект (НСВ vs СВ)","desc":"Revisão: Passado com sufixo -л, Futuro composto com Буду e distinção de aspecto (НСВ processo vs. СВ resultado).","context":"Ex: \"Я читал ➔ Я прочитал ➔ Я буду читать — \"Eu lia ➔ Eu li (concluí) ➔ Eu lerei\"\"","audio":"Resumo dos Tempos e Aspectos A2","level":"A2","module":"Módulo 23: Revisão Geral A2"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Resumo dos Casos A2","secondary":"Acusativo (Objeto) vs. Genitivo (Ausência/Posse)","desc":"Revisão: Acusativo Feminino (-у/-ю), Acusativo Masculino Animado (-а/-я) e Genitivo de Ausência (У меня нет...).","context":"Ex: \"Я знаю друга. У меня нет времени. — \"Conheço o amigo. Não tenho tempo.\"\"","audio":"Resumo dos Casos A2","level":"A2","module":"Módulo 23: Revisão Geral A2"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Прошлое","secondary":"[ Proshloye ] — O Passado","desc":"","audio":"Прошлое","level":"A2","module":"Módulo 23: Revisão Geral A2"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Будущее","secondary":"[ Buduscheye ] — O Futuro","desc":"","audio":"Будущее","level":"A2","module":"Módulo 23: Revisão Geral A2"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"У меня нет","secondary":"[ U menya net ] — Eu não tenho...","desc":"","audio":"У меня нет","level":"A2","module":"Módulo 23: Revisão Geral A2"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Заниматься","secondary":"[ Zanimat-sya ] — Praticar / Dedicar-se","desc":"","audio":"Заниматься","level":"A2","module":"Módulo 23: Revisão Geral A2"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Помогите","secondary":"[ Pomogite ] — Socorro! / Me ajudem!","desc":"","audio":"Помогите","level":"A2","module":"Módulo 23: Revisão Geral A2"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Certificação Interna Nível A2","secondary":"Comunicação Cotidiana (Nível A2 Concluído)","desc":"Ao concluir este teste integrado com sucesso, você terá domínios sólidos da gramática e conversação cotidiana do Nível A2.","context":"Ex: \"Поздравляем с успешным прохождением А2! — \"Parabéns pela conclusão com sucesso do A2!\"\"","audio":"Certificação Interna Nível A2","level":"A2","module":"Módulo 24: Desafio Final A2 (Expedição pela Rússia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estruturas Fundamentais A2","secondary":"Visão Geral do Nível A2 (Rumo ao Nível B1)","desc":"Passado (-л/-ла), Futuro (Буду+), Aspectos (НСВ/СВ), Acusativo, Genitivo, Instrumental e Expressões do Dia a Dia.","context":"Ex: \"Я буду путешествовать по России. — \"Eu vou viajar pela Rússia.\"\"","audio":"Estruturas Fundamentais A2","level":"A2","module":"Módulo 24: Desafio Final A2 (Expedição pela Rússia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Поздравляем!","secondary":"[ Pozdravlyayem! ] — Parabéns!","desc":"","audio":"Поздравляем!","level":"A2","module":"Módulo 24: Desafio Final A2 (Expedição pela Rússia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Dativo: Objeto Indireto (Destinatário)","secondary":"Masc/Neutro: -у/-ю | Fem: -е","desc":"O Caso Dativo responde a Кому? (A quem?). Substantivos masculinos e neutros ganham -у (ou -ю), e femininos terminados em -а mudam para -е.","context":"Ex: \"Друг ➔ Другу / Сестра ➔ Сестре — \"ao amigo / à irmã\"\"","audio":"Dativo: Objeto Indireto (Destinatário)","level":"B1","module":"Módulo 1: Дательный падеж I (Caso Dativo - Objeto Indireto)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbos de Comunicação + Dativo","secondary":"Звонить / Писать / Помогать + [Dativo]","desc":"Verbos como Звонить (ligar), Писать (escrever), Давать (dar) e Помогать (ajudar) exigem obrigatoriamente o Caso Dativo.","context":"Ex: \"Я звоню маме. / Он помогает брату. — \"Ligo para a mãe. / Ele ajuda o irmão.\"\"","audio":"Verbos de Comunicação + Dativo","level":"B1","module":"Módulo 1: Дательный падеж I (Caso Dativo - Objeto Indireto)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pronomes Pessoais no Caso Dativo","secondary":"Мне / Тебе / Ему / Ей / Нам / Вам / Им","desc":"Os pronomes no Dativo são: Мне (a mim), Тебе (a ti), Ему (a ele), Ей (a ela), Нам (a nós), Вам (a vocês), Им (a eles).","context":"Ex: \"Он дал мне книгу. — \"Ele me deu o livro.\"\"","audio":"Pronomes Pessoais no Caso Dativo","level":"B1","module":"Módulo 1: Дательный падеж I (Caso Dativo - Objeto Indireto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Другу","secondary":"[ Drugu ] — Ao amigo (dativo)","desc":"","audio":"Другу","level":"B1","module":"Módulo 1: Дательный падеж I (Caso Dativo - Objeto Indireto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сестре","secondary":"[ Sestre ] — À irmã (dativo)","desc":"","audio":"Сестре","level":"B1","module":"Módulo 1: Дательный падеж I (Caso Dativo - Objeto Indireto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Звонить","secondary":"[ Zvonit ] — Ligar por telefone (+ Dativo)","desc":"","audio":"Звонить","level":"B1","module":"Módulo 1: Дательный падеж I (Caso Dativo - Objeto Indireto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Помогать","secondary":"[ Pomogat ] — Ajudar (+ Dativo)","desc":"","audio":"Помогать","level":"B1","module":"Módulo 1: Дательный падеж I (Caso Dativo - Objeto Indireto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мне","secondary":"[ Mne ] — A mim / Para mim","desc":"","audio":"Мне","level":"B1","module":"Módulo 1: Дательный падеж I (Caso Dativo - Objeto Indireto)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Idade com Dativo","secondary":"[Pessoa no Dativo] + [Número] + лет / года / год","desc":"Em russo, para dizer a idade de alguém, coloca-se a pessoa no Caso Dativo + o número + лет/goda.","context":"Ex: \"Мне 25 лет. / Ему 3 года. — \"Eu tenho 25 anos. / Ele tem 3 anos.\"\"","audio":"Expressando Idade com Dativo","level":"B1","module":"Módulo 2: Дательный падеж II (Idade e Frases Impessoais)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Necessidade Impessoal (Мне нужно)","secondary":"Мне / Тебе / Ему + нужно + [Infinitivo]","desc":"Para dizer que precisa de algo, usa-se a construção: [Dativo] + нужно / надо + [Infinitivo].","context":"Ex: \"Мне нужно купить хлеб. — \"Eu preciso comprar pão.\"\"","audio":"Necessidade Impessoal (Мне нужно)","level":"B1","module":"Módulo 2: Дательный падеж II (Idade e Frases Impessoais)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Permissão e Proibição (Можно / Нельзя)","secondary":"Вам можно войти. / Здесь нельзя курить.","desc":"Usa-se Можно (é permitido / pode-se) e Нельзя (é proibido / não se pode) com o Dativo.","context":"Ex: \"Você pode entrar. / Aqui é proibido fumar. — \"Pode entrar. / Proibido fumar aqui.\"\"","audio":"Permissão e Proibição (Можно / Нельзя)","level":"B1","module":"Módulo 2: Дательный падеж II (Idade e Frases Impessoais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мне нужно","secondary":"[ Mne nuzhno ] — Eu preciso","desc":"","audio":"Мне нужно","level":"B1","module":"Módulo 2: Дательный падеж II (Idade e Frases Impessoais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Можно","secondary":"[ Mozhno ] — Pode-se / É permitido","desc":"","audio":"Можно","level":"B1","module":"Módulo 2: Дательный падеж II (Idade e Frases Impessoais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Нельзя","secondary":"[ Nelsya ] — É proibido / Não se pode","desc":"","audio":"Нельзя","level":"B1","module":"Módulo 2: Дательный падеж II (Idade e Frases Impessoais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ему","secondary":"[ Yemu ] — A ele / Para ele","desc":"","audio":"Ему","level":"B1","module":"Módulo 2: Дательный падеж II (Idade e Frases Impessoais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Надо","secondary":"[ Nado ] — É preciso / É necessário","desc":"","audio":"Надо","level":"B1","module":"Módulo 2: Дательный падеж II (Idade e Frases Impessoais)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Companhia com a Preposição С","secondary":"С + [Substantivo no Instrumental]","desc":"Para indicar a companhia de alguém (\"com\"), usa-se a preposição С seguida obrigatoriamente do Caso Instrumental.","context":"Ex: \"С другом / С сестрой / С коллегой — \"Com o amigo / Com a irmã / Com o colega\"\"","audio":"Companhia com a Preposição С","level":"B1","module":"Módulo 3: Творительный падеж I (Caso Instrumental - Instrumento e Companhia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Instrumento / Ferramenta (Sem Preposição)","secondary":"[Substantivo no Instrumental sem preposição]","desc":"Para indicar a ferramenta ou objeto com o qual se realiza uma ação, usa-se o Caso Instrumental DIRETO (sem preposição).","context":"Ex: \"Писать ручкой (escrever com caneta) / Есть вилкой (comer com garfo) — \"Escrever a caneta / Comer de garfo\"\"","audio":"Instrumento / Ferramenta (Sem Preposição)","level":"B1","module":"Módulo 3: Творительный падеж I (Caso Instrumental - Instrumento e Companhia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Terminações do Instrumental Singular","secondary":"Masc/Neutro: -ом/-ем | Fem: -ой/-ей","desc":"Substantivos masculinos e neutros ganham -ом (ou -ем). Femininos em -а/-я trocam por -ой (ou -ей).","context":"Ex: \"Брат ➔ Братом / Машина ➔ Машиной — \"com o irmão / de carro\"\"","audio":"Terminações do Instrumental Singular","level":"B1","module":"Módulo 3: Творительный падеж I (Caso Instrumental - Instrumento e Companhia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"С другом","secondary":"[ S drugom ] — Com o amigo (instrumental)","desc":"","audio":"С другом","level":"B1","module":"Módulo 3: Творительный падеж I (Caso Instrumental - Instrumento e Companhia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"С сестрой","secondary":"[ S sestroi ] — Com a irmã (instrumental)","desc":"","audio":"С сестрой","level":"B1","module":"Módulo 3: Творительный падеж I (Caso Instrumental - Instrumento e Companhia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ручкой","secondary":"[ Ruchkoi ] — Com/de caneta (instrumental)","desc":"","audio":"Ручкой","level":"B1","module":"Módulo 3: Творительный падеж I (Caso Instrumental - Instrumento e Companhia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вилкой","secondary":"[ Vilkoi ] — Com/de garfo (instrumental)","desc":"","audio":"Вилкой","level":"B1","module":"Módulo 3: Творительный падеж I (Caso Instrumental - Instrumento e Companhia)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"С кем","secondary":"[ S kem ] — Com quem?","desc":"","audio":"С кем","level":"B1","module":"Módulo 3: Творительный падеж I (Caso Instrumental - Instrumento e Companhia)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Profissões com Работать + Instrumental","secondary":"Работать + [Profissão no Instrumental]","desc":"Em russo, para dizer a profissão de alguém com o verbo Работать (trabalhar), o cargo/profissão entra obrigatoriamente no Caso Instrumental.","context":"Ex: \"Работать врачом / Работать учителем / Работать инженером — \"Trabalhar como médico / professor / engenheiro\"\"","audio":"Profissões com Работать + Instrumental","level":"B1","module":"Módulo 4: Творительный падеж II (Profissão e Mudança de Estado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Mudança de Estado com Стать + Instrumental","secondary":"Стать + [Substantivo no Instrumental]","desc":"O verbo Стать (tornar-se) exige o Caso Instrumental.","context":"Ex: \"Он стал врачом. — \"Ele se tornou médico.\"\"","audio":"Mudança de Estado com Стать + Instrumental","level":"B1","module":"Módulo 4: Творительный падеж II (Profissão e Mudança de Estado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbo Быть no Passado/Futuro","secondary":"Был / Будет + [Profissão no Instrumental]","desc":"Quando o verbo Быть é usado no passado ou futuro para definir uma profissão ou papel temporário, a profissão fica no Instrumental.","context":"Ex: \"Раньше он был студентом. — \"Antes ele era estudante.\"\"","audio":"Verbo Быть no Passado/Futuro","level":"B1","module":"Módulo 4: Творительный падеж II (Profissão e Mudança de Estado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Врачом","secondary":"[ Vrachom ] — Como médico (instrumental)","desc":"","audio":"Врачом","level":"B1","module":"Módulo 4: Творительный падеж II (Profissão e Mudança de Estado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Учителем","secondary":"[ Uchitelem ] — Como professor (instrumental)","desc":"","audio":"Учителем","level":"B1","module":"Módulo 4: Творительный падеж II (Profissão e Mudança de Estado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Стать","secondary":"[ Stat ] — Tornar-se (+ Instrumental)","desc":"","audio":"Стать","level":"B1","module":"Módulo 4: Творительный падеж II (Profissão e Mudança de Estado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Кем","secondary":"[ Kem ] — Como o quê? / De quê?","desc":"","audio":"Кем","level":"B1","module":"Módulo 4: Творительный падеж II (Profissão e Mudança de Estado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Unidirecional a Pé: Идти","secondary":"Идти (одно направление / сейчас)","desc":"O verbo Идти indica um movimento A PÉ acontecendo AGORA em uma única direção específica em direção a um objetivo.","context":"Ex: \"Сейчас я иду в магазин. — \"Agora estou indo à loja (a pé).\"\"","audio":"Unidirecional a Pé: Идти","level":"B1","module":"Módulo 5: Глаголы движения I (Verbos de Movimento Sem Prefixo - Ir a pé)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Multidirecional a Pé: Ходить","secondary":"Ходить (повторение / туда и обратно)","desc":"O verbo Ходить indica um movimento A PÉ habitual (frequência), sem direção única, ou uma viagem completa de IDA E VOLTA já concluída.","context":"Ex: \"Каждый день я хожу в парк. / Вчера я ходил в музей. — \"Todo dia vou ao parque. / Ontem fui ao museu (e voltei).\"\"","audio":"Multidirecional a Pé: Ходить","level":"B1","module":"Módulo 5: Глаголы движения I (Verbos de Movimento Sem Prefixo - Ir a pé)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conjugação dos Verbos Идти e Ходить","secondary":"Идти (шёл/шла) vs. Ходить (ходил/ходила)","desc":"Идти: иду, идёшь, идут. Passado: шёл, шла, шли. | Ходить: хожу, ходишь, ходят. Passado: ходил, ходила, ходили.","context":"Ex: \"Вчера он ходил в кино. — \"Ontem ele foi ao cinema (ida e volta).\"\"","audio":"Conjugação dos Verbos Идти e Ходить","level":"B1","module":"Módulo 5: Глаголы движения I (Verbos de Movimento Sem Prefixo - Ir a pé)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ходить","secondary":"[ Khodit ] — Ir/Andar a pé (multidirecional/hábito)","desc":"","audio":"Ходить","level":"B1","module":"Módulo 5: Глаголы движения I (Verbos de Movimento Sem Prefixo - Ir a pé)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Шёл","secondary":"[ Shyol ] — Ia a pé / Foi (masculino passado de идти)","desc":"","audio":"Шёл","level":"B1","module":"Módulo 5: Глаголы движения I (Verbos de Movimento Sem Prefixo - Ir a pé)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Шла","secondary":"[ Shla ] — Ia a pé / Foi (feminino passado de идти)","desc":"","audio":"Шла","level":"B1","module":"Módulo 5: Глаголы движения I (Verbos de Movimento Sem Prefixo - Ir a pé)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пешком","secondary":"[ Peshkom ] — A pé","desc":"","audio":"Пешком","level":"B1","module":"Módulo 5: Глаголы движения I (Verbos de Movimento Sem Prefixo - Ir a pé)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Unidirecional de Transporte: Ехать","secondary":"Ехать (транспорт / одно направление)","desc":"O verbo Ехать indica que a pessoa está viajando POR UM VEÍCULO agora, em uma direção específica.","context":"Ex: \"Сейчас мы едем в Санкт-Петербург. — \"Agora estamos indo para São Petersburgo (de transporte).\"\"","audio":"Unidirecional de Transporte: Ехать","level":"B1","module":"Módulo 6: Глаголы движения II (Verbos de Movimento Sem Prefixo - Ir de Transporte)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Multidirecional de Transporte: Ездить","secondary":"Ездить (транспорт / повторение / туда и обратно)","desc":"O verbo Ездить indica viagens de transporte repetidas, hábitos ou passeios de ida e volta já concluídos.","context":"Ex: \"Каждое лето мы ездим на море. — \"Todo verão nós viajamos para o mar.\"\"","audio":"Multidirecional de Transporte: Ездить","level":"B1","module":"Módulo 6: Глаголы движения II (Verbos de Movimento Sem Prefixo - Ir de Transporte)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Meios de Transporte no Caso Preposicional","secondary":"На + [Transporte no Preposicional]","desc":"Para indicar o meio de transporte, usa-se a preposição НА + Preposicional (-е).","context":"Ex: \"На машине / На автобусе / На поезде — \"De carro / De ônibus / De trem\"\"","audio":"Meios de Transporte no Caso Preposicional","level":"B1","module":"Módulo 6: Глаголы движения II (Verbos de Movimento Sem Prefixo - Ir de Transporte)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ездить","secondary":"[ Yezdit ] — Viajar/Ir de veículo (multidirecional/hábito)","desc":"","audio":"Ездить","level":"B1","module":"Módulo 6: Глаголы движения II (Verbos de Movimento Sem Prefixo - Ir de Transporte)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"На машине","secondary":"[ Na mashine ] — De carro","desc":"","audio":"На машине","level":"B1","module":"Módulo 6: Глаголы движения II (Verbos de Movimento Sem Prefixo - Ir de Transporte)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"На автобусе","secondary":"[ Na avtobuse ] — De ônibus","desc":"","audio":"На автобусе","level":"B1","module":"Módulo 6: Глаголы движения II (Verbos de Movimento Sem Prefixo - Ir de Transporte)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Еду","secondary":"[ Yedu ] — Eu vou (de veículo)","desc":"","audio":"Еду","level":"B1","module":"Módulo 6: Глаголы движения II (Verbos de Movimento Sem Prefixo - Ir de Transporte)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Prefixo По-: Partida / Início do Movimento","secondary":"По- + [Verbo de Movimento]","desc":"O prefixo По- adicionado a um verbo de movimento indica o INÍCIO da viagem ou a decisão de partir.","context":"Ex: \"Пойти (começar a ir a pé) / Поехать (partir de transporte) — \"Partir a pé / Partir de veículo\"\"","audio":"Prefixo По-: Partida / Início do Movimento","level":"B1","module":"Módulo 7: Глаголы движения III (Prefixos de Movimento: По-, При-, У-)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Prefixo При-: Chegada ao Destino","secondary":"При- + [Verbo de Movimento]","desc":"O prefixo При- indica CHEGADA ou aproximação final ao local de destino.","context":"Ex: \"Прийти (chegar a pé) / Приехать (chegar de transporte) — \"Chegar a pé / Chegar de veículo\"\"","audio":"Prefixo При-: Chegada ao Destino","level":"B1","module":"Módulo 7: Глаголы движения III (Prefixos de Movimento: По-, При-, У-)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Prefixo У-: Partida Definitiva / Ausência","secondary":"У- + [Verbo de Movimento]","desc":"O prefixo У- indica que o sujeito SAIS E FICOU AUSENTE do local.","context":"Ex: \"Уйти (sair/ir embora a pé) / Уехать (viajar para fora/embora) — \"Ir embora a pé / Viajar para longe\"\"","audio":"Prefixo У-: Partida Definitiva / Ausência","level":"B1","module":"Módulo 7: Глаголы движения III (Prefixos de Movimento: По-, При-, У-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Поехать","secondary":"[ Poyekhat ] — Partir de veículo / Viajar","desc":"","audio":"Поехать","level":"B1","module":"Módulo 7: Глаголы движения III (Prefixos de Movimento: По-, При-, У-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Приехать","secondary":"[ Priyekhat ] — Chegar de veículo","desc":"","audio":"Приехать","level":"B1","module":"Módulo 7: Глаголы движения III (Prefixos de Movimento: По-, При-, У-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Уехать","secondary":"[ Uyekhat ] — Viajar para longe / Ir embora de transporte","desc":"","audio":"Уехать","level":"B1","module":"Módulo 7: Глаголы движения III (Prefixos de Movimento: По-, При-, У-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Прийти","secondary":"[ Priyti ] — Chegar a pé","desc":"","audio":"Прийти","level":"B1","module":"Módulo 7: Глаголы движения III (Prefixos de Movimento: По-, При-, У-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Уйти","secondary":"[ Uyti ] — Sair / Ir embora a pé","desc":"","audio":"Уйти","level":"B1","module":"Módulo 7: Глаголы движения III (Prefixos de Movimento: По-, При-, У-)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Prefixos В- (Entrar) e Вы- (Sair)","secondary":"В- + [Verbo] + в / Вы- + [Verbo] + из","desc":"O prefixo В- indica ENTRAR em um espaço fechado (exige preposição В), enquanto Вы- indica SAIR de dentro (exige preposição Из).","context":"Ex: \"Войти в комнату / Выйти из комнаты — \"Entrar no quarto / Sair do quarto\"\"","audio":"Prefixos В- (Entrar) e Вы- (Sair)","level":"B1","module":"Módulo 8: Глаголы движения IV (Prefixos de Movimento: В-, Вы-, Про-, Пере-)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Prefixo Про-: Passar por / Percorrer","secondary":"Про- + [Verbo] + мимо / через","desc":"O prefixo Про- indica passar ao lado de algo, percorrer uma distância ou passar reto sem parar.","context":"Ex: \"Пройти мимо дома / Проехать 100 километров — \"Passar ao lado da casa / Percorrer 100 km\"\"","audio":"Prefixo Про-: Passar por / Percorrer","level":"B1","module":"Módulo 8: Глаголы движения IV (Prefixos de Movimento: В-, Вы-, Про-, Пере-)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Prefixo Пере-: Atravessar / Mudar","secondary":"Пере- + [Verbo] + через","desc":"O prefixo Пере- indica atravessar de um lado ao outro (rua, rio) ou mudar de residência.","context":"Ex: \"Перейти улицу / Переехать в новую квартиру — \"Atravessar a rua / Mudar-se para novo apartamento\"\"","audio":"Prefixo Пере-: Atravessar / Mudar","level":"B1","module":"Módulo 8: Глаголы движения IV (Prefixos de Movimento: В-, Вы-, Про-, Пере-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Войти","secondary":"[ Voyti ] — Entrar a pé","desc":"","audio":"Войти","level":"B1","module":"Módulo 8: Глаголы движения IV (Prefixos de Movimento: В-, Вы-, Про-, Пере-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Выйти","secondary":"[ Vyti ] — Sair a pé","desc":"","audio":"Выйти","level":"B1","module":"Módulo 8: Глаголы движения IV (Prefixos de Movimento: В-, Вы-, Про-, Пере-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Перейти","secondary":"[ Pereyti ] — Atravessar a pé","desc":"","audio":"Перейти","level":"B1","module":"Módulo 8: Глаголы движения IV (Prefixos de Movimento: В-, Вы-, Про-, Пере-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пройти","secondary":"[ Proyti ] — Passar por / Percorrer a pé","desc":"","audio":"Пройти","level":"B1","module":"Módulo 8: Глаголы движения IV (Prefixos de Movimento: В-, Вы-, Про-, Пере-)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Переехать","secondary":"[ Pereyekhat ] — Mudar-se (de residência)","desc":"","audio":"Переехать","level":"B1","module":"Módulo 8: Глаголы движения IV (Prefixos de Movimento: В-, Вы-, Про-, Пере-)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Passado: Processo (НСВ) vs. Conclusão (СВ)","secondary":"Долго + [НСВ] ➔ Наконец + [СВ]","desc":"No passado, usa-se o Imperfeito (НСВ) para enfatizar o TEMPO GASTO ou a repetição, e o Perfeito (СВ) para celebrar o RESULTADO OBTIDO.","context":"Ex: \"Я долго готовил ужин и приготовил его. — \"Cozinhei por muito tempo e (finalmente) preparei a janta.\"\"","audio":"Passado: Processo (НСВ) vs. Conclusão (СВ)","level":"B1","module":"Módulo 9: Аспект глагола II (Aspecto no Passado e Futuro)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Futuro: Intenção Geral vs. Compromisso de Entrega","secondary":"Буду делать (НСВ) vs Сделаю (СВ)","desc":"No futuro, o Imperfeito (Буду делать) indica a intenção de estar fazendo a ação, enquanto o Perfeito (Сделаю) garante o resultado final.","context":"Ex: \"Завтра я буду читать. / Завтра я прочитаю эту статью. — \"Amanhã estarei lendo. / Amanhã lerei (e terminarei) este artigo.\"\"","audio":"Futuro: Intenção Geral vs. Compromisso de Entrega","level":"B1","module":"Módulo 9: Аспект глагола II (Aspecto no Passado e Futuro)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pares Verbais Essenciais B1","secondary":"[Imperfeito] / [Perfeito]","desc":"Pares frequentes: Решать / Решить (resolver), Готовить / Приготовить (cozinhar), Покупать / Купить (comprar).","context":"Ex: \"Покупать / Купить — \"Comprar (processo) / Comprar (conclusão)\"\"","audio":"Pares Verbais Essenciais B1","level":"B1","module":"Módulo 9: Аспект глагола II (Aspecto no Passado e Futuro)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Решать","secondary":"[ Reshat ] — Resolver / Tentar resolver (imperfeito)","desc":"","audio":"Решать","level":"B1","module":"Módulo 9: Аспект глагола II (Aspecto no Passado e Futuro)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Решить","secondary":"[ Reshit ] — Resolver / Concluir a solução (perfeito)","desc":"","audio":"Решить","level":"B1","module":"Módulo 9: Аспект глагола II (Aspecto no Passado e Futuro)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Готовить","secondary":"[ Gotovit ] — Cozinhar / Preparar (imperfeito)","desc":"","audio":"Готовить","level":"B1","module":"Módulo 9: Аспект глагола II (Aspecto no Passado e Futuro)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Приготовить","secondary":"[ Prigotovit ] — Preparar / Deixar pronto (perfeito)","desc":"","audio":"Приготовить","level":"B1","module":"Módulo 9: Аспект глагола II (Aspecto no Passado e Futuro)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Купить","secondary":"[ Kupit ] — Comprar (perfeito)","desc":"","audio":"Купить","level":"B1","module":"Módulo 9: Аспект глагола II (Aspecto no Passado e Futuro)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Imperativo Imperfeito: Convites Corteses","secondary":"Imperativo НСВ (приглашение / вежливость)","desc":"Para convidar alguém de forma cortês e calorosa a iniciar uma ação, usa-se o Imperativo do verbo IMPERFEITO.","context":"Ex: \"Садитесь! (Sente-se!) / Проходите! (Entre!) / Ешьте! (Coma!) — \"Sente-se, por favor! / Entre!\"\"","audio":"Imperativo Imperfeito: Convites Corteses","level":"B1","module":"Módulo 10: Аспект глагола III (Aspecto no Imperativo e Infinitivo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Imperativo Perfeito: Ordens e Pedidos Diretos","secondary":"Imperativo СВ (конкретная просьба / приказ)","desc":"Para dar uma instrução pontual, ordem ou pedido de execução imediata, usa-se o verbo PERFEITO.","context":"Ex: \"Откройте окно! / Прочитайте первую страницу! — \"Abra a janela! / Leia a primeira página!\"\"","audio":"Imperativo Perfeito: Ordens e Pedidos Diretos","level":"B1","module":"Módulo 10: Аспект глагола III (Aspecto no Imperativo e Infinitivo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Negação no Imperativo (Не + НСВ vs Не + СВ)","secondary":"Не + НСВ (запрет) vs Не + СВ (предостережение)","desc":"Не + Imperfeito proíbe um hábito ou ação (\"Не делай\" = Não faça). Не + Perfeito é um AVISO para evitar um acidente (\"Не сделай ошибку!\" = Cuidado para não errar!).","context":"Ex: \"Не курите здесь! vs Не упадите! — \"Não fume aqui! vs Cuidado para não cair!\"\"","audio":"Negação no Imperativo (Не + НСВ vs Не + СВ)","level":"B1","module":"Módulo 10: Аспект глагола III (Aspecto no Imperativo e Infinitivo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Садитесь!","secondary":"[ Sadites! ] — Sente-se! (convite cortês)","desc":"","audio":"Садитесь!","level":"B1","module":"Módulo 10: Аспект глагола III (Aspecto no Imperativo e Infinitivo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Проходите!","secondary":"[ Prokhodite! ] — Entre! / Pode passar!","desc":"","audio":"Проходите!","level":"B1","module":"Módulo 10: Аспект глагола III (Aspecto no Imperativo e Infinitivo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Откройте!","secondary":"[ Otkroyte! ] — Abra! (instrução direta)","desc":"","audio":"Откройте!","level":"B1","module":"Módulo 10: Аспект глагола III (Aspecto no Imperativo e Infinitivo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Прочитайте!","secondary":"[ Prochitayte! ] — Leia! (instrução de leitura)","desc":"","audio":"Прочитайте!","level":"B1","module":"Módulo 10: Аспект глагола III (Aspecto no Imperativo e Infinitivo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Не упадите!","secondary":"[ Ne upadite! ] — Cuidado para não cair!","desc":"","audio":"Не упадите!","level":"B1","module":"Módulo 10: Аспект глагола III (Aspecto no Imperativo e Infinitivo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Comparativo Sintético em -ее / -е","secondary":"Быстрый ➔ Быстрее | Громкий ➔ Громче | Высокий ➔ Выше","desc":"A maioria dos adjetivos forma o comparativo adicionando a terminação -ее (ou -е com alternância de consoantes: к➔ч, г➔ж, т➔ч).","context":"Ex: \"Поезд едет быстрее. — \"O trem vai mais rápido.\"\"","audio":"Comparativo Sintético em -ее / -е","level":"B1","module":"Módulo 11: Сравнительная степень (Comparativos e Superlativos Avançados)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Comparativos Irregulares Frequentes","secondary":"Лучше / Хуже / Больше / Меньше","desc":"Formas especiais: Хороший ➔ Лучше (melhor), Плохой ➔ Хуже (pior), Большой ➔ Больше (maior), Маленький ➔ Меньше (menor).","context":"Ex: \"Сегодня погода лучше. — \"Hoje o tempo está melhor.\"\"","audio":"Comparativos Irregulares Frequentes","level":"B1","module":"Módulo 11: Сравнительная степень (Comparativos e Superlativos Avançados)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Superlativo com Самый","secondary":"Самый (M) / Самая (F) / Самое (N) / Самые (Pl) + [Adjetivo]","desc":"Para formar o superlativo (\"o mais...\"), coloca-se a palavra Самый (concordando em gênero/número) antes do adjetivo.","context":"Ex: \"Самый красивый город / Самая высокая гора — \"A cidade mais bonita / A montanha mais alta\"\"","audio":"Superlativo com Самый","level":"B1","module":"Módulo 11: Сравнительная степень (Comparativos e Superlativos Avançados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Быстрее","secondary":"[ Bystreye ] — Mais rápido","desc":"","audio":"Быстрее","level":"B1","module":"Módulo 11: Сравнительная степень (Comparativos e Superlativos Avançados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Громче","secondary":"[ Gromche ] — Mais alto (som/voz)","desc":"","audio":"Громче","level":"B1","module":"Módulo 11: Сравнительная степень (Comparativos e Superlativos Avançados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Самый","secondary":"[ Samy ] — O mais... (superlativo masculino)","desc":"","audio":"Самый","level":"B1","module":"Módulo 11: Сравнительная степень (Comparativos e Superlativos Avançados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Самая","secondary":"[ Samaya ] — A mais... (superlativo feminino)","desc":"","audio":"Самая","level":"B1","module":"Módulo 11: Сравнительная степень (Comparativos e Superlativos Avançados)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Выше","secondary":"[ Vyshe ] — Mais alto (estatura/altitude)","desc":"","audio":"Выше","level":"B1","module":"Módulo 11: Сравнительная степень (Comparativos e Superlativos Avançados)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura Hipotética com Если бы","secondary":"Если бы + [Verbo no Passado] ..., [Verbo no Passado] + бы","desc":"Para dizer \"Se eu tivesse... eu iria...\", usa-se a partícula Бы após a conjunção Если, e os verbos de ambas as orações ficam no TEMPO PASSADO.","context":"Ex: \"Если бы я знал, я бы пришёл. — \"Se eu soubesse, eu teria vindo.\"\"","audio":"Estrutura Hipotética com Если бы","level":"B1","module":"Módulo 12: Условное наклонение (Modo Condicional e Hipóteses)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Desejos Corteses с Я хотел бы","secondary":"Я хотел бы (M) / Я хотела бы (F) + [Infinitivo]","desc":"Para expressar um desejo de forma muito educada (\"Eu gostaria de...\"), usa-se o verbo no passado + бы.","context":"Ex: \"Я хотел бы заказать кофе. — \"Eu gostaria de pedir um café.\"\"","audio":"Expressando Desejos Corteses с Я хотел бы","level":"B1","module":"Módulo 12: Условное наклонение (Modo Condicional e Hipóteses)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Invariabilidade da Partícula Бы","secondary":"Бы (sempre invariável)","desc":"A partícula Бы não flexiona jamais. Ela pode vir logo após o verbo no passado ou após os pronomes.","context":"Ex: \"Что бы ты сделал? — \"O que você faria?\"\"","audio":"Invariabilidade da Partícula Бы","level":"B1","module":"Módulo 12: Условное наклонение (Modo Condicional e Hipóteses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Бы","secondary":"[ By ] — Partícula do modo condicional","desc":"","audio":"Бы","level":"B1","module":"Módulo 12: Условное наклонение (Modo Condicional e Hipóteses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Если бы","secondary":"[ Yesli by ] — Se (em hipóteses / \"Se fosse o caso\")","desc":"","audio":"Если бы","level":"B1","module":"Módulo 12: Условное наклонение (Modo Condicional e Hipóteses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Я хотел бы","secondary":"[ Ya khotel by ] — Eu gostaria (masculino)","desc":"","audio":"Я хотел бы","level":"B1","module":"Módulo 12: Условное наклонение (Modo Condicional e Hipóteses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Я хотела бы","secondary":"[ Ya khotela by ] — Eu gostaria (feminino)","desc":"","audio":"Я хотела бы","level":"B1","module":"Módulo 12: Условное наклонение (Modo Condicional e Hipóteses)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Знать","secondary":"[ Znat ] — Saber / Conhecer","desc":"","audio":"Знать","level":"B1","module":"Módulo 12: Условное наклонение (Modo Condicional e Hipóteses)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Relatando Afirmações com Что","secondary":"[Pessoa] сказал(а), что + [Oração]","desc":"Para relatar o que alguém disse (afirmação), usa-se a conjunção Что (que).","context":"Ex: \"Анна сказала, что она занята. — \"Anna disse que está ocupada.\"\"","audio":"Relatando Afirmações com Что","level":"B1","module":"Módulo 13: Косвенная речь (Discurso Indireto e Relatos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Relatando Pedidos e Ordens com Чтобы","secondary":"[Pessoa] попросил(а), чтобы + [Oração]","desc":"Para relatar um pedido ou ordem de outra pessoa, usa-se Чтобы + verbo no Infinitivo ou Passado.","context":"Ex: \"Он попросил, чтобы я позвонил ему. — \"Ele pediu para eu ligar para ele.\"\"","audio":"Relatando Pedidos e Ordens com Чтобы","level":"B1","module":"Módulo 13: Косвенная речь (Discurso Indireto e Relatos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntas Indiretas com Conectores","secondary":"Он спросил, где / как / когда...","desc":"Para relatar perguntas usa-se o conector interrogativo original (Где, Как, Когда) ou a partícula Ли.","context":"Ex: \"Иван спросил, где находится банк. — \"Ivan perguntou onde fica o banco.\"\"","audio":"Perguntas Indiretas com Conectores","level":"B1","module":"Módulo 13: Косвенная речь (Discurso Indireto e Relatos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Чтобы","secondary":"[ Chtoby ] — Para que / Para (relata pedidos)","desc":"","audio":"Чтобы","level":"B1","module":"Módulo 13: Косвенная речь (Discurso Indireto e Relatos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сказал","secondary":"[ Skazal ] — Disse (masculino)","desc":"","audio":"Сказал","level":"B1","module":"Módulo 13: Косвенная речь (Discurso Indireto e Relatos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Спросил","secondary":"[ Sprosil ] — Perguntou (masculino)","desc":"","audio":"Спросил","level":"B1","module":"Módulo 13: Косвенная речь (Discurso Indireto e Relatos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Попросил","secondary":"[ Poprosil ] — Pediu (masculino)","desc":"","audio":"Попросил","level":"B1","module":"Módulo 13: Косвенная речь (Discurso Indireto e Relatos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Saudações Formais Corporativas","secondary":"Уважаемый господин / Уважаемая госпожа / Уважаемые коллеги","desc":"Em correspondências comerciais usam-se \"Уважаемый\" (Prezado) + Nome/Cargo para homens, e \"Уважаемая\" para mulheres.","context":"Ex: \"Уважаемый Александр Викторович! — \"Prezado Aleksandr Viktorovitch!\"\"","audio":"Saudações Formais Corporativas","level":"B1","module":"Módulo 14: Деловая переписка (E-mails Formais e Protocolo Corporativo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fórmulas de Solicitação Profissional","secondary":"Просим вас [Infinitivo] / Будем признательны за [Acusativo]","desc":"Para fazer pedidos formais usam-se estruturas como \"Просим вас + [Infinitivo]\" (Pedimos-lhe que...) ou \"Будем признательны за...\" (Ficaremos gratos por...).","context":"Ex: \"Просим вас выслать счёт. — \"Pedimos-lhe que nos envie a fatura.\"\"","audio":"Fórmulas de Solicitação Profissional","level":"B1","module":"Módulo 14: Деловая переписка (E-mails Formais e Protocolo Corporativo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Encerramento e Anexos","secondary":"С уважением, [Seu Nome] | В приложении: [Arquivo]","desc":"Standard de encerramento: \"С уважением\" (Atenciosamente) e indicação de arquivos anexos com \"В приложении\" (Em anexo).","context":"Ex: \"В приложении направляем договор. — \"Em anexo enviamos o contrato.\"\"","audio":"Encerramento e Anexos","level":"B1","module":"Módulo 14: Деловая переписка (E-mails Formais e Protocolo Corporativo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Просим вас","secondary":"[ Prosim vas ] — Pedimos-lhe / Solicitamos a você","desc":"","audio":"Просим вас","level":"B1","module":"Módulo 14: Деловая переписка (E-mails Formais e Protocolo Corporativo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"В приложении","secondary":"[ V prilozhenii ] — Em anexo","desc":"","audio":"В приложении","level":"B1","module":"Módulo 14: Деловая переписка (E-mails Formais e Protocolo Corporativo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Договор","secondary":"[ Dogovor ] — Contrato","desc":"","audio":"Договор","level":"B1","module":"Módulo 14: Деловая переписка (E-mails Formais e Protocolo Corporativo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Подтвердить","secondary":"[ Podtverdit ] — Confirmar","desc":"","audio":"Подтвердить","level":"B1","module":"Módulo 14: Деловая переписка (E-mails Formais e Protocolo Corporativo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Apresentando Experiência (Опыт работы)","secondary":"У меня есть опыт работы в + [Área]","desc":"Para falar da sua experiência anterior usa-se \"У меня есть опыт работы в + [Área no Preposicional/Locativo]\".","context":"Ex: \"У меня есть опыт работы в маркетинге. — \"Tenho experiência profissional em marketing.\"\"","audio":"Apresentando Experiência (Опыт работы)","level":"B1","module":"Módulo 15: Собеседование (Entrevistas de Emprego em Russo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fluência em Idiomas","secondary":"Свободно говорить по-русски / по-английски","desc":"Usa-se \"Свободно говорить по-...\" para indicar fluência em línguas estrangeiras.","context":"Ex: \"Я свободно говорю по-русски. — \"Falo russo fluentemente.\"\"","audio":"Fluência em Idiomas","level":"B1","module":"Módulo 15: Собеседование (Entrevistas de Emprego em Russo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Qualidades Pessoais no Currículo","secondary":"Я + [Adjetivo Masculino/Feminino]","desc":"Adjetivos valorizados: Ответственный (responsável), Коммуникабельный (comunicativo), Пунктуальный (pontual).","context":"Ex: \"Я очень ответственный сотрудник. — \"Sou um funcionário muito responsável.\"\"","audio":"Qualidades Pessoais no Currículo","level":"B1","module":"Módulo 15: Собеседование (Entrevistas de Emprego em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Резюме","secondary":"[ Rezyume ] — Currículo (CV)","desc":"","audio":"Резюме","level":"B1","module":"Módulo 15: Собеседование (Entrevistas de Emprego em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Опыт работы","secondary":"[ Opyt raboty ] — Experiência de trabalho","desc":"","audio":"Опыт работы","level":"B1","module":"Módulo 15: Собеседование (Entrevistas de Emprego em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Собеседование","secondary":"[ Sobesedovaniye ] — Entrevista de emprego","desc":"","audio":"Собеседование","level":"B1","module":"Módulo 15: Собеседование (Entrevistas de Emprego em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ответственный","secondary":"[ Otvetstvenny ] — Responsável","desc":"","audio":"Ответственный","level":"B1","module":"Módulo 15: Собеседование (Entrevistas de Emprego em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Должность","secondary":"[ Dolzhnost ] — Cargo / Função","desc":"","audio":"Должность","level":"B1","module":"Módulo 15: Собеседование (Entrevistas de Emprego em Russo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Preposição Из-за + Genitivo (Causa Negativa)","secondary":"Из-за + [Genitivo]","desc":"A preposição Из-за (por causa de) é usada para indicar motivos desfavoráveis, imprevistos ou problemas.","context":"Ex: \"Из-за дождя / Из-за пробки — \"Por causa da chuva / Por causa do engarrafamento\"\"","audio":"Preposição Из-за + Genitivo (Causa Negativa)","level":"B1","module":"Módulo 16: Сложные предлоги (Preposições Complexas dos Casos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Preposição Благодаря + Dativo (Causa Positiva)","secondary":"Благодаря + [Dativo]","desc":"A preposição Благодаря (graças a) é usada para indicar causas benéficas, ajuda ou fatores positivos.","context":"Ex: \"Благодаря врачу / Благодаря помощи — \"Graças ao médico / Graças à ajuda\"\"","audio":"Preposição Благодаря + Dativo (Causa Positiva)","level":"B1","module":"Módulo 16: Сложные предлоги (Preposições Complexas dos Casos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Preposição Temporal Во время + Genitivo","secondary":"Во время + [Genitivo]","desc":"Significa \"Durante\" a realização de um evento.","context":"Ex: \"Во время концерта / Во время обеда — \"Durante o show / Durante o almoço\"\"","audio":"Preposição Temporal Во время + Genitivo","level":"B1","module":"Módulo 16: Сложные предлоги (Preposições Complexas dos Casos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Из-за","secondary":"[ Iz-za ] — Por causa de (causa negativa + Genativo)","desc":"","audio":"Из-за","level":"B1","module":"Módulo 16: Сложные предлоги (Preposições Complexas dos Casos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Благодаря","secondary":"[ Blagodarya ] — Graças a (causa positiva + Dativo)","desc":"","audio":"Благодаря","level":"B1","module":"Módulo 16: Сложные предлоги (Preposições Complexas dos Casos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Во время","secondary":"[ Vo vremya ] — Durante (+ Genitivo)","desc":"","audio":"Во время","level":"B1","module":"Módulo 16: Сложные предлоги (Preposições Complexas dos Casos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пробки","secondary":"[ Probki ] — Engarrafamento / Trânsito (genitivo)","desc":"","audio":"Пробки","level":"B1","module":"Módulo 16: Сложные предлоги (Preposições Complexas dos Casos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Помощи","secondary":"[ Pomoschi ] — Ajuda (dativo/genitivo)","desc":"","audio":"Помощи","level":"B1","module":"Módulo 16: Сложные предлоги (Preposições Complexas dos Casos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Aleksandr Pushkin (Александр Пушкин)","secondary":"Поэзия (Poesia) / Стихотворение (Poema)","desc":"Considerado o fundador da literatura russa moderna e \"o sol da poesia russa\" (Солнце русской поэзии).","context":"Ex: \"Я помню чудное мгновенье... — \"Recordo o momento maravilhoso...\"\"","audio":"Aleksandr Pushkin (Александр Пушкин)","level":"B1","module":"Módulo 17: Русская литература I (Introdução aos Clássicos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Anton Tchekhov (Антон Чехов)","secondary":"Рассказ (Conto) / Пьеса (Peça de teatro)","desc":"Mestre mundial do conto curto (рассказ) e da dramaturgia (пьеса).","context":"Ex: \"Чехов писал замечательные рассказы. — \"Tchekhov escrevia contos fabulosos.\"\"","audio":"Anton Tchekhov (Антон Чехов)","level":"B1","module":"Módulo 17: Русская литература I (Introdução aos Clássicos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Vocabulário Literário e Poético","secondary":"Произведение / Повесть / Роман","desc":"Substantivos e adjetivos literários: Поэт (poeta), Писатель (escritor), Произведение (obra literária).","context":"Ex: \"Это великое произведение. — \"Esta é uma grande obra literária.\"\"","audio":"Vocabulário Literário e Poético","level":"B1","module":"Módulo 17: Русская литература I (Introdução aos Clássicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Поэт","secondary":"[ Poet ] — Poeta","desc":"","audio":"Поэт","level":"B1","module":"Módulo 17: Русская литература I (Introdução aos Clássicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Писатель","secondary":"[ Pisatel ] — Escritor","desc":"","audio":"Писатель","level":"B1","module":"Módulo 17: Русская литература I (Introdução aos Clássicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Рассказ","secondary":"[ Rasskaz ] — Conto curto","desc":"","audio":"Рассказ","level":"B1","module":"Módulo 17: Русская литература I (Introdução aos Clássicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Стихотворение","secondary":"[ Stikhotvoreniye ] — Poema","desc":"","audio":"Стихотворение","level":"B1","module":"Módulo 17: Русская литература I (Introdução aos Clássicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Произведение","secondary":"[ Proizvedeniye ] — Obra literária / artística","desc":"","audio":"Произведение","level":"B1","module":"Módulo 17: Русская литература I (Introdução aos Clássicos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Sigla СМИ (Meios de Comunicação)","secondary":"СМИ (Imprensa / Mídia)","desc":"СМИ significa Средства Массовой Информации (Meios de Comunicação de Massa / Imprensa).","context":"Ex: \"По данным СМИ... — \"De acordo com a mídia...\"\"","audio":"A Sigla СМИ (Meios de Comunicação)","level":"B1","module":"Módulo 18: СМИ и новости (Leitura de Notícias em Russo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Manchetes e Relatos Informativos","secondary":"Сообщается, что... / По сообщению...","desc":"Usa-se \"Сообщается, что...\" (Informa-se que...) ou \"По сообщению...\" (Segundo o relato de...).","context":"Ex: \"Сообщается, что переговоры прошли успешно. — \"Informa-se que as negociações foram bem-sucedidas.\"\"","audio":"Manchetes e Relatos Informativos","level":"B1","module":"Módulo 18: СМИ и новости (Leitura de Notícias em Russo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Vocabulário Econômico e Político","secondary":"Новости / Экономика / Событие","desc":"Termos frequentes: Экономика (economia), Президент (presidente), Новости (notícias), Событие (acontecimento).","context":"Ex: \"Главные события дня. — \"Os principais acontecimentos do dia.\"\"","audio":"Vocabulário Econômico e Político","level":"B1","module":"Módulo 18: СМИ и новости (Leitura de Notícias em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"СМИ","secondary":"[ SMI ] — Imprensa / Mídia de massa","desc":"","audio":"СМИ","level":"B1","module":"Módulo 18: СМИ и новости (Leitura de Notícias em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Новости","secondary":"[ Novosti ] — Notícias","desc":"","audio":"Новости","level":"B1","module":"Módulo 18: СМИ и новости (Leitura de Notícias em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Событие","secondary":"[ Sobytiye ] — Acontecimento / Evento","desc":"","audio":"Событие","level":"B1","module":"Módulo 18: СМИ и новости (Leitura de Notícias em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сообщается","secondary":"[ Soobschayetsya ] — Informa-se / É noticiado","desc":"","audio":"Сообщается","level":"B1","module":"Módulo 18: СМИ и новости (Leitura de Notícias em Russo)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Экономика","secondary":"[ Ekonomika ] — Economia","desc":"","audio":"Экономика","level":"B1","module":"Módulo 18: СМИ и новости (Leitura de Notícias em Russo)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Opinião: Я считаю, что...","secondary":"Я считаю, что + [Opinião]","desc":"Para expressar um posicionamento forte e considerado, usa-se \"Я считаю, что...\" (Eu considero/acho que...).","context":"Ex: \"Я считаю, что это важно. — \"Eu considero que isto é importante.\"\"","audio":"Expressando Opinião: Я считаю, что...","level":"B1","module":"Módulo 19: Экология и общество (Meio Ambiente e Sociedade)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Ponto de Vista: По-моему","secondary":"По-моему, / По моему мнению,","desc":"Usa-se \"По-моему\" (Na minha opinião) ou \"По моему мнению\" para introduzir um ponto de vista.","context":"Ex: \"По-моему, природа в опасности. — \"Na minha opinião, a natureza está em perigo.\"\"","audio":"Expressando Ponto de Vista: По-моему","level":"B1","module":"Módulo 19: Экология и общество (Meio Ambiente e Sociedade)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Vocabulário Ambiental e Social","secondary":"Природа / Защищать / Общество","desc":"Termos essenciais: Природа (natureza), Экология (ecologia), Защищать (proteger), Общество (sociedade).","context":"Ex: \"Мы должны защищать природу. — \"Nós devemos proteger a natureza.\"\"","audio":"Vocabulário Ambiental e Social","level":"B1","module":"Módulo 19: Экология и общество (Meio Ambiente e Sociedade)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Я считаю, что","secondary":"[ Ya schitayu, chto ] — Eu considero/acho que","desc":"","audio":"Я считаю, что","level":"B1","module":"Módulo 19: Экология и общество (Meio Ambiente e Sociedade)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"По-моему","secondary":"[ Po-moyemu ] — Na minha opinião","desc":"","audio":"По-моему","level":"B1","module":"Módulo 19: Экология и общество (Meio Ambiente e Sociedade)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Защищать","secondary":"[ Zaschischat ] — Proteger / Defender","desc":"","audio":"Защищать","level":"B1","module":"Módulo 19: Экология и общество (Meio Ambiente e Sociedade)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Общество","secondary":"[ Obschestvo ] — Sociedade","desc":"","audio":"Общество","level":"B1","module":"Módulo 19: Экология и общество (Meio Ambiente e Sociedade)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Causa com Потому что (Porque)","secondary":"[Fato] +, потому что + [Causa]","desc":"Usa-se \"Потому что\" para responder diretamente à pergunta Почему? (Por quê?).","context":"Ex: \"Я не пришёл, потому что был занят. — \"Não fui porque estava ocupado.\"\"","audio":"Causa com Потому что (Porque)","level":"B1","module":"Módulo 20: Выражение причины и следствия (Causa e Consequência)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Consequência com Поэтому (Por isso / Portanto)","secondary":"[Fato] +, поэтому + [Consequência]","desc":"Usa-se \"Поэтому\" para introduzir o resultado ou consequência de um fato anterior.","context":"Ex: \"Погода была плохая, поэтому мы остались дома. — \"O tempo estava ruim, por isso ficamos em casa.\"\"","audio":"Consequência com Поэтому (Por isso / Portanto)","level":"B1","module":"Módulo 20: Выражение причины и следствия (Causa e Consequência)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Causa Formal / Explicativa com Так как","secondary":"Так как + [Causa] ..., [Consequência]","desc":"Usa-se \"Так как\" (Visto que / Já que) frequentemente no início da frase para enunciar a causa motivadora.","context":"Ex: \"Так как идёт дождь, мы возьмём зонт. — \"Já que está chovendo, levaremos um guarda-chuva.\"\"","audio":"Causa Formal / Explicativa com Так как","level":"B1","module":"Módulo 20: Выражение причины и следствия (Causa e Consequência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Потому что","secondary":"[ Potomu chto ] — Porque (causa)","desc":"","audio":"Потому что","level":"B1","module":"Módulo 20: Выражение причины и следствия (Causa e Consequência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Поэтому","secondary":"[ Poetomu ] — Por isso / Portanto (consequência)","desc":"","audio":"Поэтому","level":"B1","module":"Módulo 20: Выражение причины и следствия (Causa e Consequência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Так как","secondary":"[ Tak kak ] — Visto que / Já que (causa inicial)","desc":"","audio":"Так как","level":"B1","module":"Módulo 20: Выражение причины и следствия (Causa e Consequência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Почему","secondary":"[ Pochemu ] — Por quê?","desc":"","audio":"Почему","level":"B1","module":"Módulo 20: Выражение причины и следствия (Causa e Consequência)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Заболел","secondary":"[ Zabolel ] — Adoeceu","desc":"","audio":"Заболел","level":"B1","module":"Módulo 20: Выражение причины и следствия (Causa e Consequência)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Propósito com Чтобы + Infinitivo","secondary":"[Ação] +, чтобы + [Infinitivo]","desc":"Quando o sujeito da oração principal e da subordinada é O MESMO, usa-se Чтобы seguido do verb no Infinitivo.","context":"Ex: \"Я приехал в Москву, чтобы учиться. — \"Vim a Moscou para estudar.\"\"","audio":"Propósito com Чтобы + Infinitivo","level":"B1","module":"Módulo 21: Выражение цели (Orações Finais e Propósito)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura Formal Для того чтобы","secondary":"Для того чтобы + [Infinitivo / Subjuntivo]","desc":"Em contextos formais ou e-mails corporativos, usa-se a expressão \"Для того чтобы\" (A fim de que / Com a finalidade de).","context":"Ex: \"Для того чтобы получить визу, нужно заполнить анкету. — \"A fim de obter o visto, é preciso preencher o formulário.\"\"","audio":"Estrutura Formal Для того чтобы","level":"B1","module":"Módulo 21: Выражение цели (Orações Finais e Propósito)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Preposição Для + Genitivo","secondary":"Для + [Genitivo]","desc":"Para indicar a quem ou a que se destina algo (\"para\"), usa-se a preposição Для + Caso Genitivo.","context":"Ex: \"Подарок для мамы / Учебник для студентов — \"Presente para a mãe / Livro para estudantes\"\"","audio":"Preposição Для + Genitivo","level":"B1","module":"Módulo 21: Выражение цели (Orações Finais e Propósito)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Для того чтобы","secondary":"[ Dlya togo chtoby ] — A fim de que / Com o objetivo de","desc":"","audio":"Для того чтобы","level":"B1","module":"Módulo 21: Выражение цели (Orações Finais e Propósito)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Для","secondary":"[ Dlya ] — Para (destinado a + Genitivo)","desc":"","audio":"Для","level":"B1","module":"Módulo 21: Выражение цели (Orações Finais e Propósito)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Цель","secondary":"[ Tsel ] — Objetivo / Meta","desc":"","audio":"Цель","level":"B1","module":"Módulo 21: Выражение цели (Orações Finais e Propósito)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Получить","secondary":"[ Poluchit ] — Obter / Receber","desc":"","audio":"Получить","level":"B1","module":"Módulo 21: Выражение цели (Orações Finais e Propósito)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Desejo de Boa Sorte: Ни пуха ни пера!","secondary":"Ни пуха ни пера! ➔ Ответ: К чёрту!","desc":"Expressão idiomática tradicional usada antes de exames ou desafios (\"Boa sorte!\"). A única resposta aceita por superstição é \"К чёрту!\" (Ao diabo!).","context":"Ex: \"Завтра экзамен? Ни пуха ни пера! — К чёрту! — \"Exame amanhã? Boa sorte! — Valeu / Ao diabo!\"\"","audio":"Desejo de Boa Sorte: Ни пуха ни пера!","level":"B1","module":"Módulo 22: Русский юмор и выражения (Humor Russo e Expressões)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressão: Делать из мухи слона","secondary":"Делать из мухи слона","desc":"Significa \"Fazer tempestade em copo d'água\" (Literalmente: fazer de uma mosca um elefante).","context":"Ex: \"Не переживай, не делай из мухи слона! — \"Não se preocupe, não faça tempestade em copo d'água!\"\"","audio":"Expressão: Делать из мухи слона","level":"B1","module":"Módulo 22: Русский юмор и выражения (Humor Russo e Expressões)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressão: Дойти до ручки","secondary":"Дойти до ручки","desc":"Significa \"Chegar ao limite / ao fundo do poço / estar esgotado extrema e desesperadamente\".","context":"Ex: \"Он так много работал, что дошёл до ручки. — \"Ele trabalhou tanto que chegou ao limite exausto.\"\"","audio":"Expressão: Дойти до ручки","level":"B1","module":"Módulo 22: Русский юмор и выражения (Humor Russo e Expressões)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ни пуха ни пера!","secondary":"[ Ni pukha ni pera! ] — Boa sorte! (em exames/testes)","desc":"","audio":"Ни пуха ни пера!","level":"B1","module":"Módulo 22: Русский юмор и выражения (Humor Russo e Expressões)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"К чёрту!","secondary":"[ K chortu! ] — Ao diabo! (resposta ritual a boa sorte)","desc":"","audio":"К чёрту!","level":"B1","module":"Módulo 22: Русский юмор и выражения (Humor Russo e Expressões)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Из мухи слона","secondary":"[ Iz mukhi slona ] — Tempestade em copo d'água (de mosca a elefante)","desc":"","audio":"Из мухи слона","level":"B1","module":"Módulo 22: Русский юмор и выражения (Humor Russo e Expressões)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дойти до ручки","secondary":"[ Doyti do ruchki ] — Chegar ao limite / exaustão total","desc":"","audio":"Дойти до ручки","level":"B1","module":"Módulo 22: Русский юмор и выражения (Humor Russo e Expressões)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Юмор","secondary":"[ Yumor ] — Humor","desc":"","audio":"Юмор","level":"B1","module":"Módulo 22: Русский юмор и выражения (Humor Russo e Expressões)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Os 6 Casos Gramaticais do Russo","secondary":"Именительный, Родительный, Дательный, Винительный, Творительный, Предложный","desc":"Revisão: 1. Nominativo (sujeito), 2. Genitivo (posse/ausência), 3. Dativo (destinatário/idade), 4. Acusativo (objeto), 5. Instrumental (companhia/profissão), 6. Preposicional (localização).","context":"Ex: \"Друг ➔ Друга ➔ Другу ➔ Друга ➔ Другом ➔ О друге — \"Todas as 6 formas do substantivo \"Друг\"\"\"","audio":"Os 6 Casos Gramaticais do Russo","level":"B1","module":"Módulo 23: Revisão Geral B1"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Prefixos de Movimento Em Matriz","secondary":"По- / При- / У- / В- / Вы- / Про- / Пере-","desc":"Revisão: По- (partida), При- (chegada), У- (ausência), В- (entrar), Вы- (sair), Про- (passar), Пере- (atravessar).","context":"Ex: \"Приехать ➔ Уехать ➔ Войти ➔ Выйти ➔ Перейти — \"Chegar ➔ Sair longe ➔ Entrar ➔ Sair ➔ Atravessar\"\"","audio":"Prefixos de Movimento Em Matriz","level":"B1","module":"Módulo 23: Revisão Geral B1"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Sintaxe de Orações Subordinadas B1","secondary":"Что / Чтобы / Из-за / Благодаря / Потому что / Поэтому","desc":"Revisão dos conectores: Что (discurso), Чтобы (propósito/pedido), Из-за (causa-), Благодаря (causa+), Потому что / Поэтому (lógica).","context":"Ex: \"Я учился, чтобы сдать экзамен. — \"Estudei para passar no exame.\"\"","audio":"Sintaxe de Orações Subordinadas B1","level":"B1","module":"Módulo 23: Revisão Geral B1"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Падеж","secondary":"[ Padezh ] — Caso gramatical","desc":"","audio":"Падеж","level":"B1","module":"Módulo 23: Revisão Geral B1"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дательный","secondary":"[ Datelny ] — Caso Dativo","desc":"","audio":"Дательный","level":"B1","module":"Módulo 23: Revisão Geral B1"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Творительный","secondary":"[ Tvoritelny ] — Caso Instrumental","desc":"","audio":"Творительный","level":"B1","module":"Módulo 23: Revisão Geral B1"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Движение","secondary":"[ Dvizheniye ] — Movimento","desc":"","audio":"Движение","level":"B1","module":"Módulo 23: Revisão Geral B1"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Автономия","secondary":"[ Avtonomiya ] — Autonomia","desc":"","audio":"Автономия","level":"B1","module":"Módulo 23: Revisão Geral B1"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Certificação Interna Nível B1","secondary":"Autonomia Gramatical (Nível B1 Concluído)","desc":"Ao concluir este teste com sucesso, você terá conquistado a Autonomia Gramatical Intermediária Superior (Nível B1).","context":"Ex: \"Поздравляем с уровнем B1! — \"Parabéns pelo Nível B1!\"\"","audio":"Certificação Interna Nível B1","level":"B1","module":"Módulo 24: Desafio Final B1 (Debate Simulado e Apresentação de Projeto)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Domínio dos 6 Casos e Verbos de Movimento","secondary":"Visão Geral do Nível B1 (Rumo ao Nível B2)","desc":"Certificação em todos os 6 Casos Gramaticais, Verbos com Prefixo, Discurso Indireto e Sintaxe Complexa.","context":"Ex: \"Вы отлично говорите по-русски! — \"Você fala russo muito bem!\"\"","audio":"Domínio dos 6 Casos e Verbos de Movimento","level":"B1","module":"Módulo 24: Desafio Final B1 (Debate Simulado e Apresentação de Projeto)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Debate e Apresentação de Projetos","secondary":"Debate & Fluência Autônoma","desc":"Capacidade de expor ideias com Я считаю, que... e defender pontos de vista corporativos e sociais.","context":"Ex: \"Я считаю, что этот проект успешный. — \"Considero que este projeto é bem-sucedido.\"\"","audio":"Debate e Apresentação de Projetos","level":"B1","module":"Módulo 24: Desafio Final B1 (Debate Simulado e Apresentação de Projeto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Экзамен","secondary":"[ Ekzamen ] — Exame / Teste de certificação","desc":"","audio":"Экзамен","level":"B1","module":"Módulo 24: Desafio Final B1 (Debate Simulado e Apresentação de Projeto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дискуссия","secondary":"[ Diskussiya ] — Debate / Discussão","desc":"","audio":"Дискуссия","level":"B1","module":"Módulo 24: Desafio Final B1 (Debate Simulado e Apresentação de Projeto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Проект","secondary":"[ Proyekt ] — Projeto","desc":"","audio":"Проект","level":"B1","module":"Módulo 24: Desafio Final B1 (Debate Simulado e Apresentação de Projeto)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Успех","secondary":"[ Uspekh ] — Sucesso","desc":"","audio":"Успех","level":"B1","module":"Módulo 24: Desafio Final B1 (Debate Simulado e Apresentação de Projeto)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Particípio Ativo Presente (-ущ-/-ющ- & -ащ-/-ящ-)","secondary":"[Verbo Presente 3ª Pl] - т + щий / щая / щее / щие","desc":"Derivado do tema do presente. Verbos de 1ª conjugação usam -ущ-/-ющ- (читающий, работающий), e de 2ª conjugação usam -ащ-/-ящ- (говорящий, смотрящий).","context":"Ex: \"Студент, читающий книгу ➔ O estudante que lê o livro — \"O estudante lendo o livro\"\"","audio":"Particípio Ativo Presente (-ущ-/-ющ- & -ащ-/-ящ-)","level":"B2","module":"Módulo 1: Причастие I (Particípios Ativos no Presente e Passado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Particípio Ativo Passado (-вш-/-ш-)","secondary":"[Verbo Passado Masc] + вший / вшая / вшее / вшие","desc":"Derivado do tema do passado. Verbos terminados em vogal ganham -вш- (читавший, живший), e em consoante ganham -ш- (нёсший, пришедший).","context":"Ex: \"Человек, живший в Москве ➔ A pessoa que viveu em Moscou — \"A pessoa que morava em Moscou\"\"","audio":"Particípio Ativo Passado (-вш-/-ш-)","level":"B2","module":"Módulo 1: Причастие I (Particípios Ativos no Presente e Passado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Concordância e Declinação dos Particípios","secondary":"Concordância em Gênero + Número + Caso","desc":"Os particípios funcionam como adjetivos e declinam nos 6 casos gramaticais concordando com o substantivo que modificam.","context":"Ex: \"Я знаю студента, читающего книгу. (Caso Acusativo Animado) — \"Conheço o estudante que está lendo o livro.\"\"","audio":"Concordância e Declinação dos Particípios","level":"B2","module":"Módulo 1: Причастие I (Particípios Ativos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Читающий","secondary":"[ Chitayushchiy ] — Que lê / Lendo (Particípio Ativo Presente)","desc":"","audio":"Читающий","level":"B2","module":"Módulo 1: Причастие I (Particípios Ativos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Говорящий","secondary":"[ Govoryashchiy ] — Que fala / Falando","desc":"","audio":"Говорящий","level":"B2","module":"Módulo 1: Причастие I (Particípios Ativos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Живший","secondary":"[ Zhivshiy ] — Que viveu / Morava","desc":"","audio":"Живший","level":"B2","module":"Módulo 1: Причастие I (Particípios Ativos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пришедший","secondary":"[ Prishedshiy ] — Que chegou / Veio","desc":"","audio":"Пришедший","level":"B2","module":"Módulo 1: Причастие I (Particípios Ativos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Работающий","secondary":"[ Rabotayushchiy ] — Que trabalha / Trabalhando","desc":"","audio":"Работающий","level":"B2","module":"Módulo 1: Причастие I (Particípios Ativos no Presente e Passado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Particípio Passivo Presente (-ем-/-им-)","secondary":"[1ª pessoa Plural Presente] + ый / ая / ое / ые","desc":"Derivado da 1ª pessoa do plural do presente + adjetivo: читаем ➔ читаемый, любим ➔ любимый. Indica ação contínua sofrida pelo objeto.","context":"Ex: \"Любимый город ➔ Cidade amada — \"Cidade favorita/amada\"\"","audio":"Particípio Passivo Presente (-ем-/-им-)","level":"B2","module":"Módulo 2: Причастие II (Particípios Passivos no Presente e Passado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Particípio Passivo Passado (-нн- e -т-)","secondary":"[Infinitivo SV] ➔ -нный / -енный / -тый","desc":"Formado do tema do infinitivo/passado de verbos perfeitos. Verbos em -ать/-ять ganham -нный (прочитанный), em -ить ganham -енный (решённый), e radicais monosilábicos ganham -тый (открытый, запертый).","context":"Ex: \"Прочитанная книга / Открытая дверь — \"Livro lido / Porta aberta\"\"","audio":"Particípio Passivo Passado (-нн- e -т-)","level":"B2","module":"Módulo 2: Причастие II (Particípios Passivos no Presente e Passado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Agente da Ação no Caso Instrumental","secondary":"[Objeto] + [Particípio Passivo] + [Agente no Instrumental]","desc":"O agente que realiza a ação passiva fica obrigatoriamente no Caso Instrumental.","context":"Ex: \"Статья, написанная журналистом. (написанная + журналистом) — \"Artigo escrito pelo jornalista.\"\"","audio":"Agente da Ação no Caso Instrumental","level":"B2","module":"Módulo 2: Причастие II (Particípios Passivos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Прочитанный","secondary":"[ Prochitannyy ] — Lido (Particípio Passivo Passado)","desc":"","audio":"Прочитанный","level":"B2","module":"Módulo 2: Причастие II (Particípios Passivos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Любимый","secondary":"[ Lyubimyy ] — Amado / Favorito","desc":"","audio":"Любимый","level":"B2","module":"Módulo 2: Причастие II (Particípios Passivos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Открытый","secondary":"[ Otkrytyy ] — Aberto","desc":"","audio":"Открытый","level":"B2","module":"Módulo 2: Причастие II (Particípios Passivos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Решённый","secondary":"[ Reshyonnyy ] — Resolvido / Decidido","desc":"","audio":"Решённый","level":"B2","module":"Módulo 2: Причастие II (Particípios Passivos no Presente e Passado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Написанный","secondary":"[ Napisannyy ] — Escrito","desc":"","audio":"Написанный","level":"B2","module":"Módulo 2: Причастие II (Particípios Passivos no Presente e Passado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Formação dos Particípios Curtos Passivos","secondary":"Написанный ➔ Написан (M), Написана (F), Написано (N), Написаны (Pl)","desc":"As formas curtas são derivadas dos particípios passivos longos retirando a terminação adjetival. Masculino: -ен/-н/-т, Feminino: -ена/-на/-та, Neutro: -ено/-но/-то, Plural: -ены/-ны/-ты.","context":"Ex: \"Дом построен. / Дверь открыта. — \"A casa está construída. / A porta está aberta.\"\"","audio":"Formação dos Particípios Curtos Passivos","level":"B2","module":"Módulo 3: Краткие причастия (Particípios Curtos na Voz Passiva)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Concordância Predicativa no Sujeito","secondary":"[Sujeito] + [Particípio Curto]","desc":"O particípio curto funciona como predicado nominal da oração e concorda estritamente com o sujeito em gênero e número.","context":"Ex: \"Работа (F) завершена. / Письма (Pl) отправлены. — \"O trabalho foi concluído. / As cartas foram enviadas.\"\"","audio":"Concordância Predicativa no Sujeito","level":"B2","module":"Módulo 3: Краткие причастия (Particípios Curtos na Voz Passiva)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Tempo com o Verbo Быть","secondary":"Presente: [Particípio Curto] | Passado: Был + [Particípio] | Futuro: Будет + [Particípio]","desc":"No presente, Быть é omitido. No passado usa-se Был/Была/Было/Были e no futuro Будет/Будут.","context":"Ex: \"Проект был завершён вчера. — \"O projeto foi concluído ontem.\"\"","audio":"Expressando Tempo com o Verbo Быть","level":"B2","module":"Módulo 3: Краткие причастия (Particípios Curtos na Voz Passiva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Построен","secondary":"[ Postroyen ] — Construído (Forma curta M)","desc":"","audio":"Построен","level":"B2","module":"Módulo 3: Краткие причастия (Particípios Curtos na Voz Passiva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Завершена","secondary":"[ Zavershena ] — Concluída (Forma curta F)","desc":"","audio":"Завершена","level":"B2","module":"Módulo 3: Краткие причастия (Particípios Curtos na Voz Passiva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Открыто","secondary":"[ Otkryto ] — Aberto (Forma curta N)","desc":"","audio":"Открыто","level":"B2","module":"Módulo 3: Краткие причастия (Particípios Curtos na Voz Passiva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Отправлены","secondary":"[ Otpravleny ] — Enviados (Forma curta Pl)","desc":"","audio":"Отправлены","level":"B2","module":"Módulo 3: Краткие причастия (Particípios Curtos na Voz Passiva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Принят","secondary":"[ Prinyat ] — Aceito / Adotado","desc":"","audio":"Принят","level":"B2","module":"Módulo 3: Краткие причастия (Particípios Curtos na Voz Passiva)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Formação do Gerúndio Imperfeito (-а/-я)","secondary":"[3ª Plural Presente] - ut/at + я / а","desc":"Formado do tema do presente retirando a terminação da 3ª pessoa do plural e adicionando -я (ou -а após consoantes chiantes ж, ч, ш, щ).","context":"Ex: \"Читают ➔ Читая / Сидят ➔ Сидя / Слышат ➔ Слыша — \"Lendo / Sentando / Ouvindo\"\"","audio":"Formação do Gerúndio Imperfeito (-а/-я)","level":"B2","module":"Módulo 4: Деепричастие I (Gerúndios no Imperfeito - Ações Simultâneas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Identidade de Sujeito Obrigatória","secondary":"[Sujeito] + [Gerúndio] + [Verbo Principal]","desc":"O gerúndio e o verbo principal DEVEM ser realizados rigorosamente pela MESMA pessoa/sujeito.","context":"Ex: \"Слушая музыку, я отдыхаю. — \"Escutando música, eu me relaxo.\"\"","audio":"Identidade de Sujeito Obrigatória","level":"B2","module":"Módulo 4: Деепричастие I (Gerúndios no Imperfeito - Ações Simultâneas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Isolamento por Vírgulas (Деепричастный оборот)","secondary":"..., [Gerúndio + Complementos], ...","desc":"Toda oração reduzida de gerúndio é isolada por vírgula na escrita em russo, esteja no início, meio ou fim da frase.","context":"Ex: \"Он шёл по улице, напевая песню. — \"Ele andava pela rua, cantarolando uma canção.\"\"","audio":"Isolamento por Vírgulas (Деепричастный оборот)","level":"B2","module":"Módulo 4: Деепричастие I (Gerúndios no Imperfeito - Ações Simultâneas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Читая","secondary":"[ Chitaya ] — Lendo (Gerúndio Imperfeito)","desc":"","audio":"Читая","level":"B2","module":"Módulo 4: Деепричастие I (Gerúndios no Imperfeito - Ações Simultâneas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Говоря","secondary":"[ Govorya ] — Falando","desc":"","audio":"Говоря","level":"B2","module":"Módulo 4: Деепричастие I (Gerúndios no Imperfeito - Ações Simultâneas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сидя","secondary":"[ Sidya ] — Sentando / Sentado","desc":"","audio":"Сидя","level":"B2","module":"Módulo 4: Деепричастие I (Gerúndios no Imperfeito - Ações Simultâneas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Слушая","secondary":"[ Slushaya ] — Escutando","desc":"","audio":"Слушая","level":"B2","module":"Módulo 4: Деепричастие I (Gerúndios no Imperfeito - Ações Simultâneas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Улыбаясь","secondary":"[ Ulybayas ] — Sorrindo (Reflexivo)","desc":"","audio":"Улыбаясь","level":"B2","module":"Módulo 4: Деепричастие I (Gerúndios no Imperfeito - Ações Simultâneas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Formação do Gerúndio Perfeito (-в/-вши)","secondary":"[Tema do Passado Perfectivo] + в / вши / вшись","desc":"Formado do tema do passado de verbos de aspecto perfeito retirando a terminação -л e adicionando -в (ou -вши em contexto poético/coloquial e verbos reflexivos em -вшись).","context":"Ex: \"Прочитал ➔ Прочитав / Вернулся ➔ Вернувшись — \"Tendo lido / Tendo voltado\"\"","audio":"Formação do Gerúndio Perfeito (-в/-вши)","level":"B2","module":"Módulo 5: Деепричастие II (Gerúndios no Perfeito - Ações Anteriores)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbos em Consoante (-ши)","secondary":"[Passado em Consoante] + ши","desc":"Verbos perfeitos cujo passado termina em consoante usam o sufixo -ши (принёс ➔ принёсши, пришёл ➔ придя/пришедши).","context":"Ex: \"Принёс ➔ Принёсши / Зашёл ➔ Зашедши — \"Tendo trazido / Tendo entrado\"\"","audio":"Verbos em Consoante (-ши)","level":"B2","module":"Módulo 5: Деепричастие II (Gerúndios no Perfeito - Ações Anteriores)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Relação de Causa e Antecedência Temporal","secondary":"[Gerúndio Perfeito (Ação 1 Aconteceu Primeiro)] ➔ [Verbo Principal (Ação 2)]","desc":"O gerúndio perfeito expressa uma ação totalmente CONCLUÍDA ANTES do evento principal, atuando muitas vezes como causa da ação principal.","context":"Ex: \"Узнав новости, она позвонила маме. — \"Ao saber das notícias (tendo sabido), ela ligou para a mãe.\"\"","audio":"Relação de Causa e Antecedência Temporal","level":"B2","module":"Módulo 5: Деепричастие II (Gerúndios no Perfeito - Ações Anteriores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Прочитав","secondary":"[ Prochitav ] — Tendo lido / Após ler","desc":"","audio":"Прочитав","level":"B2","module":"Módulo 5: Деепричастие II (Gerúndios no Perfeito - Ações Anteriores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Узнав","secondary":"[ Uznav ] — Tendo sabido / Ao descobrir","desc":"","audio":"Узнав","level":"B2","module":"Módulo 5: Деепричастие II (Gerúndios no Perfeito - Ações Anteriores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вернувшись","secondary":"[ Vernuvshis ] — Tendo voltado / Ao retornar","desc":"","audio":"Вернувшись","level":"B2","module":"Módulo 5: Деепричастие II (Gerúndios no Perfeito - Ações Anteriores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Закончив","secondary":"[ Zakonchiv ] — Tendo terminado / Concluindo","desc":"","audio":"Закончив","level":"B2","module":"Módulo 5: Деепричастие II (Gerúndios no Perfeito - Ações Anteriores)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Посмотрев","secondary":"[ Posmotrev ] — Tendo assistido / Tendo olhado","desc":"","audio":"Посмотрев","level":"B2","module":"Módulo 5: Деепричастие II (Gerúndios no Perfeito - Ações Anteriores)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fórmulas Diplomáticas de Proposta Commercial","secondary":"Мы предлагаем + [Infinitivo] / Взаимовыгодное + [Substantivo]","desc":"Em negociações corporativas em russo, usam-se estruturas formais como \"Мы предлагаем рассмотреть...\" (Propomos considerar...) e \"Взаимовыгодное сотрудничество\" para criar ambiente propício ao acordo.","context":"Ex: \"Мы предлагаем рассмотреть новые условия договора. — \"Propomos considerar as novas condições do contrato.\"\"","audio":"Fórmulas Diplomáticas de Proposta Commercial","level":"B2","module":"Módulo 6: Переговоры и бизнес (Negociação Executiva e Resolução de Conflitos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Objeções com Polidez Corporativa","secondary":"К сожалению, + [Oraçao no Dativo/Instrumental]","desc":"Para discordar sem gerar tensão, usa-se a atenuação \"К сожалению, мы не можем согласиться с...\" ou a antítese \"С одной стороны..., но с другой...\".","context":"Ex: \"К сожалению, эти условия нам не подходят. — \"Infelizmente estas condições não nos atendem.\"\"","audio":"Expressando Objeções com Polidez Corporativa","level":"B2","module":"Módulo 6: Переговоры и бизнес (Negociação Executiva e Resolução de Conflitos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fechamento e Registro de Acordos","secondary":"Прийти к + [Dativo: компромиссу / соглашению]","desc":"Usa-se \"Прийти к компромиссу\" (Chegar a um compromisso/acordo) e \"Подписать протокол намерений\" (Assinar memorando de intenções).","context":"Ex: \"Стороны пришли к взаимовыгодному соглашению. — \"As partes chegaram a um acordo mutuamente vantajoso.\"\"","audio":"Fechamento e Registro de Acordos","level":"B2","module":"Módulo 6: Переговоры и бизнес (Negociação Executiva e Resolução de Conflitos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Взаимовыгодный","secondary":"[ Vzaimovygodnyy ] — Mutuamente vantajoso / De benefício mútuo","desc":"","audio":"Взаимовыгодный","level":"B2","module":"Módulo 6: Переговоры и бизнес (Negociação Executiva e Resolução de Conflitos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Переговоры","secondary":"[ Peregovory ] — Negociações / Reunião de negócios","desc":"","audio":"Переговоры","level":"B2","module":"Módulo 6: Переговоры и бизнес (Negociação Executiva e Resolução de Conflitos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Компромисс","secondary":"[ Kompromiss ] — Compromisso / Acordo amigável","desc":"","audio":"Компромисс","level":"B2","module":"Módulo 6: Переговоры и бизнес (Negociação Executiva e Resolução de Conflitos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Соглашение","secondary":"[ Soglasheniye ] — Acordo / Pacto assinado","desc":"","audio":"Соглашение","level":"B2","module":"Módulo 6: Переговоры и бизнес (Negociação Executiva e Resolução de Conflitos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Entrada em Vigor de Documentos Legais","secondary":"Договор вступает в силу с момента + [Genitivo]","desc":"Em contratos russos, a cláusula de vigência usa o verbo \"вступать в силу\" (entrar em vigor) acompanhado da preposição \"с момента\" (+ Genitivo).","context":"Ex: \"Договор вступает в силу с момента подписания. — \"O contrato entra em vigor a partir do momento da assinatura.\"\"","audio":"Entrada em Vigor de Documentos Legais","level":"B2","module":"Módulo 7: Юридический язык (Linguagem Jurídica e Burocrática Básica)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressão de Obrigações Jurídicas (Обязываться)","secondary":"Стороны обязуются + [Infinitivo]","desc":"Nas cláusulas contratuais, as partes são referidas como \"Стороны\", e o verbo reflexivo \"обязываться\" (+ infinitivo) indica compromisso legal.","context":"Ex: \"Арендатор обязуется своевременно оплачивать аренду. — \"O inquilino se obriga a pagar o aluguel pontualmente.\"\"","audio":"Expressão de Obrigações Jurídicas (Обязываться)","level":"B2","module":"Módulo 7: Юридический язык (Linguagem Jurídica e Burocrática Básica)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Responsabilidade por Incumprimento (Ответственность)","secondary":"Нести ответственность за + [Acusativo]","desc":"A responsabilidade por violação de cláusulas é expressa por \"нести ответственность за\" (+ Acusativo).","context":"Ex: \"Сторона несёт ответственность за нарушение условий. — \"A parte responde pela violação das condições.\"\"","audio":"Responsabilidade por Incumprimento (Ответственность)","level":"B2","module":"Módulo 7: Юридический язык (Linguagem Jurídica e Burocrática Básica)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Обязанность","secondary":"[ Obyazannost ] — Obrigação / Dever legal","desc":"","audio":"Обязанность","level":"B2","module":"Módulo 7: Юридический язык (Linguagem Jurídica e Burocrática Básica)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ответственность","secondary":"[ Otvetstvennost ] — Responsabilidade civil / penal","desc":"","audio":"Ответственность","level":"B2","module":"Módulo 7: Юридический язык (Linguagem Jurídica e Burocrática Básica)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Действителен","secondary":"[ Deystvitelen ] — Válido (Forma curta masc)","desc":"","audio":"Действителен","level":"B2","module":"Módulo 7: Юридический язык (Linguagem Jurídica e Burocrática Básica)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Арендатор","secondary":"[ Arendator ] — Inquilino / Locatário","desc":"","audio":"Арендатор","level":"B2","module":"Módulo 7: Юридический язык (Linguagem Jurídica e Burocrática Básica)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Indicadores Macroeconômicos Globais","secondary":"ВВП / Инфляция / Процентная ставка","desc":"Termos fundamentais da economia: ВВП (Внутренний валовой продукт - PIB), Инфляция (Inflação), e Процентная ставка (Taxa de juros bancária).","context":"Ex: \"Рост ВВП составил три процента. — \"O crescimento do PIB somou três por cento.\"\"","audio":"Indicadores Macroeconômicos Globais","level":"B2","module":"Módulo 8: Экономика и финансы (Economia e Mercado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Variação Percentual (На + porcentagem)","secondary":"Вырасти / Снизиться + на + [Porcentagem]","desc":"Para indicar aumento ou redução percentual, usa-se a preposição НА seguida do numeral cardinal no Acusativo.","context":"Ex: \"Инфляция снизилась на два процента. — \"A inflação reduziu em dois por cento.\"\"","audio":"Expressando Variação Percentual (На + porcentagem)","level":"B2","module":"Módulo 8: Экономика и финансы (Economia e Mercado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbos de Aplicação Financeira (Инвестировать)","secondary":"Инвестировать в + [Acusativo]","desc":"O verbo \"инвестировать\" (investir) exige a preposição В acompanhada do Caso Acusativo.","context":"Ex: \"Компания инвестирует средства в искусственный интеллект. — \"A empresa investe recursos em inteligência artificial.\"\"","audio":"Verbos de Aplicação Financeira (Инвестировать)","level":"B2","module":"Módulo 8: Экономика и финансы (Economia e Mercado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Инфляция","secondary":"[ Inflyatsiya ] — Inflação / Alta de preços","desc":"","audio":"Инфляция","level":"B2","module":"Módulo 8: Экономика и финансы (Economia e Mercado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Инвестиции","secondary":"[ Investitsii ] — Investimentos de capital","desc":"","audio":"Инвестиции","level":"B2","module":"Módulo 8: Экономика и финансы (Economia e Mercado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Прибыль","secondary":"[ Pribyl ] — Lucro / Rendimento financeiro","desc":"","audio":"Прибыль","level":"B2","module":"Módulo 8: Экономика и финансы (Economia e Mercado)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ставка","secondary":"[ Stavka ] — Taxa (de juros / de câmbio)","desc":"","audio":"Ставка","level":"B2","module":"Módulo 8: Экономика и финансы (Economia e Mercado)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Citação de Fontes de Informação Jornalística","secondary":"По данным + [Genitivo] / Как сообщает + [Nome da Agência]","desc":"Matérias de imprensa usam fórmulas fixas para atrelar a notícia à fonte: \"По данным...\" (Segundo dados de...), \"Как сообщает ТАСС...\" (Como informa a TASS...), ou \"Со ссылкой на источник...\" (Citando fonte...).","context":"Ex: \"По данным министерства, проект завершён. — \"Segundo dados do ministério, o projeto foi concluído.\"\"","audio":"Citação de Fontes de Informação Jornalística","level":"B2","module":"Módulo 9: Анализ прессы (Análise de Periódicos Nativos - TASS, RIA Novosti)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbos Principais da Redação Jornalística","secondary":"Заявлять / Подчёркивать / Отмечать, что...","desc":"A imprensa nativa emprega verbos de alta formalidade: \"заявлять\" (declarar), \"подчёркивать\" (sublinhar/destacar), e \"отмечать\" (notar/observar).","context":"Ex: \"Пресс-секретарь подчеркнул важность соглашения. — \"O porta-voz destacou a importância do acordo.\"\"","audio":"Verbos Principais da Redação Jornalística","level":"B2","module":"Módulo 9: Анализ прессы (Análise de Periódicos Nativos - TASS, RIA Novosti)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Sintaxe Concisa das Manchetes (Заголовки)","secondary":"[Substantivo Chave] + [Particípio / Ação Direta]","desc":"Nas manchetes russas, o verbo ser/estar e conjunções são frequentemente omitidos, priorizando particípios e formas diretas para dar agilidade à notícia.","context":"Ex: \"Саммит в Москве: приняты ключевые решения. — \"Cúpula em Moscou: tomadas decisões chave.\"\"","audio":"Sintaxe Concisa das Manchetes (Заголовки)","level":"B2","module":"Módulo 9: Анализ прессы (Análise de Periódicos Nativos - TASS, RIA Novosti)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пресса","secondary":"[ Pressa ] — Imprensa / Periódicos de notícia","desc":"","audio":"Пресса","level":"B2","module":"Módulo 9: Анализ прессы (Análise de Periódicos Nativos - TASS, RIA Novosti)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Заголовок","secondary":"[ Zagolovok ] — Manchete / Título da notícia","desc":"","audio":"Заголовок","level":"B2","module":"Módulo 9: Анализ прессы (Análise de Periódicos Nativos - TASS, RIA Novosti)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Источник","secondary":"[ Istochnik ] — Fonte de informação","desc":"","audio":"Источник","level":"B2","module":"Módulo 9: Анализ прессы (Análise de Periódicos Nativos - TASS, RIA Novosti)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Introdução de Opinião Pessoal em Fala Rápida","secondary":"Честно говоря, / На мой взгляд, + [Oração]","desc":"Em conversas nativas e podcasts, usam-se marcadores de franqueza como \"Честно говоря...\" (Pra ser sincero...) e \"На мой взгляд...\" (Do meu ponto de vista...) para sinalizar posição individual.","context":"Ex: \"Честно говоря, я не ожидал такого результата. — \"Pra ser sincero, eu não esperava tal resultado.\"\"","audio":"Introdução de Opinião Pessoal em Fala Rápida","level":"B2","module":"Módulo 10: Подкасты и радио (Compreensão de Podcasts Nativos em Velocidade Real)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conectores Oratoriais de Resumo e Transição","secondary":"Короче говоря, / Собственно говоря,","desc":"Para fazer transições rápidas na fala nativa, usam-se \"Собственно говоря...\" (A bem da verdade...) e \"Короче говоря...\" (Em resumo / Enfim...).","context":"Ex: \"Короче говоря, мы решили остаться. — \"Em resumo, decidimos ficar.\"\"","audio":"Conectores Oratoriais de Resumo e Transição","level":"B2","module":"Módulo 10: Подкасты и радио (Compreensão de Podcasts Nativos em Velocidade Real)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pausas Preenchidas e Modulação de Tom","secondary":"Ну, знаете... / Так сказать...","desc":"Marcadores de fluência como \"Ну, знаете...\", \"Так сказать...\", e \"В общем-то...\" são usados para organizar o raciocínio sem perder o turno da fala.","context":"Ex: \"Это был, так сказать, интересный опыт. — \"Foi uma experiência, por assim dizer, interessante.\"\"","audio":"Pausas Preenchidas e Modulação de Tom","level":"B2","module":"Módulo 10: Подкасты и радио (Compreensão de Podcasts Nativos em Velocidade Real)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Подкаст","secondary":"[ Podkast ] — Podcast de áudio / vídeo","desc":"","audio":"Подкаст","level":"B2","module":"Módulo 10: Подкасты и радио (Compreensão de Podcasts Nativos em Velocidade Real)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ведущий","secondary":"[ Vedushchiy ] — Apresentador / Host do programa","desc":"","audio":"Ведущий","level":"B2","module":"Módulo 10: Подкасты и радио (Compreensão de Podcasts Nativos em Velocidade Real)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Честно","secondary":"[ Chestno ] — Sinceramente / Honestamente","desc":"","audio":"Честно","level":"B2","module":"Módulo 10: Подкасты и радио (Compreensão de Podcasts Nativos em Velocidade Real)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мнение","secondary":"[ Mneniye ] — Opinião / Ponto de vista","desc":"","audio":"Мнение","level":"B2","module":"Módulo 10: Подкасты и радио (Compreensão de Podcasts Nativos em Velocidade Real)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Gírias Nativas de Entusiasmo em Diálogos de Filme","secondary":"Это просто бомба! / Круто! / Клёво!","desc":"No cinema e séries russas modernas, usam-se termos informais de forte impacto emotivo: \"Это просто бомба!\" (É sensacional / bombástico!), \"Круто!\" (Demais!), e \"Клёво!\".","context":"Ex: \"Фильм — просто бомба! — \"O filme é sensacional!\"\"","audio":"Gírias Nativas de Entusiasmo em Diálogos de Filme","level":"B2","module":"Módulo 11: Кино и сериалы (Cinema e Séries Russas sem Legendas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Reduções e Elipses Fonéticas da Fala Coloquial","secondary":"Сейчас ➔ Щас / Что ➔ Чё / Только ➔ Тока","desc":"A fala veloz de personagens de filmes reduz formas padrão: \"Сейчас\" vira \"Щас\", \"Что\" vira \"Чё\", e \"Только\" vira \"Тока\".","context":"Ex: \"Щас приду, подожди! — \"Já tô indo, espera!\"\"","audio":"Reduções e Elipses Fonéticas da Fala Coloquial","level":"B2","module":"Módulo 11: Кино и сериалы (Cinema e Séries Russas sem Legendas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressões de Impacto e Imersão Auditiva","secondary":"Не могу оторваться! / Затягивает!","desc":"Para expressar o envolvimento com o enredo de uma série, usam-se \"Не могу оторваться!\" (Não consigo parar de assistir!) e \"Затягивает!\" (É viciante!).","context":"Ex: \"Сериал так затягивает, что смотришь всю ночь. — \"A série vicia tanto que você assiste a noite toda.\"\"","audio":"Expressões de Impacto e Imersão Auditiva","level":"B2","module":"Módulo 11: Кино и сериалы (Cinema e Séries Russas sem Legendas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Фильм","secondary":"[ Film ] — Filme cinematográfico","desc":"","audio":"Фильм","level":"B2","module":"Módulo 11: Кино и сериалы (Cinema e Séries Russas sem Legendas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сериал","secondary":"[ Serial ] — Série de TV / Streaming","desc":"","audio":"Сериал","level":"B2","module":"Módulo 11: Кино и сериалы (Cinema e Séries Russas sem Legendas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Круто","secondary":"[ Kruto ] — Legal / Daora / Excelente","desc":"","audio":"Круто","level":"B2","module":"Módulo 11: Кино и сериалы (Cinema e Séries Russas sem Legendas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Бомба","secondary":"[ Bomba ] — Algo bombástico / Sensacional","desc":"","audio":"Бомба","level":"B2","module":"Módulo 11: Кино и сериалы (Cinema e Séries Russas sem Legendas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сюжет","secondary":"[ Syuzhet ] — Enredo / Trama da história","desc":"","audio":"Сюжет","level":"B2","module":"Módulo 11: Кино и сериалы (Cinema e Séries Russas sem Legendas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Formulação do Objetivo Acadêmico","secondary":"Целью + [Genitivo] является + [Substantivo]","desc":"Em artigos científicos e teses russas, o objetivo principal é formulado com \"Целью данного исследования является...\" (O objetivo desta pesquisa é...) ou \"Предметом анализа выступает...\".","context":"Ex: \"Целью работы является анализ данных. — \"O objetivo do trabalho é a análise de dados.\"\"","audio":"Formulação do Objetivo Acadêmico","level":"B2","module":"Módulo 12: Научные тексты (Redação Acadêmica e Científica)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Impessoalidade e Voz Passiva Acadêmica","secondary":"Рассматривается / Исследуется + [Sujeito]","desc":"A redação científica russa evita o uso de \"я\" (eu) ou \"мы\" (nós), optando por construções reflexivas impessoais: \"Рассматривается...\" (Examina-se...), \"Исследуется...\" (Investiga-se...), \"Следует отметить...\" (Cabe ressaltar...).","context":"Ex: \"В статье рассматривается проблема экологии. — \"No artigo examina-se a questão da ecologia.\"\"","audio":"Impessoalidade e Voz Passiva Acadêmica","level":"B2","module":"Módulo 12: Научные тексты (Redação Acadêmica e Científica)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fundamentação das Conclusões Científicas","secondary":"На основе полученных данных, ...","desc":"Conclusões acadêmicas são introduzidas por \"На основе полученных данных...\" (Com base nos dados obtidos...) e \"Таким образом, доказано, что...\".","context":"Ex: \"На основе полученных данных сделаны выводы. — \"Com base nos dados obtidos foram feitas conclusões.\"\"","audio":"Fundamentação das Conclusões Científicas","level":"B2","module":"Módulo 12: Научные тексты (Redação Acadêmica e Científica)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Исследование","secondary":"[ Issledovaniye ] — Pesquisa / Estudo acadêmico","desc":"","audio":"Исследование","level":"B2","module":"Módulo 12: Научные тексты (Redação Acadêmica e Científica)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Анализ","secondary":"[ Analiz ] — Análise rigorosa de dados","desc":"","audio":"Анализ","level":"B2","module":"Módulo 12: Научные тексты (Redação Acadêmica e Científica)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Гипотеза","secondary":"[ Gipoteza ] — Hipótese de pesquisa","desc":"","audio":"Гипотеза","level":"B2","module":"Módulo 12: Научные тексты (Redação Acadêmica e Científica)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вывод","secondary":"[ Vyvod ] — Conclusão acadêmica","desc":"","audio":"Вывод","level":"B2","module":"Módulo 12: Научные тексты (Redação Acadêmica e Científica)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Dilemas Morais Dostoiévskianos","secondary":"Совесть / Искупление / Душевные терзания","desc":"A prosa de Fiódor Dostoiévski aborda conceitos éticos centrais: \"Совесть\" (Consciência moral), \"Искупление\" (Redenção/Expiação), e \"Душевные терзания\" (Tormentos da alma).","context":"Ex: \"Раскольников испытывал душевные терзания. — \"Raskólnikov sofria tormentos da alma.\"\"","audio":"Dilemas Morais Dostoiévskianos","level":"B2","module":"Módulo 13: Русская литература II (Dostoiévski e Tolstói)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Dialética da Alma de Tolstói","secondary":"Внутренняя эволюция / Поиск истины","desc":"Liev Tolstói destaca a evolução moral contínua dos personagens, retratando o conflito entre o dever social e a busca pela verdade interna.","context":"Ex: \"Герои Толстого находятся в поиске истины. — \"Os personagens de Tolstói estão em busca da verdade.\"\"","audio":"A Dialética da Alma de Tolstói","level":"B2","module":"Módulo 13: Русская литература II (Dostoiévski e Tolstói)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Recursos Estilísticos da Prosa Clássica","secondary":"Внутренний монолог / Психологизм","desc":"Uso de monólogos interiores profundos (\"внутренний монолог\") e antíteses dramáticas para retratar a psicologia humana.","context":"Ex: \"Роман насыщен внутренними монологами. — \"O romance é repleto de monólogos interiores.\"\"","audio":"Recursos Estilísticos da Prosa Clássica","level":"B2","module":"Módulo 13: Русская литература II (Dostoiévski e Tolstói)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Роман","secondary":"[ Roman ] — Romance (Gênero literário)","desc":"","audio":"Роман","level":"B2","module":"Módulo 13: Русская литература II (Dostoiévski e Tolstói)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Герой","secondary":"[ Geroy ] — Personagem principal / Herói","desc":"","audio":"Герой","level":"B2","module":"Módulo 13: Русская литература II (Dostoiévski e Tolstói)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Совесть","secondary":"[ Sovest ] — Consciência moral","desc":"","audio":"Совесть","level":"B2","module":"Módulo 13: Русская литература II (Dostoiévski e Tolstói)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Нравственность","secondary":"[ Nravstvennost ] — Moralidade / Ética viva","desc":"","audio":"Нравственность","level":"B2","module":"Módulo 13: Русская литература II (Dostoiévski e Tolstói)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Судьба","secondary":"[ Sudba ] — Destino / Fado dos personagens","desc":"","audio":"Судьба","level":"B2","module":"Módulo 13: Русская литература II (Dostoiévski e Tolstói)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Vocabulário de Análise Poética","secondary":"Стихотворение / Строфа / Рифма","desc":"Na apreciação poética russa, usam-se: \"Стихотворение\" (Poema), \"Строфа\" (Estrofe), \"Рифма\" (Rima), e \"Метафора\" (Metáfora).","context":"Ex: \"Стихотворение написано точным ямбом. — \"O poema foi escrito em jambo preciso.\"\"","audio":"Vocabulário de Análise Poética","level":"B2","module":"Módulo 14: Русская поэзия (Poesia Russa: Esenin, Akhmatova, Tsvetaeva)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Poesia da Era de Prata (Серебряный век)","secondary":"Серебряный век / Лирика","desc":"Período poético do início do séc. XX marcado por simbolismo, acmeísmo e expressividade emotiva profunda nas obras de Akhmatova e Tsvetaeva.","context":"Ex: \"Ахматова — яркая представительница Серебряного века. — \"Akhmatova é marcante representante da Era de Prata.\"\"","audio":"A Poesia da Era de Prata (Серебряный век)","level":"B2","module":"Módulo 14: Русская поэзия (Poesia Russa: Esenin, Akhmatova, Tsvetaeva)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Lirismo Natureza e Melancolia em Esenin","secondary":"Образ природы / Меланхолия","desc":"Sergei Esenin utilizava imagens rurais e melancólicas da natureza russa (\"русская природа\") para expressar sentimentos humanos.","context":"Ex: \"Есенин воспевал красоту родной природы. — \"Esenin cantava a beleza da natureza pátria.\"\"","audio":"Lirismo Natureza e Melancolia em Esenin","level":"B2","module":"Módulo 14: Русская поэзия (Poesia Russa: Esenin, Akhmatova, Tsvetaeva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Поэзия","secondary":"[ Poeziya ] — Poesia / Arte dos versos","desc":"","audio":"Поэзия","level":"B2","module":"Módulo 14: Русская поэзия (Poesia Russa: Esenin, Akhmatova, Tsvetaeva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Стих","secondary":"[ Stikh ] — Verso / Poema curto","desc":"","audio":"Стих","level":"B2","module":"Módulo 14: Русская поэзия (Poesia Russa: Esenin, Akhmatova, Tsvetaeva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Рифма","secondary":"[ Rifma ] — Rima poética","desc":"","audio":"Рифма","level":"B2","module":"Módulo 14: Русская поэзия (Poesia Russa: Esenin, Akhmatova, Tsvetaeva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Метафора","secondary":"[ Metafora ] — Metáfora figurada","desc":"","audio":"Метафора","level":"B2","module":"Módulo 14: Русская поэзия (Poesia Russa: Esenin, Akhmatova, Tsvetaeva)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вдохновение","secondary":"[ Vdokhnoveniye ] — Inspiração poética","desc":"","audio":"Вдохновение","level":"B2","module":"Módulo 14: Русская поэзия (Poesia Russa: Esenin, Akhmatova, Tsvetaeva)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Declarações Diplomáticas Oficiais","secondary":"Стороны подтвердили намерение + [Infinitivo]","desc":"Discursos de relações internacionais empregam estruturas consagradas: \"Стороны подтвердили намерение...\" (As partes confirmaram a intenção de...) e \"На основе взаимного уважения\" (Com base no respeito mútuo).","context":"Ex: \"Стороны подтвердили намерение развивать диалог. — \"As partes confirmaram a intenção de desenvolver o diálogo.\"\"","audio":"Declarações Diplomáticas Oficiais","level":"B2","module":"Módulo 15: Политика и международные отношения (Relações Internacionais)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Tratados Bilaterais e Cúpulas (Саммит)","secondary":"Двустороннее соглашение / Международный саммит","desc":"Usam-se \"Двустороннее соглашение\" (Acordo bilateral) e \"Саммит\" (Cúpula de líderes) para descrever eventos diplomáticos globais.","context":"Ex: \"На саммите подписано двустороннее соглашение. — \"Na cúpula foi assinado um acordo bilateral.\"\"","audio":"Tratados Bilaterais e Cúpulas (Саммит)","level":"B2","module":"Módulo 15: Политика и международные отношения (Relações Internacionais)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Direito Internacional e Soberania","secondary":"Суверенитет / Международное право","desc":"Fórmulas do direito global: \"Суверенитет\" (Soberania), \"В рамках международного права\" (No âmbito do direito internacional).","context":"Ex: \"Решение принято в рамках международного права. — \"A decisão foi tomada no âmbito do direito internacional.\"\"","audio":"Direito Internacional e Soberania","level":"B2","module":"Módulo 15: Политика и международные отношения (Relações Internacionais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Дипломатия","secondary":"[ Diplomatiya ] — Diplomacia / Relações externas","desc":"","audio":"Дипломатия","level":"B2","module":"Módulo 15: Политика и международные отношения (Relações Internacionais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Саммит","secondary":"[ Sammit ] — Cúpula / Encontro de líderes mundiais","desc":"","audio":"Саммит","level":"B2","module":"Módulo 15: Политика и международные отношения (Relações Internacionais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Суверенитет","secondary":"[ Suverenite ] — Soberania estatal","desc":"","audio":"Суверенитет","level":"B2","module":"Módulo 15: Политика и международные отношения (Relações Internacionais)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Terminologia de Inteligência Artificial e Redes Neurais","secondary":"Искусственный интеллект (ИИ) / Нейросеть","desc":"Na área de tecnologia em russo, usam-se \"Искусственный интеллект (ИИ)\" (Inteligência Artificial), \"Нейросеть\" (Rede Neural) e \"Машинное обучение\" (Aprendizado de Máquina).","context":"Ex: \"Нейросеть генерирует текст и изображения. — \"A rede neural gera texto e imagens.\"\"","audio":"Terminologia de Inteligência Artificial e Redes Neurais","level":"B2","module":"Módulo 16: Технологии и ИИ (Tecnologia e Inteligência Artificial)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Processamento de Dados e Algoritmos","secondary":"Обработка данных / База данных","desc":"Para tratar de computação e dados, usam-se \"Обработка данных\" (Processamento de dados), \"База данных\" (Banco de dados) e \"Алгоритм\".","context":"Ex: \"Алгоритм ускоряет обработку данных. — \"O algoritmo acelera o processamento de dados.\"\"","audio":"Processamento de Dados e Algoritmos","level":"B2","module":"Módulo 16: Технологии и ИИ (Tecnologia e Inteligência Artificial)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbos de Inovação Digital (Внедрять e Оптимизировать)","secondary":"Внедрять / Оптимизировать + [Acusativo]","desc":"Verbos técnicos de TI: \"внедрять\" (implementar/introduzir) e \"оптимизировать\" (otimizar processos).","context":"Ex: \"Разработчики внедряют новые методы защиты. — \"Os desenvolvedores implementam novos métodos de proteção.\"\"","audio":"Verbos de Inovação Digital (Внедрять e Оптимизировать)","level":"B2","module":"Módulo 16: Технологии и ИИ (Tecnologia e Inteligência Artificial)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Интеллект","secondary":"[ Intellekt ] — Inteligência (Искусственный интеллект = IA)","desc":"","audio":"Интеллект","level":"B2","module":"Módulo 16: Технологии и ИИ (Tecnologia e Inteligência Artificial)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Нейросеть","secondary":"[ Neyroset ] — Rede Neural / Modelo de IA","desc":"","audio":"Нейросеть","level":"B2","module":"Módulo 16: Технологии и ИИ (Tecnologia e Inteligência Artificial)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Алгоритм","secondary":"[ Algoritm ] — Algoritmo de computação","desc":"","audio":"Алгоритм","level":"B2","module":"Módulo 16: Технологии и ИИ (Tecnologia e Inteligência Artificial)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Данные","secondary":"[ Danneye ] — Dados / Informações computacionais","desc":"","audio":"Данные","level":"B2","module":"Módulo 16: Технологии и ИИ (Tecnologia e Inteligência Artificial)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Инновация","secondary":"[ Innovatsiya ] — Inovação tecnológica","desc":"","audio":"Инновация","level":"B2","module":"Módulo 16: Технологии и ИИ (Tecnologia e Inteligência Artificial)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conjunção Subordinada Concessiva (Несмотря на то что...)","secondary":"Несмотря на то что + [Oração 1], [Oração Principal 2]","desc":"Expressa uma concessão formal (\"apesar de que / embora\"). A oração principal ocorre contrariando a expectativa da oração subordinada.","context":"Ex: \"Несмотря на то чтошёл дождь, мы пошли гулять. — \"Apesar de estar chovendo, fomos passear.\"\"","audio":"Conjunção Subordinada Concessiva (Несмотря на то что...)","level":"B2","module":"Módulo 17: Сложный синтаксис (Sintaxe Avançada e Períodos Compostos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conjunções Causais Formais (В связи с тем что...)","secondary":"В связи с тем что / Ввиду того что + [Oração]","desc":"Em textos burocráticos e acadêmicos, \"В связи с тем что...\" (Em razão de que...) e \"Ввиду того что...\" substituem o simples \"Потому что\".","context":"Ex: \"В связи с тем что рейс отменён, мы остались. — \"Em razão de o voo ter sido cancelado, ficamos.\"\"","audio":"Conjunções Causais Formais (В связи с тем что...)","level":"B2","module":"Módulo 17: Сложный синтаксис (Sintaxe Avançada e Períodos Compostos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conjunção Integrante de Propósito (С тем чтобы...)","secondary":"С тем чтобы + [Infinitivo / Verbo no Passado]","desc":"Substitui \"Чтобы\" em registros de alta formalidade para indicar uma finalidade planejada com cuidado.","context":"Ex: \"Документы подписаны с тем чтобы ускорить проект. — \"Os documentos foram assinados com o intuito de acelerar o projeto.\"\"","audio":"Conjunção Integrante de Propósito (С тем чтобы...)","level":"B2","module":"Módulo 17: Сложный синтаксис (Sintaxe Avançada e Períodos Compostos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Несмотря","secondary":"[ Nesmotrya ] — Apesar de (Несмотря на то что = embora)","desc":"","audio":"Несмотря","level":"B2","module":"Módulo 17: Сложный синтаксис (Sintaxe Avançada e Períodos Compostos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Связь","secondary":"[ Svyaz ] — Relação / Conexão (В связи с = em razão de)","desc":"","audio":"Связь","level":"B2","module":"Módulo 17: Сложный синтаксис (Sintaxe Avançada e Períodos Compostos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Причина","secondary":"[ Prichina ] — Causa / Razão motivadora","desc":"","audio":"Причина","level":"B2","module":"Módulo 17: Сложный синтаксис (Sintaxe Avançada e Períodos Compostos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Следствие","secondary":"[ Sledstviye ] — Consequência / Efeito decorrente","desc":"","audio":"Следствие","level":"B2","module":"Módulo 17: Сложный синтаксис (Sintaxe Avançada e Períodos Compostos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Условие","secondary":"[ Usloviye ] — Condição necessária","desc":"","audio":"Условие","level":"B2","module":"Módulo 17: Сложный синтаксис (Sintaxe Avançada e Períodos Compostos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Registro Oficial-Corporativo (Официально-деловой стиль)","secondary":"Официально-деловой стиль / Книжная лексика","desc":"Estilo de leis, contratos e e-mails formais. Caracteriza-se por concisão, ausência de emotividade e uso de jargão burocrático (\"настоящий договор\", \"уведомлять\").","context":"Ex: \"Уведомляем вас о принятом решении. — \"Notificamos-lhe sobre a decisão tomada.\"\"","audio":"Registro Oficial-Corporativo (Официально-деловой стиль)","level":"B2","module":"Módulo 18: Стилистика русского языка (Estilística e Registros de Fala)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Registro Acadêmico e Jornalístico (Научный и публицистический)","secondary":"Научный стиль / Публицистика","desc":"Usado em teses e notícias. Foco na objetividade, clareza lógica e léxico erudito (\"согласно исследованию\", \"по данным экспертов\").","context":"Ex: \"Согласно исследованию, факт подтверждён. — \"Conforme o estudo, o fato foi confirmado.\"\"","audio":"Registro Acadêmico e Jornalístico (Научный и публицистический)","level":"B2","module":"Módulo 18: Стилистика русского языка (Estilística e Registros de Fala)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Registro Coloquial (Разговорный стиль)","secondary":"Разговорный стиль / Эмоциональность","desc":"Usado entre amigos e familiares. Permite diminutivos, abreviações e palavras emotivas (\"привет\", \"круто\", \"щас\").","context":"Ex: \"Привет! Как делишки? — \"Oi! Como vão as coisas?\"\"","audio":"Registro Coloquial (Разговорный стиль)","level":"B2","module":"Módulo 18: Стилистика русского языка (Estilística e Registros de Fala)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Стиль","secondary":"[ Stil ] — Estilo / Registro sociolinguístico","desc":"","audio":"Стиль","level":"B2","module":"Módulo 18: Стилистика русского языка (Estilística e Registros de Fala)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Официальный","secondary":"[ Ofitsialnyy ] — Formal / Oficial / Erudito","desc":"","audio":"Официальный","level":"B2","module":"Módulo 18: Стилистика русского языка (Estilística e Registros de Fala)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Разговорный","secondary":"[ Razgovornyy ] — Coloquial / Informal / Cotidiano","desc":"","audio":"Разговорный","level":"B2","module":"Módulo 18: Стилистика русского языка (Estilística e Registros de Fala)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Контекст","secondary":"[ Kontekst ] — Contexto de comunicação","desc":"","audio":"Контекст","level":"B2","module":"Módulo 18: Стилистика русского языка (Estilística e Registros de Fala)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Лексика","secondary":"[ Leksika ] — Léxico / Vocabulário selecionado","desc":"","audio":"Лексика","level":"B2","module":"Módulo 18: Стилистика русского языка (Estilística e Registros de Fala)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Provérbio de Cautela e Planejamento","secondary":"Семь раз отмерь, один раз отрежь","desc":"O ditado popular \"Семь раз отмерь, один раз отрежь\" (Meça sete vezes, corte uma) aconselha a refletir e planejar com extremo cuidado antes de tomar uma decisão irrevogável.","context":"Ex: \"Не спеши с решением: семь раз отмерь, один раз отрежь. — \"Não se apresse na decisão: meça 7 vezes, corte 1.\"\"","audio":"Provérbio de Cautela e Planejamento","level":"B2","module":"Módulo 19: Идиоматика высокого уровня (Expressões Idiomáticas Avançadas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Provérbio sobre Esforço e Conquista","secondary":"Без труда не выловишь и рыбу из пруда","desc":"O ditado \"Без труда не выловишь и рыбу из пруда\" (Sem trabalho não se tira nem peixe do lago) ensina que nenhuma conquista expressiva vem sem esforço dedicado.","context":"Ex: \"Нужно учиться: без труда не выловишь и рыбу из пруда. — \"É preciso estudar: sem esforço não se pesca peixe.\"\"","audio":"Provérbio sobre Esforço e Conquista","level":"B2","module":"Módulo 19: Идиоматика высокого уровня (Expressões Idiomáticas Avançadas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Locuções Idiomáticas Frequentes","secondary":"Делать из мухи слона / Бить баклуши","desc":"Usam-se expressões consolidadas como \"Делать из мухи слона\" (Fazer de uma mosca um elefante / tempestade em copo d'água) e \"Бить баклуши\" (Vadiar / Ficar sem fazer nada).","context":"Ex: \"Хватит бить баклуши, пора работать! — \"Chega de vadiar, hora de trabalhar!\"\"","audio":"Locuções Idiomáticas Frequentes","level":"B2","module":"Módulo 19: Идиоматика высокого уровня (Expressões Idiomáticas Avançadas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Пословица","secondary":"[ Poslovitsa ] — Provérbio / Ditado popular tradicional","desc":"","audio":"Пословица","level":"B2","module":"Módulo 19: Идиоматика высокого уровня (Expressões Idiomáticas Avançadas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Идиома","secondary":"[ Idioma ] — Expressão idiomática figurada","desc":"","audio":"Идиома","level":"B2","module":"Módulo 19: Идиоматика высокого уровня (Expressões Idiomáticas Avançadas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Мудрость","secondary":"[ Mudrost ] — Sabedoria moral","desc":"","audio":"Мудрость","level":"B2","module":"Módulo 19: Идиоматика высокого уровня (Expressões Idiomáticas Avançadas)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Смысл","secondary":"[ Smysl ] — Sentido / Significado profundo","desc":"","audio":"Смысл","level":"B2","module":"Módulo 19: Идиоматика высокого уровня (Expressões Idiomáticas Avançadas)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Abertura Formal de Discurso Público","secondary":"Уважаемая аудитория, позвольте представить + [Acusativo]","desc":"Discursos e apresentações perante um auditório abrem-se com \"Уважаемая аудитория...\" (Prezado público...) e \"Позвольте представить вам...\" (Permitam-me apresentar-lhes...).","context":"Ex: \"Позвольте представить тему нашей презентации. — \"Permitam-me apresentar o tema da nossa apresentação.\"\"","audio":"Abertura Formal de Discurso Público","level":"B2","module":"Módulo 20: Публичное выступление (Oratória e Discursos Públicos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Encadeamento Oratório de Pontos (Во-первых...)","secondary":"Во-первых, ... Во-вторых, ... / Перейдём к...","desc":"Estruturação lógica de tópicos em apresentações: \"Во-первых...\" (Em 1º lugar...), \"Во-вторых...\" (Em 2º lugar...), e a transição \"Перейдём к следующему пункту\" (Passemos ao próximo ponto).","context":"Ex: \"Перейдём к следующему пункту доклада. — \"Passemos ao próximo ponto do relatório.\"\"","audio":"Encadeamento Oratório de Pontos (Во-первых...)","level":"B2","module":"Módulo 20: Публичное выступление (Oratória e Discursos Públicos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Encerramento e Sessão de Perguntas","secondary":"Благодарю за внимание! / Отвечу на ваши вопросы","desc":"Fórmulas de fechamento polido: \"Благодарю за внимание!\" (Obrigado pela atenção!) e \"Я с удовольствием отвечу на ваши вопросы\" (Responderei com prazer a suas perguntas).","context":"Ex: \"Благодарю за внимание! Жду ваших вопросов. — \"Obrigado pela atenção! Fico no aguardo de suas perguntas.\"\"","audio":"Encerramento e Sessão de Perguntas","level":"B2","module":"Módulo 20: Публичное выступление (Oratória e Discursos Públicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Выступление","secondary":"[ Vystupleniye ] — Discurso / Apresentação em público","desc":"","audio":"Выступление","level":"B2","module":"Módulo 20: Публичное выступление (Oratória e Discursos Públicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Аудитория","secondary":"[ Auditoriya ] — Auditório / Público ouvinte","desc":"","audio":"Аудитория","level":"B2","module":"Módulo 20: Публичное выступление (Oratória e Discursos Públicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Презентация","secondary":"[ Prezentatsiya ] — Apresentação visual de slides","desc":"","audio":"Презентация","level":"B2","module":"Módulo 20: Публичное выступление (Oratória e Discursos Públicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Внимание","secondary":"[ Vnimaniye ] — Atenção (Благодарю за внимание!)","desc":"","audio":"Внимание","level":"B2","module":"Módulo 20: Публичное выступление (Oratória e Discursos Públicos)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Доклад","secondary":"[ Doklad ] — Palestra / Relatório oral formal","desc":"","audio":"Доклад","level":"B2","module":"Módulo 20: Публичное выступление (Oratória e Discursos Públicos)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Ganhar Tempo de Reflexão Elegante","secondary":"Это действительно важный вопрос... / Спасибо за вопрос...","desc":"Em entrevistas ao vivo sob pressão, ganha-se tempo para estruturar a resposta com frases de valorização: \"Это действительно важный вопрос...\" (Esta é realmente uma pergunta importante...) e \"Спасибо за интересную тему...\".","context":"Ex: \"Это действительно актуальный вопрос. — \"Esta é realmente uma pergunta atual.\"\"","audio":"Ganhar Tempo de Reflexão Elegante","level":"B2","module":"Módulo 21: Симуляция интервью (Simulação de Entrevista na Mídia Nativa)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Reformular Perguntas Hostis com Polidez","secondary":"Я бы сформулировал это иначе, ...","desc":"Para suavizar uma provocação, reformula-se o foco com \"Я бы сформулировал это иначе...\" (Eu formularia isto de outra forma...) e \"Главный аспект заключается в том, что...\".","context":"Ex: \"Я бы сформулировал этот вопрос иначе. — \"Eu formularia esta pergunta de outra forma.\"\"","audio":"Reformular Perguntas Hostis com Polidez","level":"B2","module":"Módulo 21: Симуляция интервью (Simulação de Entrevista na Mídia Nativa)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Síntese de Posicionamento Pessoal (Подводя итог)","secondary":"Подводя итог, хочу подчеркнуть, что...","desc":"Encerra-se a resposta em entrevista sintetizando a postura pessoal com \"Подводя итог, хочу подчеркнуть...\" (Sumarizando, quero destacar...).","context":"Ex: \"Подводя итог, наша позиция неизменна. — \"Sumarizando, nossa posição é inalterável.\"\"","audio":"Síntese de Posicionamento Pessoal (Подводя итог)","level":"B2","module":"Módulo 21: Симуляция интервью (Simulação de Entrevista na Mídia Nativa)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Интервью","secondary":"[ Intervyu ] — Entrevista de mídia (TV/Rádio)","desc":"","audio":"Интервью","level":"B2","module":"Módulo 21: Симуляция интервью (Simulação de Entrevista na Mídia Nativa)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Вопрос","secondary":"[ Vopros ] — Pergunta formulada","desc":"","audio":"Вопрос","level":"B2","module":"Módulo 21: Симуляция интервью (Simulação de Entrevista na Mídia Nativa)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Ответ","secondary":"[ Otvet ] — Resposta / Esclarecimento dado","desc":"","audio":"Ответ","level":"B2","module":"Módulo 21: Симуляция интервью (Simulação de Entrevista na Mídia Nativa)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Позиция","secondary":"[ Pozitsiya ] — Posicionamento / Postura oficial","desc":"","audio":"Позиция","level":"B2","module":"Módulo 21: Симуляция интервью (Simulação de Entrevista na Mídia Nativa)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Комментарий","secondary":"[ Kommentariy ] — Comentário / Esclarecimento","desc":"","audio":"Комментарий","level":"B2","module":"Módulo 21: Симуляция интервью (Simulação de Entrevista na Mídia Nativa)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Contraponto Argumentativo (С одной стороны..., с другой стороны...)","secondary":"С одной стороны, ... но с другой стороны, ...","desc":"Em ensaios e artigos de opinião, pesa-se os prós e contras com a antítese \"С одной стороны...\" (Por um lado...) e \"С другой стороны...\" (Por outro lado...).","context":"Ex: \"С одной стороны это плюсы, но с другой — минусы. — \"Por um lado são prós, por outro contras.\"\"","audio":"Contraponto Argumentativo (С одной стороны..., с другой стороны...)","level":"B2","module":"Módulo 22: Эссе и публицистика (Redação de Ensaios Pessoais)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Encadeamento Lógico de Argumentos","secondary":"Во-первых, ... Во-вторых, ... Следовательно, ...","desc":"Para encadear premissas no ensaio: \"Во-первых...\" (Em 1º lugar...), \"Во-вторых...\" (Em 2º lugar...), e a conclusão \"Следовательно...\" (Consequentemente...).","context":"Ex: \"Следовательно, выбор очевиден. — \"Consequentemente, a escolha é óbvia.\"\"","audio":"Encadeamento Lógico de Argumentos","level":"B2","module":"Módulo 22: Эссе и публицистика (Redação de Ensaios Pessoais)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Síntese Reflexiva da Tese","secondary":"Таким образом, мы приходим к выводу, что...","desc":"O parágrafo final do ensaio sintetiza os argumentos com \"Таким образом, мы приходим к выводу, что...\" (Deste modo, chegamos à conclusão de que...).","context":"Ex: \"Таким образом, тезис подтверждён. — \"Deste modo, a tese é confirmada.\"\"","audio":"Síntese Reflexiva da Tese","level":"B2","module":"Módulo 22: Эссе и публицистика (Redação de Ensaios Pessoais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Эссе","secondary":"[ Esse ] — Ensaio pessoal / Texto opinativo","desc":"","audio":"Эссе","level":"B2","module":"Módulo 22: Эссе и публицистика (Redação de Ensaios Pessoais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Тезис","secondary":"[ Tezis ] — Tese / Proposição defendida","desc":"","audio":"Тезис","level":"B2","module":"Módulo 22: Эссе и публицистика (Redação de Ensaios Pessoais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Аргумент","secondary":"[ Argument ] — Argumento / Prova fundamentada","desc":"","audio":"Аргумент","level":"B2","module":"Módulo 22: Эссе и публицистика (Redação de Ensaios Pessoais)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Контраргумент","secondary":"[ Kontrargument ] — Contra-argumento / Refutação","desc":"","audio":"Контраргумент","level":"B2","module":"Módulo 22: Эссе и публицистика (Redação de Ensaios Pessoais)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura do Exame Oficial ТРКИ-II / TORFL-2","secondary":"ТРКИ-2 / 5 субтестов","desc":"O exame de certificação oficial de nível B2 (ТРКИ-2) é dividido em 5 subtestes obrigatórios: Léxico/Gramática, Leitura de textos autênticos, Audição, Escrita e Fala.","context":"Ex: \"Экзамен состоит из пяти субтестов. — \"O exame é composto por cinco subtestes.\"\"","audio":"Estrutura do Exame Oficial ТРКИ-II / TORFL-2","level":"B2","module":"Módulo 23: Регламент и сертификация (Revisão Geral de Fluidez B2)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Checklist Sintático de Revisão B2","secondary":"Причастия + Деепричастия + Сложный синтаксис","desc":"Dominar a conversão fluida entre particípios (\"читающий / прочитанный\"), gerúndios (\"читая / прочитав\") e orações subordinadas concessivas (*Несмотря на то что*).","context":"Ex: \"Прочитав текст, напишите аннотацию. — \"Tendo lido o texto, escreva um resumo.\"\"","audio":"Checklist Sintático de Revisão B2","level":"B2","module":"Módulo 23: Регламент и сертификация (Revisão Geral de Fluidez B2)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Свободное владение языком (Fluência Avançada B2)","secondary":"Свободное владение + [Substantivo no Instrumental]","desc":"No nível B2, exige-se espontaneidade de fala, precisão de regência nos 6 casos e adequação ao registro de linguagem de cada situação social.","context":"Ex: \"Он свободно владеет русский языком. — \"Ele domina fluentemente a língua russa.\"\"","audio":"Свободное владение языком (Fluência Avançada B2)","level":"B2","module":"Módulo 23: Регламент и сертификация (Revisão Geral de Fluidez B2)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сертификация","secondary":"[ Sertifikatsiya ] — Certificação oficial de proficiência","desc":"","audio":"Сертификация","level":"B2","module":"Módulo 23: Регламент и сертификация (Revisão Geral de Fluidez B2)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Уровень","secondary":"[ Uroven ] — Nível de domínio (ex: B2)","desc":"","audio":"Уровень","level":"B2","module":"Módulo 23: Регламент и сертификация (Revisão Geral de Fluidez B2)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Владение","secondary":"[ Vladeniye ] — Domínio / Fluência no idioma","desc":"","audio":"Владение","level":"B2","module":"Módulo 23: Регламент и сертификация (Revisão Geral de Fluidez B2)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Регламент","secondary":"[ Reglament ] — Regulamento e regras do teste","desc":"","audio":"Регламент","level":"B2","module":"Módulo 23: Регламент и сертификация (Revisão Geral de Fluidez B2)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Síntese Integrada do Nível B2","secondary":"A1 + A2 + B1 + B2 ➔ 96 Módulos Concluídos","desc":"Consolidação total de particípios ativos/passivos, gerúndios imperfeitos/perfeitos, estilo oficial-corporativo, termos jurídicos, jornalismo e orações concessivas (*Несмотря на то что*).","context":"Ex: \"Вы отлично владеете русским языком! — \"Você domina perfeitamente o idioma russo!\"\"","audio":"Síntese Integrada do Nível B2","level":"B2","module":"Módulo 24: Desafio Final B2: Exame Integrado de Fluidez e Certificação Interna"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fluência Nativa e Adequação Estilística","secondary":"Adequação Estilística Total","desc":"Capacidade de alternar entre o estilo oficial-corporativo em documentos, acadêmico em relatórios e coloquial expressivo em conversas sociais.","context":"Ex: \"Уровень B2 подтверждён полностью. — \"Nível B2 confirmado totalmente.\"\"","audio":"Fluência Nativa e Adequação Estilística","level":"B2","module":"Módulo 24: Desafio Final B2: Exame Integrado de Fluidez e Certificação Interna"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Certificação Interna Idiomas Academy","secondary":"Selo de Proficiência B2 Conquistado!","desc":"Conquista do certificado máximo de proficiência avançada em russo da plataforma com aprovação no Exame Integrado.","context":"Ex: \"Поздравляем с победой! — \"Parabéns pela vitória!\"\"","audio":"Certificação Interna Idiomas Academy","level":"B2","module":"Módulo 24: Desafio Final B2: Exame Integrado de Fluidez e Certificação Interna"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Сертификат","secondary":"[ Sertifikat ] — Certificado de proficiência B2","desc":"","audio":"Сертификат","level":"B2","module":"Módulo 24: Desafio Final B2: Exame Integrado de Fluidez e Certificação Interna"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Победа","secondary":"[ Pobeda ] — Vitória / Conquista final","desc":"","audio":"Победа","level":"B2","module":"Módulo 24: Desafio Final B2: Exame Integrado de Fluidez e Certificação Interna"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Результат","secondary":"[ Rezultat ] — Resultado de excelência","desc":"","audio":"Результат","level":"B2","module":"Módulo 24: Desafio Final B2: Exame Integrado de Fluidez e Certificação Interna"}]);
